import { useCallback, useEffect, useState } from 'react'
import { Plus, RefreshCw, Save, Trash2 } from 'lucide-react'
import { EsPageChrome } from '@/components/design-system'
import { TABLES } from '@/constants/domain'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'
import { DEFAULT_ABOUT, getAboutContent, saveAboutContent } from '@/services/siteContent'

export default function AdminAboutEditor({ setToast }) {
  const [form, setForm] = useState({
    eyebrow: DEFAULT_ABOUT.eyebrow,
    title: DEFAULT_ABOUT.title,
    lead: DEFAULT_ABOUT.lead,
    body: DEFAULT_ABOUT.body,
    highlights: DEFAULT_ABOUT.highlights.map((h) => ({ ...h })),
  })
  const [loading, setLoading] = useState(true)
  const [busy, setBusy] = useState(false)

  const load = useCallback(async () => {
    setLoading(true)
    const { data, error, fallback } = await getAboutContent()
    if (error && !fallback) setToast?.(error.message)
    if (data) {
      setForm({
        eyebrow: data.eyebrow,
        title: data.title,
        lead: data.lead,
        body: data.body,
        highlights: (data.highlights || []).map((h) => ({ title: h.title || '', body: h.body || '' })),
      })
    }
    setLoading(false)
  }, [setToast])

  useEffect(() => {
    load()
  }, [load])

  useRealtimeTables([TABLES.SITE_ABOUT], () => load(), { channelName: 'es-admin-about' })

  const updateHighlight = (idx, key, value) => {
    setForm((f) => {
      const highlights = f.highlights.map((h, i) => (i === idx ? { ...h, [key]: value } : h))
      return { ...f, highlights }
    })
  }

  const addHighlight = () => {
    setForm((f) => ({
      ...f,
      highlights: [...f.highlights, { title: '', body: '' }],
    }))
  }

  const removeHighlight = (idx) => {
    setForm((f) => ({
      ...f,
      highlights: f.highlights.filter((_, i) => i !== idx),
    }))
  }

  async function save() {
    setBusy(true)
    const { error } = await saveAboutContent(form)
    setBusy(false)
    if (error) {
      setToast?.(
        /does not exist|schema cache|site_about/i.test(error.message || '')
          ? 'Run supabase/eventsphere-site-content.sql first'
          : error.message,
      )
      return
    }
    setToast?.('About page saved — live on /about')
    load()
  }

  return (
    <div data-testid="admin-about-editor">
      <EsPageChrome
        eyebrow="Public CMS"
        title="About page"
        description="Edit the guest About story. Changes publish instantly to /about."
        action={
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <button className="btn" type="button" onClick={load} disabled={loading || busy}>
              <RefreshCw size={14} /> Refresh
            </button>
            <button className="btn btn-primary" type="button" onClick={save} disabled={busy || loading} data-testid="button-save-about">
              <Save size={14} /> {busy ? 'Saving…' : 'Save About'}
            </button>
          </div>
        }
      />

      {loading ? (
        <p className="muted">Loading About content…</p>
      ) : (
        <div className="surface" style={{ padding: 22 }}>
          <div className="form-grid">
            <div>
              <label className="label">Eyebrow</label>
              <input
                className="input"
                value={form.eyebrow}
                onChange={(e) => setForm({ ...form, eyebrow: e.target.value })}
                data-testid="input-about-eyebrow"
              />
            </div>
            <div>
              <label className="label">Title</label>
              <input
                className="input"
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
                data-testid="input-about-title"
              />
            </div>
            <div className="full">
              <label className="label">Lead (hero line)</label>
              <textarea
                className="input"
                rows={3}
                value={form.lead}
                onChange={(e) => setForm({ ...form, lead: e.target.value })}
                data-testid="input-about-lead"
              />
            </div>
            <div className="full">
              <label className="label">Body (separate paragraphs with a blank line)</label>
              <textarea
                className="input"
                rows={8}
                value={form.body}
                onChange={(e) => setForm({ ...form, body: e.target.value })}
                data-testid="input-about-body"
              />
            </div>
          </div>

          <div style={{ marginTop: 22 }}>
            <div className="section-title">
              <h2 style={{ margin: 0 }}>Highlight cards</h2>
              <button className="btn btn-quiet" type="button" onClick={addHighlight}>
                <Plus size={14} /> Add card
              </button>
            </div>
            <div style={{ display: 'grid', gap: 12, marginTop: 12 }}>
              {form.highlights.map((h, idx) => (
                <div key={idx} className="surface" style={{ padding: 14, background: 'var(--overlay-soft)' }}>
                  <div className="form-grid">
                    <div>
                      <label className="label">Card title</label>
                      <input
                        className="input"
                        value={h.title}
                        onChange={(e) => updateHighlight(idx, 'title', e.target.value)}
                      />
                    </div>
                    <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'flex-end' }}>
                      <button className="btn btn-quiet" type="button" onClick={() => removeHighlight(idx)} aria-label="Remove card">
                        <Trash2 size={14} />
                      </button>
                    </div>
                    <div className="full">
                      <label className="label">Card body</label>
                      <textarea
                        className="input"
                        rows={2}
                        value={h.body}
                        onChange={(e) => updateHighlight(idx, 'body', e.target.value)}
                      />
                    </div>
                  </div>
                </div>
              ))}
              {!form.highlights.length ? (
                <p className="muted" style={{ margin: 0, fontSize: 13 }}>
                  No highlight cards yet.
                </p>
              ) : null}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { Mail, RefreshCw, Send } from 'lucide-react'
import { EsPageChrome } from '@/components/design-system'
import { TABLES } from '@/constants/domain'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'
import { sendCampusNotify, isEmailJsNotifyConfigured } from '@/lib/emailjs'
import {
  listAllContactMessages,
  replyToContactMessage,
} from '@/services/contact'

function formatWhen(iso) {
  if (!iso) return '—'
  try {
    return new Intl.DateTimeFormat(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    }).format(new Date(iso))
  } catch {
    return String(iso)
  }
}

export default function AdminContactInbox({ setToast }) {
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState('open')
  const [selectedId, setSelectedId] = useState(null)
  const [draft, setDraft] = useState('')
  const [busy, setBusy] = useState(false)

  const load = useCallback(async () => {
    setLoading(true)
    const { data, error } = await listAllContactMessages()
    if (error) setToast?.(error.message)
    setRows(data || [])
    setLoading(false)
  }, [setToast])

  useEffect(() => {
    load()
  }, [load])

  useRealtimeTables([TABLES.CONTACT_MESSAGES], () => load(), {
    channelName: 'es-admin-contact',
  })

  const filtered = useMemo(() => {
    if (filter === 'all') return rows
    return rows.filter((r) => r.status === filter)
  }, [rows, filter])

  const selected = useMemo(
    () => rows.find((r) => String(r.id) === String(selectedId)) || filtered[0] || null,
    [rows, selectedId, filtered],
  )

  useEffect(() => {
    if (selected && String(selectedId) !== String(selected.id)) {
      setSelectedId(selected.id)
      setDraft(selected.admin_reply || '')
    }
  }, [selected, selectedId])

  const counts = useMemo(() => {
    const open = rows.filter((r) => r.status === 'open').length
    const replied = rows.filter((r) => r.status === 'replied').length
    return { open, replied, all: rows.length }
  }, [rows])

  async function sendReply() {
    if (!selected?.id) return
    const reply = draft.trim()
    if (reply.length < 2) {
      setToast?.('Write a reply first')
      return
    }
    setBusy(true)
    const { data, error } = await replyToContactMessage({ id: selected.id, reply })
    if (error) {
      setBusy(false)
      setToast?.(error.message)
      return
    }

    let mailNote = ''
    if (isEmailJsNotifyConfigured && selected.email) {
      const { error: mailErr } = await sendCampusNotify({
        toEmail: selected.email,
        toName: selected.name || 'there',
        subject: `Re: ${selected.subject || 'Your EventSphere message'}`,
        title: 'EventSphere replied to your message',
        message: [
          `Hi ${selected.name || 'there'},`,
          '',
          'Campus admin replied to your Contact Us message:',
          '',
          reply,
          '',
          `Your original subject: ${selected.subject || 'General inquiry'}`,
          'You can also view this reply on the Contact page → Track reply.',
        ].join('\n'),
      })
      mailNote = mailErr ? ` (email failed: ${mailErr.message})` : ' · email sent'
    } else {
      mailNote = ' · email skipped (notify template not configured)'
    }

    setBusy(false)
    setToast?.(`Reply saved${mailNote}`)
    if (data) {
      setRows((prev) => prev.map((r) => (r.id === data.id ? data : r)))
      setDraft(data.admin_reply || reply)
    } else {
      load()
    }
  }

  return (
    <div className="es-admin-contact" data-testid="admin-contact-inbox">
      <EsPageChrome
        eyebrow="Public inbox"
        title="Contact messages"
        description="Replies save to the database, show on the Contact track panel, and email the sender."
        action={
          <button type="button" className="btn" onClick={load} disabled={loading}>
            <RefreshCw size={14} className={loading ? 'es-org-regs__spin' : ''} />
            Refresh
          </button>
        }
      />

      <div className="es-org-regs__chips" style={{ marginBottom: 14 }}>
        <span className="es-org-regs__chip-label">Status</span>
        {[
          { id: 'open', label: `Open (${counts.open})` },
          { id: 'replied', label: `Replied (${counts.replied})` },
          { id: 'all', label: `All (${counts.all})` },
        ].map((f) => (
          <button
            key={f.id}
            type="button"
            className={`chip ${filter === f.id ? 'active' : ''}`}
            onClick={() => setFilter(f.id)}
          >
            {f.label}
          </button>
        ))}
      </div>

      <div className="es-admin-contact__grid">
        <div className="surface es-admin-contact__list">
          {loading ? <p className="muted" style={{ padding: 16 }}>Loading…</p> : null}
          {!loading && !filtered.length ? (
            <p className="muted" style={{ padding: 16, margin: 0 }}>
              No messages in this filter.
            </p>
          ) : null}
          {filtered.map((m) => {
            const active = selected && String(selected.id) === String(m.id)
            return (
              <button
                key={m.id}
                type="button"
                className={`es-admin-contact__item ${active ? 'is-active' : ''}`}
                onClick={() => {
                  setSelectedId(m.id)
                  setDraft(m.admin_reply || '')
                }}
              >
                <div className="es-admin-contact__item-top">
                  <strong>{m.name}</strong>
                  <span className={`badge ${m.status === 'replied' ? 'badge-approved' : 'badge-pending'}`}>
                    {m.status}
                  </span>
                </div>
                <div className="muted" style={{ fontSize: 11 }}>{m.email}</div>
                <div className="es-admin-contact__preview">{m.subject || m.message}</div>
                <div className="subtle" style={{ fontSize: 10, marginTop: 6 }}>
                  {formatWhen(m.created_at)}
                </div>
              </button>
            )
          })}
        </div>

        <div className="surface es-admin-contact__detail">
          {!selected ? (
            <p className="muted" style={{ margin: 0 }}>Select a message to reply.</p>
          ) : (
            <>
              <div className="eyebrow">Conversation</div>
              <h2 className="display" style={{ margin: '8px 0 4px', fontSize: 22 }}>
                {selected.subject || 'General inquiry'}
              </h2>
              <p className="muted" style={{ fontSize: 12, marginBottom: 14 }}>
                <Mail size={12} style={{ verticalAlign: -1, marginRight: 4 }} />
                {selected.name} · {selected.email} · {formatWhen(selected.created_at)}
              </p>

              <div className="es-contact-bubble es-contact-bubble--you">
                <div className="subtle" style={{ fontSize: 10, marginBottom: 4 }}>Visitor</div>
                {selected.message}
              </div>

              {selected.admin_reply ? (
                <div className="es-contact-bubble es-contact-bubble--admin" style={{ marginTop: 12 }}>
                  <div className="subtle" style={{ fontSize: 10, marginBottom: 4 }}>
                    Your reply · {formatWhen(selected.replied_at)}
                  </div>
                  {selected.admin_reply}
                </div>
              ) : null}

              <label className="label" style={{ marginTop: 18 }}>Admin reply</label>
              <textarea
                className="input"
                rows={5}
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                placeholder="Write a clear campus reply…"
                data-testid="input-admin-contact-reply"
              />
              <button
                className="btn btn-primary"
                type="button"
                style={{ marginTop: 12 }}
                disabled={busy}
                onClick={sendReply}
                data-testid="button-admin-contact-reply"
              >
                <Send size={14} /> {busy ? 'Sending…' : selected.admin_reply ? 'Update & email reply' : 'Send reply'}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Pencil, Plus, RefreshCw, Trash2 } from 'lucide-react'
import { EsPageChrome } from '@/components/design-system'
import EsModal from '@/components/shared/EsModal'
import { TABLES } from '@/constants/domain'
import { useConfirmDialog } from '@/hooks/useConfirmDialog.jsx'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'
import {
  createFaq,
  deleteFaq,
  listAllFaqs,
  updateFaq,
} from '@/services/siteContent'

const emptyForm = { question: '', answer: '', sortOrder: 100, published: true }

export default function AdminFaqManager({ setToast }) {
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [open, setOpen] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(emptyForm)
  const [busy, setBusy] = useState(false)
  const { confirm, dialog: confirmUi } = useConfirmDialog()

  const load = useCallback(async () => {
    setLoading(true)
    const { data, error } = await listAllFaqs()
    if (error) {
      setToast?.(
        /does not exist|schema cache|site_faqs/i.test(error.message || '')
          ? 'Run supabase/eventsphere-site-content.sql first'
          : error.message,
      )
    }
    setRows(data || [])
    setLoading(false)
  }, [setToast])

  useEffect(() => {
    load()
  }, [load])

  useRealtimeTables([TABLES.SITE_FAQS], () => load(), { channelName: 'es-admin-faqs' })

  function openCreate() {
    setEditing(null)
    setForm({ ...emptyForm, sortOrder: (rows.length + 1) * 10 })
    setOpen(true)
  }

  function openEdit(row) {
    setEditing(row)
    setForm({
      question: row.question,
      answer: row.answer,
      sortOrder: row.sortOrder,
      published: row.published,
    })
    setOpen(true)
  }

  async function save() {
    if (!form.question.trim() || !form.answer.trim()) {
      setToast?.('Question and answer are required')
      return
    }
    setBusy(true)
    const payload = {
      question: form.question,
      answer: form.answer,
      sortOrder: Number(form.sortOrder) || 0,
      published: form.published,
    }
    const { error } = editing
      ? await updateFaq(editing.id, payload)
      : await createFaq(payload)
    setBusy(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    setToast?.(editing ? 'FAQ updated' : 'FAQ added')
    setOpen(false)
    load()
  }

  async function remove(row) {
    const ok = await confirm({
      title: 'Delete FAQ?',
      message: `"${row.question}" will be removed from the public FAQ page.`,
      confirmLabel: 'Delete FAQ',
      tone: 'danger',
    })
    if (!ok) return
    const { error } = await deleteFaq(row.id)
    if (error) setToast?.(error.message)
    else {
      setToast?.('FAQ deleted')
      load()
    }
  }

  async function togglePublished(row) {
    const { error } = await updateFaq(row.id, { published: !row.published })
    if (error) setToast?.(error.message)
    else load()
  }

  return (
    <div data-testid="admin-faq-manager">
      {confirmUi}
      <EsPageChrome
        eyebrow="Public CMS"
        title="FAQs"
        description="Manage accordion answers on /faq. Unpublished items stay hidden from guests."
        action={
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <button className="btn" type="button" onClick={load} disabled={loading}>
              <RefreshCw size={14} /> Refresh
            </button>
            <button className="btn btn-primary" type="button" onClick={openCreate} data-testid="button-add-faq">
              <Plus size={14} /> Add FAQ
            </button>
          </div>
        }
      />

      {loading ? (
        <p className="muted">Loading FAQs…</p>
      ) : !rows.length ? (
        <div className="surface" style={{ padding: 24 }}>
          <p className="muted" style={{ margin: 0 }}>
            No FAQs yet. Add one, or run <code>eventsphere-site-content.sql</code> to seed defaults.
          </p>
        </div>
      ) : (
        <div className="surface table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>Order</th>
                <th>Question</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.id}>
                  <td className="mono">{r.sortOrder}</td>
                  <td>
                    <strong>{r.question}</strong>
                    <br />
                    <span className="subtle" style={{ whiteSpace: 'normal' }}>
                      {r.answer.length > 120 ? `${r.answer.slice(0, 120)}…` : r.answer}
                    </span>
                  </td>
                  <td>
                    <button
                      type="button"
                      className={`chip ${r.published ? 'active' : ''}`}
                      onClick={() => togglePublished(r)}
                    >
                      {r.published ? 'Published' : 'Hidden'}
                    </button>
                  </td>
                  <td>
                    <div style={{ display: 'flex', gap: 6 }}>
                      <button className="btn btn-quiet" type="button" onClick={() => openEdit(r)} aria-label="Edit FAQ">
                        <Pencil size={14} />
                      </button>
                      <button className="btn btn-quiet" type="button" onClick={() => remove(r)} aria-label="Delete FAQ">
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {open ? (
        <EsModal title={editing ? 'Edit FAQ' : 'Add FAQ'} onClose={() => !busy && setOpen(false)}>
          <div className="form-grid">
            <div className="full">
              <label className="label">Question</label>
              <input
                className="input"
                value={form.question}
                onChange={(e) => setForm({ ...form, question: e.target.value })}
                data-testid="input-faq-question"
              />
            </div>
            <div className="full">
              <label className="label">Answer</label>
              <textarea
                className="input"
                rows={5}
                value={form.answer}
                onChange={(e) => setForm({ ...form, answer: e.target.value })}
                data-testid="input-faq-answer"
              />
            </div>
            <div>
              <label className="label">Sort order</label>
              <input
                className="input"
                type="number"
                value={form.sortOrder}
                onChange={(e) => setForm({ ...form, sortOrder: e.target.value })}
              />
            </div>
            <div>
              <label className="label">Visibility</label>
              <select
                className="input"
                value={form.published ? 'yes' : 'no'}
                onChange={(e) => setForm({ ...form, published: e.target.value === 'yes' })}
              >
                <option value="yes">Published</option>
                <option value="no">Hidden</option>
              </select>
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8, marginTop: 18, justifyContent: 'flex-end' }}>
            <button className="btn" type="button" disabled={busy} onClick={() => setOpen(false)}>
              Cancel
            </button>
            <button className="btn btn-primary" type="button" disabled={busy} onClick={save} data-testid="button-save-faq">
              {busy ? 'Saving…' : editing ? 'Update' : 'Create'}
            </button>
          </div>
        </EsModal>
      ) : null}
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { Check, Loader2, Plus, Trash2, Upload, Users } from 'lucide-react'
import { EsPageChrome } from '@/components/design-system'
import { useMascotLibrary } from '@/context/MascotLibraryContext'
import {
  createCampusMascot,
  deleteCampusMascot,
  updateCampusMascot,
  updateMascotExperienceSettings,
  uploadCampusMascotAsset,
} from '@/services/mascots'

function ToggleRow({ label, hint, checked, onChange, testId }) {
  return (
    <label
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: 16,
        padding: '14px 0',
        borderBottom: '1px solid var(--line)',
        fontSize: 12,
        cursor: 'pointer',
      }}
    >
      <span>
        <strong style={{ display: 'block', fontWeight: 600 }}>{label}</strong>
        {hint ? <span className="muted" style={{ fontSize: 11 }}>{hint}</span> : null}
      </span>
      <input type="checkbox" checked={checked} onChange={(e) => onChange(e.target.checked)} data-testid={testId} />
    </label>
  )
}

export default function AdminMascotLibrary({ setToast }) {
  const { library, settings, loading, refresh } = useMascotLibrary()
  const [label, setLabel] = useState('')
  const [imageUrl, setImageUrl] = useState('')
  const [busy, setBusy] = useState(false)
  const [uploadEnabled, setUploadEnabled] = useState(settings.student_upload_enabled !== false)
  const [maxMb, setMaxMb] = useState(settings.max_upload_mb || 2)
  const fileRef = useRef(null)

  useEffect(() => {
    setUploadEnabled(settings.student_upload_enabled !== false)
    setMaxMb(settings.max_upload_mb || 2)
  }, [settings])

  const reload = useCallback(async () => {
    await refresh({ includeDisabled: true })
  }, [refresh])

  useEffect(() => {
    reload()
  }, [reload])

  const onAdminUpload = async (e) => {
    const file = e.target.files?.[0]
    e.target.value = ''
    if (!file) return
    setBusy(true)
    const { data, error } = await uploadCampusMascotAsset(file)
    setBusy(false)
    if (error) {
      setToast?.(error.message || 'Upload failed')
      return
    }
    setImageUrl(data.publicUrl || '')
    setToast?.('Image uploaded — add a label and save to library')
  }

  const addMascot = async () => {
    if (!label.trim() || !imageUrl.trim()) {
      setToast?.('Label and image URL required')
      return
    }
    setBusy(true)
    const { error } = await createCampusMascot({ label: label.trim(), imageUrl: imageUrl.trim() })
    setBusy(false)
    if (error) {
      setToast?.(error.message || 'Could not add mascot')
      return
    }
    setLabel('')
    setImageUrl('')
    setToast?.('Mascot added to campus library')
