const COLOR_LABELS = ['Lead glow', 'Peak white', 'Accent flash']

function ToggleRow({ label, hint, checked, onChange, testId }) {
  return (
    <label
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: 16,
        padding: '14px 0',
