                              }
                            >
                              {busy ? '…' : 'Confirm'}
                            </button>
                          )}
                          {canDeposit && (
                            <button
                              className="btn"
                              type="button"
                              disabled={busy}
                              onClick={async () => {
                                const ok = await confirm({
                                  title: 'Refund deposit?',
                                  message: 'Refund the security deposit via Stripe sandbox for this booking?',
                                  confirmLabel: 'Refund deposit',
                                  tone: 'danger',
