export default function AdminThemeStudio({ setToast }) {
  const {
    config,
    updatePaletteColor,
    applyPreset,
    resetDefaults,
    syncStatus,
    syncError,
    persistNow,
  } = useThemeEngine()
  const [mode, setMode] = useState('dark')
  const [saved, setSaved] = useState(false)
  const [busy, setBusy] = useState(false)

  const palette = config[mode] || config.dark
  const warnings = useMemo(() => paletteContrastWarnings(palette), [palette])

  const confirmSave = async () => {
    setBusy(true)
    const { error } = await persistNow()
    setBusy(false)
    if (error) {
      setToast?.(error.message || 'Could not save campus theme')
      return
    }
    setSaved(true)
    setToast?.('Campus theme saved for all users')
    window.setTimeout(() => setSaved(false), 1600)
  }

  const onReset = async () => {
    resetDefaults()
    setToast?.('Theme reset to Midnight Campus — saving…')
    window.setTimeout(async () => {
      const { error } = await persistNow()
      if (error) setToast?.(error.message || 'Reset local; DB save failed')
      else setToast?.('Campus theme reset to defaults')
    }, 80)
  }

  return (
    <>
      <EsPageChrome
        eyebrow="Platform appearance"
        title="Theme studio"
        description="Control the shared EventSphere color system — stage glows, brand accents, and primary buttons. Both dark and light modes are stored campus-wide."
        action={
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <button type="button" className="btn btn-quiet" onClick={onReset} data-testid="button-theme-reset">
              <RotateCcw size={14} /> Reset defaults
            </button>
            <button
              type="button"
              className="btn btn-primary"
              disabled={busy || syncStatus === 'saving'}
              onClick={confirmSave}
              data-testid="button-theme-save"
            >
              {busy || syncStatus === 'saving' ? (
                <Loader2 size={14} style={{ animation: 'spin 0.9s linear infinite' }} />
              ) : saved ? (
                <Check size={14} />
              ) : (
                <Palette size={14} />
              )}
              {saved ? 'Saved' : 'Save to campus'}
            </button>
          </div>
        }
      />

      <div className="surface" style={{ padding: 21, marginBottom: 16 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <span
            style={{
              width: 40,
              height: 40,
              borderRadius: 14,
              display: 'grid',
              placeItems: 'center',
              background: 'linear-gradient(135deg, var(--es-hot), var(--es-ice))',
              color: '#07060c',
            }}
          >
            <Sparkles size={18} />
          </span>
          <SyncHint syncStatus={syncStatus} syncError={syncError} />
        </div>
      </div>

      <div className="surface" style={{ padding: 21, marginBottom: 16 }}>
        <div className="eyebrow">Presets</div>
        <h2 className="display" style={{ margin: '8px 0 12px', fontSize: 20 }}>Start from a pack</h2>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {Object.values(THEME_PRESETS).map((p) => (
            <button
              key={p.id}
              type="button"
              className={`chip ${config.preset === p.id ? 'active' : ''}`}
              onClick={() => {
                applyPreset(p.id)
                setToast?.(`Applied ${p.label}`)
              }}
              data-testid={`button-theme-preset-${p.id}`}
            >
              {p.label}
            </button>
          ))}
          {config.preset === 'custom' ? <span className="chip active">Custom</span> : null}
        </div>
      </div>

      <div style={{ display: 'flex', gap: 8, marginBottom: 14 }}>
        <button
          type="button"
          className={`chip ${mode === 'dark' ? 'active' : ''}`}
          onClick={() => setMode('dark')}
          data-testid="button-theme-mode-dark"
        >
          Edit dark mode
        </button>
        <button
          type="button"
          className={`chip ${mode === 'light' ? 'active' : ''}`}
          onClick={() => setMode('light')}
          data-testid="button-theme-mode-light"
        >
          Edit light mode
        </button>
      </div>

      <div className="surface" style={{ padding: 21, marginBottom: 16 }}>
        <div className="eyebrow">Live preview · {mode}</div>
        <h2 className="display" style={{ margin: '8px 0 12px', fontSize: 18 }}>Stage + button</h2>
        <StagePreview palette={palette} />
        {warnings.length ? (
          <ul style={{ margin: '12px 0 0', paddingLeft: 18, fontSize: 11, color: 'var(--danger)' }}>
            {warnings.map((w) => (
              <li key={w}>{w}</li>
            ))}
          </ul>
        ) : (
          <p className="muted" style={{ fontSize: 11, marginTop: 10 }}>
            Contrast looks OK for text and primary button on this mode.
          </p>
        )}
      </div>

      <div className="grid-2" style={{ gap: 16 }}>
        {THEME_FIELD_GROUPS.map((group) => (
          <div key={group.id} className="surface" style={{ padding: 21 }}>
            <div className="eyebrow">{group.title}</div>
            <h2 className="display" style={{ margin: '8px 0 14px', fontSize: 18 }}>{group.title}</h2>
            <div className="form-grid">
              {group.keys.map((key) => (
                <div key={key} className="full">
                  <ColorField
                    label={THEME_PALETTE_LABELS[key] || key}
                    value={palette[key]}
                    onChange={(hex) => updatePaletteColor(mode, key, hex)}
                    testId={`theme-${mode}-${key}`}
                  />
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { ASSIGNABLE_ROLES, ROLES } from '../../constants/roles'
import { TABLES } from '../../constants/domain'
import { useAuth } from '../../context/AuthContext'
import { getProfiles, updateProfileRole } from '../../services/profiles'
import { useRealtimeTables } from '../../hooks/useRealtimeTables'

/** Admin → Users / Organizers / Students: real Supabase profiles. */
export default function AdminUsersLive({ setToast, roleFilter = 'all' }) {
  const { user } = useAuth()
  const [profiles, setProfiles] = useState([])
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)
  const [savingId, setSavingId] = useState(null)

  const title =
    roleFilter === ROLES.ORGANIZER
      ? 'Organizers'
      : roleFilter === ROLES.USER
        ? 'Students'
        : roleFilter === ROLES.GUEST
          ? 'Public guests'
          : 'Users'

  const load = useCallback(async (opts = {}) => {
    const silent = Boolean(opts.silent)
    if (!silent) setLoading(true)
    setError('')
    const { data, error: err } = await getProfiles()
    if (err) setError(err.message)
    else setProfiles(data || [])
    if (!silent) setLoading(false)
  }, [])

  useEffect(() => {
    load()
  }, [load])

  useRealtimeTables([TABLES.PROFILES], () => load({ silent: true }), {
    channelName: 'es-admin-users',
  })

  async function changeRole(profile, nextRole) {
    if (profile.role === nextRole) return
    if (profile.id === user?.id && nextRole !== ROLES.ADMIN) {
      setError('You cannot demote yourself while signed in as admin.')
      return
    }
    setError('')
    setSavingId(profile.id)
    const { error: err } = await updateProfileRole(profile.id, nextRole)
    setSavingId(null)
    if (err) {
      setError(err.message)
      return
    }
    setToast?.(`${profile.email} → ${nextRole}`)
    await load()
  }

  const filtered =
    roleFilter === 'all'
      ? profiles
      : profiles.filter((p) => p.role === roleFilter)

  return (
    <>
      <div className="page-head">
        <div>
          <div className="eyebrow">People directory</div>
          <h1>{title}</h1>
          <p>
            {roleFilter === 'all'
              ? <>All profiles. Signup creates <code>user</code> (student) or <code>guest</code> (public). Only admins promote organizers.</>
              : roleFilter === ROLES.USER
                ? 'Campus student accounts (role user).'
                : roleFilter === ROLES.GUEST
                  ? 'Public guest accounts — hub-only access, no student dashboard or certificates.'
                  : 'Accounts with role organizer.'}
          </p>
        </div>
      </div>
      {error && (
        <p className="muted" style={{ color: 'var(--danger)', marginBottom: 12 }}>
          {error}
        </p>
      )}
      {loading ? (
        <p className="muted">Loading profiles…</p>
      ) : !filtered.length ? (
        <div className="surface" style={{ padding: 24 }}>
          <p className="muted" style={{ margin: 0 }}>No {title.toLowerCase()} found.</p>
        </div>
      ) : (
        <div className="surface table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>Role</th>
                <th>Department</th>
                <th>Joined</th>
                {roleFilter === 'all' && <th>Assign</th>}
              </tr>
            </thead>
            <tbody>
              {filtered.map((p) => (
                <tr key={p.id}>
                  <td>
                    <strong>{p.full_name || '—'}</strong>
                  </td>
                  <td>{p.email}</td>
                  <td>
                    <span className="badge badge-approved">{p.role}</span>
                  </td>
                  <td>{p.department || '—'}</td>
                  <td>{p.created_at ? new Date(p.created_at).toLocaleDateString() : '—'}</td>
                  {roleFilter === 'all' && (
                    <td>
                      <select
                        className="input"
                        style={{ width: 140, padding: '8px 10px' }}
                        value={p.role}
                        disabled={p.id === user?.id || savingId === p.id}
                        onChange={(e) => changeRole(p, e.target.value)}
                        aria-label={`Role for ${p.email}`}
                      >
                        {ASSIGNABLE_ROLES.map((r) => (
                          <option key={r} value={r}>
                            {r}
                          </option>
                        ))}
                      </select>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { Link } from 'wouter'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { EsBrandMark } from '@/components/design-system/EsBrandLogo'
import { CAMPUS_CHARACTERS } from '@/constants/campusCharacters'

const PULL_KEY = 'es_auth_pull_v2'
const MASCOT = CAMPUS_CHARACTERS.hero

function hasSeenPull() {
  try {
    return sessionStorage.getItem(PULL_KEY) === '1'
  } catch {
    return false
  }
}

function markPullSeen() {
  try {
    sessionStorage.setItem(PULL_KEY, '1')
  } catch {
    /* ignore */
  }
}

function OrbitDust({ reduce }) {
  const dots = useMemo(
    () =>
      Array.from({ length: 18 }, (_, i) => ({
        id: i,
        left: `${(i * 37) % 100}%`,
        top: `${(i * 53) % 100}%`,
        size: 2 + (i % 3),
        delay: (i % 7) * 0.35,
        dur: 4 + (i % 5),
      })),
    [],
  )
  if (reduce) return null
  return (
    <div className="es-auth__dust" aria-hidden>
      {dots.map((d) => (
        <span
          key={d.id}
          className="es-auth__dust-dot"
          style={{
            left: d.left,
            top: d.top,
            width: d.size,
            height: d.size,
            animationDelay: `${d.delay}s`,
            animationDuration: `${d.dur}s`,
          }}
        />
      ))}
    </div>
  )
}

export default function AuthStage({
  mode = 'login',
  mood = 'idle',
  eyebrow,
  title,
  subtitle,
  children,
  footer,
  testId = 'auth-stage',
}) {
  const reduce = useReducedMotion()
  const [playPull, setPlayPull] = useState(() => !reduce && !hasSeenPull())
  const [ready, setReady] = useState(() => reduce || hasSeenPull())
  const [phase, setPhase] = useState(() => (reduce || hasSeenPull() ? 'settled' : 'enter'))

  useEffect(() => {
    if (!playPull) {
      setReady(true)
      setPhase('settled')
      return undefined
    }
    setPhase('pull')
    const settle = window.setTimeout(() => {
      markPullSeen()
      setPlayPull(false)
      setReady(true)
      setPhase('settled')
    }, 2100)
    return () => window.clearTimeout(settle)
  }, [playPull])

  useEffect(() => {
    const html = document.documentElement
    html.classList.add('es-auth-lock')
    const prevBodyOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => {
      html.classList.remove('es-auth-lock')
      document.body.style.overflow = prevBodyOverflow
    }
  }, [])

  const skipPull = () => {
    markPullSeen()
    setPlayPull(false)
    setReady(true)
    setPhase('settled')
  }

  const mascotVariants = {
    enter: { x: -180, opacity: 0, rotate: -12, scale: 0.92 },
    pull: {
      x: [ -180, 24, -4, 0 ],
      opacity: 1,
      rotate: [ -12, 8, -2, 0 ],
      scale: 1,
      transition: { duration: 1.55, times: [0, 0.55, 0.82, 1], ease: 'easeOut' },
    },
    settled: {
      y: [0, -6, 0],
      transition: { duration: 4, repeat: Infinity, ease: 'easeInOut' },
    },
    error: {
      x: [0, -8, 8, -5, 5, 0],
      rotate: [0, -5, 5, -3, 0],
      transition: { duration: 0.5 },
    },
    busy: {
      y: [0, -5, 0],
      transition: { duration: 0.7, repeat: Infinity, ease: 'easeInOut' },
    },
  }

  const passVariants = {
    enter: { x: '16%', opacity: 0, rotate: 6, scale: 0.96 },
    pull: {
      x: ['16%', '-0.5%', '0%', '0%'],
      opacity: 1,
      rotate: [6, -1, 0, 0],
      scale: 1,
      transition: { duration: 1.65, delay: 0.18, times: [0, 0.62, 0.85, 1], ease: [0.16, 1, 0.3, 1] },
    },
    settled: { x: 0, opacity: 1, rotate: 0, scale: 1 },
  }

  const mascotState = reduce
    ? 'settled'
    : mood === 'error'
      ? 'error'
      : mood === 'busy'
        ? 'busy'
        : playPull
          ? 'pull'
          : phase === 'settled'
            ? 'settled'
            : 'enter'

  const passState = reduce ? 'settled' : playPull ? 'pull' : 'settled'

  const modeChip = {
    login: { href: '/signup', label: 'Need a seat? Sign up' },
    signup: { href: '/login', label: 'Have an account? Sign in' },
    verify: { href: '/login', label: 'Back to sign in' },
    forgot: { href: '/login', label: 'Back to sign in' },
  }[mode] || { href: '/login', label: 'Sign in' }

  const passCode = {
    login: 'RETURN PASS',
    signup: 'NEW PASS',
    verify: 'VERIFY PASS',
    forgot: 'RECOVERY',
  }[mode] || 'CAMPUS PASS'

  const line =
    mood === 'error'
      ? 'That didn’t lock — try again.'
      : mood === 'busy'
        ? 'Aligning your orbit…'
        : mode === 'signup'
          ? 'Grabbing your boarding pass…'
          : mode === 'verify'
            ? 'Scanning your orbit code…'
            : mode === 'forgot'
              ? 'Opening the recovery airlock…'
              : 'Hauling the gate open for you.'

  return (
    <div
      className={`es-auth es-public es-auth--${mode} es-auth--${mood}`}
      data-testid={testId}
      data-phase={phase}
    >
      <div className="es-auth__sky" aria-hidden>
        <div className="es-auth__grid" />
        <div className="es-auth__blob es-auth__blob--a" />
        <div className="es-auth__blob es-auth__blob--b" />
        <div className="es-auth__blob es-auth__blob--c" />
        <OrbitDust reduce={reduce} />
        <div className="es-auth__rings">
          <span className="es-auth__ring es-auth__ring--1" />
          <span className="es-auth__ring es-auth__ring--2" />
          <span className="es-auth__ring es-auth__ring--3" />
        </div>
      </div>

      <div className="es-auth__top">
        <Link href="/" className="es-auth__brand" aria-label="EventSphere home">
          <EsBrandMark cycle={0} />
          <span className="es-auth__brand-copy">
            <span className="es-auth__brand-name">EventSphere</span>
            <span className="es-auth__brand-tag">Orbital gate</span>
          </span>
        </Link>
        <div className="es-auth__top-actions">
          {playPull ? (
            <button type="button" className="es-auth__ghost-btn" onClick={skipPull}>
              Skip intro
            </button>
          ) : null}
          <Link href={modeChip.href} className="es-auth__mode-chip">
            {modeChip.label}
          </Link>
        </div>
      </div>

      <div className="es-auth__canvas">
        <motion.aside
          className="es-auth__guide"
          initial={reduce ? false : 'enter'}
          animate={mascotState}
          variants={mascotVariants}
        >
          <div className="es-auth__guide-aura" />
          <img className="es-auth__mascot" src={MASCOT.src} alt={MASCOT.alt} draggable={false} />
          <AnimatePresence mode="wait">
            <motion.p
              key={line}
              className="es-auth__speech"
              initial={{ opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -4 }}
              transition={{ duration: 0.25 }}
            >
              {line}
            </motion.p>
          </AnimatePresence>

          {!reduce ? (
            <svg className="es-auth__tow" viewBox="0 0 220 40" aria-hidden>
              <motion.path
                d="M4 20 C 60 4, 140 36, 216 18"
                fill="none"
                stroke="url(#esTowGrad)"
                strokeWidth="2.4"
                strokeLinecap="round"
                strokeDasharray="5 7"
                animate={
                  playPull
                    ? { pathLength: [0, 1], opacity: [0, 1, 0.7] }
                    : { pathLength: 1, opacity: 0.35 }
                }
                transition={playPull ? { duration: 1.1, delay: 0.35 } : { duration: 0.4 }}
              />
              <defs>
                <linearGradient id="esTowGrad" x1="0" y1="0" x2="1" y2="0">
                  <stop offset="0%" stopColor="#5ce1ff" />
                  <stop offset="100%" stopColor="#7dffb3" />
                </linearGradient>
              </defs>
            </svg>
          ) : null}
        </motion.aside>

        <motion.section
          className="es-auth__pass"
          initial={reduce ? false : 'enter'}
          animate={passState}
          variants={passVariants}
          style={{ pointerEvents: ready ? 'auto' : 'none' }}
        >
          <div className="es-auth__pass-sheen" aria-hidden />
          <div className="es-auth__pass-edge" aria-hidden />
          <div className="es-auth__pass-punch" aria-hidden />

          <div className="es-auth__pass-body">
            <div className="es-auth__pass-head">
              <span className="es-auth__pass-code">{passCode}</span>
              <span className="es-auth__pass-orbit">CAMPUS ORBIT · LIVE</span>
            </div>

            {eyebrow ? <div className="es-auth__kicker">{eyebrow}</div> : null}
            <AnimatePresence mode="wait">
              <motion.h1
                key={title}
                className="es-auth__headline"
                initial={reduce ? false : { opacity: 0, y: 12, filter: 'blur(6px)' }}
                animate={{ opacity: 1, y: 0, filter: 'blur(0px)' }}
                exit={{ opacity: 0, y: -8 }}
                transition={{ duration: 0.35 }}
              >
                {title}
              </motion.h1>
            </AnimatePresence>
            {subtitle ? <p className="es-auth__lede">{subtitle}</p> : null}

            <motion.div
              className="es-auth__body"
              initial={reduce ? false : { opacity: 0 }}
              animate={{ opacity: ready ? 1 : 0.35 }}
              transition={{ delay: playPull ? 1.1 : 0, duration: 0.35 }}
            >
              {children}
            </motion.div>

            {footer ? <div className="es-auth__footer">{footer}</div> : null}
          </div>
        </motion.section>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link, useLocation } from 'wouter'
import { ArrowLeft, ArrowRight, KeyRound, Mail } from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import { isEmailJsConfigured } from '@/lib/emailjs'
import {
  completePasswordReset,
  requestPasswordResetOtp,
} from '@/services/passwordReset'
