const RESET_EMAIL_KEY = 'es_reset_email'

export default function ForgotPasswordForm() {
  const { user, loading } = useAuth()
  const [, setLocation] = useLocation()
  const [step, setStep] = useState(1)
  const [email, setEmail] = useState('')
  const [otp, setOtp] = useState('')
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [showPw, setShowPw] = useState(false)
  const [busy, setBusy] = useState(false)
  const [sending, setSending] = useState(false)
  const [message, setMessage] = useState('')
  const [error, setError] = useState('')

  useEffect(() => {
    if (!loading && user) setLocation('/login')
  }, [loading, user, setLocation])

  useEffect(() => {
    try {
      const saved = sessionStorage.getItem(RESET_EMAIL_KEY)
      if (saved) setEmail(saved)
    } catch {
      /* ignore */
    }
  }, [])

  async function sendOtp(e) {
    e?.preventDefault?.()
    setError('')
    setMessage('')
    if (!isEmailJsConfigured) {
      setError('EmailJS is not configured in .env')
      return
    }
    setSending(true)
    const { error: err, toEmail } = await requestPasswordResetOtp(email)
    setSending(false)
    if (err) {
      setError(err.message)
      return
    }
    try {
      sessionStorage.setItem(RESET_EMAIL_KEY, toEmail)
    } catch {
      /* ignore */
    }
    setMessage(
      'If an account exists for that email, a 6-digit recovery code was sent. Check inbox and spam.',
    )
    setStep(2)
  }

  async function handleReset(e) {
    e.preventDefault()
    setError('')
    setMessage('')
    if (password.length < 6) {
      setError('Password must be at least 6 characters.')
      return
    }
    if (password !== confirm) {
      setError('Passwords do not match.')
      return
    }
    setBusy(true)
    const { ok, error: err } = await completePasswordReset({ email, otp, newPassword: password })
    setBusy(false)
    if (err) {
      setError(err.message)
      return
    }
    if (!ok) {
      setError('Invalid or expired code. Request a new one and try again.')
      return
    }
    try {
      sessionStorage.removeItem(RESET_EMAIL_KEY)
    } catch {
      /* ignore */
    }
    setMessage('Password updated. Sign in with your new password.')
    setTimeout(() => setLocation('/login'), 1400)
  }

  const mood = error ? 'error' : busy || sending ? 'busy' : message && step === 1 ? 'idle' : 'idle'

  if (loading) {
    return (
      <AuthStage mode="forgot" mood="busy" title="Loading…" subtitle="">
        <p className="muted">Checking session…</p>
      </AuthStage>
    )
  }

  if (user) return null

  return (
    <AuthStage
      mode="forgot"
      mood={mood}
      eyebrow="Recovery airlock"
      title={step === 1 ? 'Reset your passcode' : 'Set a new password'}
      subtitle={
        step === 1
          ? 'We email a one-time 6-digit code via your existing EmailJS setup — no paid add-ons.'
          : `Enter the code sent to ${email || 'your email'} and choose a new password.`
      }
      footer={
        <p className="muted es-auth__foot-note">
          <Link href="/login">Back to sign in</Link>
          {' · '}
          <Link href="/signup">Create account</Link>
          {' · '}
          <Link href="/">Public home</Link>
        </p>
      }
    >
      <div className="es-auth__steps" aria-hidden>
        <span className={`es-auth__step ${step >= 1 ? 'is-on' : ''}`} />
        <span className={`es-auth__step ${step >= 2 ? 'is-on' : ''}`} />
      </div>

      {!isEmailJsConfigured && (
        <p className="es-auth__alert es-auth__alert--danger">
          Add EmailJS keys to <code>.env</code> before using password reset.
        </p>
      )}

      {step === 1 ? (
        <form onSubmit={sendOtp}>
          <label className="label" htmlFor="forgot-email">
            Account email
          </label>
          <div className="es-auth__input-wrap">
            <Mail size={16} className="es-auth__input-icon" aria-hidden />
            <input
              id="forgot-email"
              className="input es-auth__input--icon"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              autoComplete="email"
              placeholder="you@email.com"
            />
          </div>
          {error ? <p className="es-auth__alert es-auth__alert--danger">{error}</p> : null}
          {message ? <p className="es-auth__alert es-auth__alert--ok">{message}</p> : null}
          <button
            type="submit"
            className="btn btn-primary"
            style={{ width: '100%', marginTop: 18 }}
            disabled={sending}
          >
            {sending ? 'Sending code…' : <>Send recovery code <ArrowRight size={15} /></>}
          </button>
        </form>
      ) : (
        <form onSubmit={handleReset}>
          <label className="label" htmlFor="forgot-otp">
            Recovery code
          </label>
          <input
            id="forgot-otp"
            className="input es-auth__otp"
            inputMode="numeric"
            maxLength={6}
            value={otp}
            onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
            required
            autoComplete="one-time-code"
            placeholder="000000"
          />
          <label className="label" htmlFor="forgot-password">
            New password
          </label>
          <div className="es-auth__input-wrap">
            <KeyRound size={16} className="es-auth__input-icon" aria-hidden />
            <input
              id="forgot-password"
              className="input es-auth__input--icon es-auth__input--pw"
              type={showPw ? 'text' : 'password'}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              minLength={6}
              required
              autoComplete="new-password"
            />
            <button
              type="button"
              className="es-auth__pw-toggle"
              onClick={() => setShowPw((v) => !v)}
              aria-label={showPw ? 'Hide password' : 'Show password'}
            >
              {showPw ? 'Hide' : 'Show'}
            </button>
          </div>
          <label className="label" htmlFor="forgot-confirm">
            Confirm password
          </label>
          <input
            id="forgot-confirm"
            className="input"
            type={showPw ? 'text' : 'password'}
            value={confirm}
            onChange={(e) => setConfirm(e.target.value)}
            minLength={6}
            required
            autoComplete="new-password"
          />
          {error ? <p className="es-auth__alert es-auth__alert--danger">{error}</p> : null}
          {message ? <p className="es-auth__alert es-auth__alert--ok">{message}</p> : null}
          <div style={{ display: 'flex', gap: 8, marginTop: 18 }}>
            <button
              type="button"
              className="btn"
              onClick={() => {
                setError('')
                setMessage('')
                setStep(1)
              }}
            >
              <ArrowLeft size={14} /> Back
            </button>
            <button
              type="submit"
              className="btn btn-primary"
              style={{ flex: 1 }}
              disabled={busy || otp.length !== 6}
            >
              {busy ? 'Updating…' : <>Save new password <ArrowRight size={15} /></>}
            </button>
          </div>
          <button
            type="button"
            className="btn es-auth__link-btn"
            style={{ width: '100%', marginTop: 10 }}
            disabled={sending}
            onClick={sendOtp}
          >
            {sending ? 'Sending…' : 'Resend recovery code'}
          </button>
        </form>
      )}
    </AuthStage>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { Link, useLocation } from 'wouter'
import { ArrowLeft, ArrowRight, KeyRound, Mail } from 'lucide-react'
import { useAuth } from '../../context/AuthContext'
import { isEmailJsConfigured } from '../../lib/emailjs'
import { STUDENT_INTERESTS } from '@/constants/domain'
import { readIntentFromSearch, readNextFromSearch, stashAuthNext } from '@/lib/authReturn'
import {
  passwordStrengthHints,
  validateSignupStep1,
  validateSignupStep2,
} from '@/lib/authValidation'
import AuthStage from '@/components/auth/AuthStage'

function FieldError({ message }) {
  if (!message) return null
  return <p className="es-auth__field-error">{message}</p>
}

export default function SignupForm() {
  const { signUp } = useAuth()
  const [, setLocation] = useLocation()
  const search = typeof window !== 'undefined' ? window.location.search : ''
  const intentGuest = useMemo(() => readIntentFromSearch(search) === 'guest', [search])
  const [step, setStep] = useState(1)
  const [fullName, setFullName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [mobile, setMobile] = useState('')
  const [department, setDepartment] = useState('')
  const [enrollmentNo, setEnrollmentNo] = useState('')
  const [interests, setInterests] = useState([])
  const [error, setError] = useState('')
  const [fieldErrors, setFieldErrors] = useState({})
  const [busy, setBusy] = useState(false)

  const pwHints = useMemo(() => passwordStrengthHints(password), [password])

  useEffect(() => {
    const next = readNextFromSearch(search)
    if (next) stashAuthNext(next)
  }, [search])

  const loginHref = (() => {
    const next = readNextFromSearch(search)
    const base = next ? `/login?next=${encodeURIComponent(next)}` : '/login'
    return intentGuest ? `${base}${base.includes('?') ? '&' : '?'}intent=guest` : base
  })()

  const toggleInterest = (tag) => {
    setInterests((prev) => {
      if (prev.includes(tag)) return prev.filter((t) => t !== tag)
      if (prev.length >= 8) return prev
      return [...prev, tag]
    })
    setFieldErrors((prev) => {
      if (!prev.interests) return prev
      const next = { ...prev }
      delete next.interests
      return next
    })
  }

  function clearFieldError(key) {
    setFieldErrors((prev) => {
      if (!prev[key]) return prev
      const next = { ...prev }
      delete next[key]
      return next
    })
    if (error) setError('')
  }

  function goNextStep(e) {
    e.preventDefault()
    setError('')
    const result = validateSignupStep1({ fullName, email, password, intentGuest })
    if (!result.ok) {
      setFieldErrors(result.errors)
      setError(result.firstError)
      return
    }
    setFieldErrors({})
    setStep(2)
  }

  async function handleSubmit(e) {
    e.preventDefault()
    setError('')
    const step1 = validateSignupStep1({ fullName, email, password, intentGuest })
    if (!step1.ok) {
      setFieldErrors(step1.errors)
      setError(step1.firstError)
      setStep(1)
      return
    }
    const step2 = validateSignupStep2({ mobile, intentGuest, interests })
    if (!step2.ok) {
      setFieldErrors(step2.errors)
      setError(step2.firstError)
      return
    }
    setFieldErrors({})
    setBusy(true)
    const { data, error: err } = await signUp({
      email: email.trim(),
      password,
      fullName: fullName.trim(),
      mobile,
      department,
      enrollmentNo: intentGuest ? '' : enrollmentNo,
      interests: intentGuest ? [] : interests,
      intent: intentGuest ? 'guest' : 'student',
    })
    setBusy(false)
    if (err) {
      setError(err.message)
      return
    }
    if (data?.user && !data.session) {
      setError(
        'Supabase Confirm email is still ON. Turn it OFF: Authentication → Providers → Email → Confirm email.',
      )
      return
    }
    setLocation('/verify-email')
  }

  return (
    <AuthStage
      mode="signup"
      mood={error ? 'error' : busy ? 'busy' : 'idle'}
      eyebrow={intentGuest ? 'Public guest pass' : 'Issue a new pass'}
      title={intentGuest ? 'Join as a public guest' : 'Claim your campus seat'}
      subtitle={
        intentGuest
          ? 'Public guests — OTP confirm, then your guest hub.'
          : 'Campus email required. Organizer access is granted by admin.'
      }
      footer={
        <p className="muted es-auth__foot-note" style={{ margin: 0 }}>
          Already have an account? <Link href={loginHref}>Sign in</Link>
          {' · '}
          <Link href="/forgot-password">Forgot password?</Link>
          {' · '}
          <Link href="/">Public home</Link>
          {!intentGuest ? (
            <>
              {' · '}
              <Link href="/signup?intent=guest">Continue as guest</Link>
            </>
          ) : (
            <>
              {' · '}
              <Link href="/signup">Campus student signup</Link>
            </>
          )}
        </p>
      }
    >
      <div className="es-auth__steps" aria-hidden>
        <span className={`es-auth__step ${step >= 1 ? 'is-on' : ''}`} />
        <span className={`es-auth__step ${step >= 2 ? 'is-on' : ''}`} />
      </div>

      {!isEmailJsConfigured && (
        <p className="es-auth__alert es-auth__alert--danger" style={{ marginBottom: 12 }}>
          Add EmailJS keys to <code>.env</code> before signup.
        </p>
      )}

      {step === 1 ? (
        <form onSubmit={goNextStep} noValidate>
          <label className="label" htmlFor="signup-name">
            Full name
          </label>
          <input
            id="signup-name"
            className={`input ${fieldErrors.fullName ? 'is-invalid' : ''}`}
            value={fullName}
            onChange={(e) => {
              setFullName(e.target.value)
              clearFieldError('fullName')
            }}
            required
            autoComplete="name"
            placeholder="Your full name"
            aria-invalid={Boolean(fieldErrors.fullName)}
          />
          <FieldError message={fieldErrors.fullName} />

          <label className="label" htmlFor="signup-email">
            Email
          </label>
          <div className="es-auth__input-wrap">
            <Mail size={16} className="es-auth__input-icon" aria-hidden />
            <input
              id="signup-email"
              className={`input es-auth__input--icon ${fieldErrors.email ? 'is-invalid' : ''}`}
              type="email"
              value={email}
              onChange={(e) => {
                setEmail(e.target.value)
                clearFieldError('email')
              }}
              required
              autoComplete="email"
              placeholder="you@email.com"
              aria-invalid={Boolean(fieldErrors.email)}
            />
          </div>
          <FieldError message={fieldErrors.email} />

          <label className="label" htmlFor="signup-password">
            Password
          </label>
          <div className="es-auth__input-wrap">
            <KeyRound size={16} className="es-auth__input-icon" aria-hidden />
            <input
              id="signup-password"
              className={`input es-auth__input--icon ${fieldErrors.password ? 'is-invalid' : ''}`}
              type="password"
              value={password}
              onChange={(e) => {
                setPassword(e.target.value)
                clearFieldError('password')
              }}
              minLength={8}
              required
              autoComplete="new-password"
              placeholder="Min. 8 chars, letter + number"
              aria-invalid={Boolean(fieldErrors.password)}
            />
          </div>
          <FieldError message={fieldErrors.password} />
          {password ? (
            <ul className="es-auth__pw-hints" aria-live="polite">
              {pwHints.map((h) => (
                <li key={h.key} className={h.ok ? 'is-ok' : 'is-bad'}>
                  {h.ok ? '✓' : '○'} {h.label}
                </li>
              ))}
            </ul>
          ) : null}

          {error ? <p className="es-auth__alert es-auth__alert--danger">{error}</p> : null}
          <button type="submit" className="btn btn-primary es-auth__submit">
            Continue <ArrowRight size={15} />
          </button>
        </form>
      ) : (
        <form onSubmit={handleSubmit} noValidate>
          <label className="label" htmlFor="signup-mobile">
            Mobile / phone
          </label>
          <input
            id="signup-mobile"
            className={`input ${fieldErrors.mobile ? 'is-invalid' : ''}`}
            value={mobile}
            onChange={(e) => {
              setMobile(e.target.value)
              clearFieldError('mobile')
            }}
            placeholder={intentGuest ? '03XXXXXXXXX' : 'Optional · 03XXXXXXXXX'}
            inputMode="tel"
            data-testid="input-signup-mobile"
            aria-invalid={Boolean(fieldErrors.mobile)}
          />
          <FieldError message={fieldErrors.mobile} />

          {!intentGuest ? (
            <>
              <label className="label" htmlFor="signup-department">
                Department
              </label>
              <input
                id="signup-department"
                className="input"
                value={department}
                onChange={(e) => setDepartment(e.target.value)}
                placeholder="e.g. Computer Science"
                data-testid="input-signup-department"
              />
              <label className="label" htmlFor="signup-enrollment">
                Enrollment no.
              </label>
              <input
                id="signup-enrollment"
                className="input"
                value={enrollmentNo}
                onChange={(e) => setEnrollment(e.target.value)}
                placeholder="Optional"
                data-testid="input-signup-enrollment"
              />
              <label className="label">Your interests</label>
              <p className="muted" style={{ fontSize: 11, margin: '4px 0 8px' }}>
                Pick up to 8 — we will recommend matching campus events.
              </p>
              <div className="chips" style={{ flexWrap: 'wrap', gap: 8 }} data-testid="signup-interests">
                {STUDENT_INTERESTS.map((tag) => (
                  <button
                    key={tag}
                    type="button"
                    className={`chip ${interests.includes(tag) ? 'active' : ''}`}
                    onClick={() => toggleInterest(tag)}
                    data-testid={`chip-interest-${tag.toLowerCase()}`}
                  >
                    {tag}
                  </button>
                ))}
              </div>
              <FieldError message={fieldErrors.interests} />
            </>
          ) : (
            <>
              <label className="label" htmlFor="signup-guest-org">
                Organization / relation (optional)
              </label>
              <input
                id="signup-guest-org"
                className="input"
                value={department}
                onChange={(e) => setDepartment(e.target.value)}
                placeholder="e.g. Parent · Teacher · Visitor"
                data-testid="input-signup-guest-org"
              />
            </>
          )}
          {error ? <p className="es-auth__alert es-auth__alert--danger">{error}</p> : null}
          <div style={{ display: 'flex', gap: 8, marginTop: 16 }}>
            <button type="button" className="btn" onClick={() => { setError(''); setFieldErrors({}); setStep(1) }}>
              <ArrowLeft size={14} /> Back
            </button>
            <button
              type="submit"
              className="btn btn-primary"
              style={{ flex: 1 }}
              disabled={busy}
            >
              {busy ? 'Creating…' : <>{intentGuest ? 'Create guest account' : 'Create account'} <ArrowRight size={15} /></>}
            </button>
          </div>
        </form>
      )}
    </AuthStage>
  )
}

import { useEffect, useRef, useState } from 'react'
import { Link, useLocation } from 'wouter'
import { ArrowRight, Mail } from 'lucide-react'
import { useAuth } from '../../context/AuthContext'
import { homePathForRole } from '../../constants/roles'
import { sendEmailOtp, verifyEmailOtp } from '../../services/emailOtp'
import { isEmailJsConfigured } from '../../lib/emailjs'
import { resolvePostAuthPath } from '@/lib/authReturn'
import AuthStage from '@/components/auth/AuthStage'

export default function VerifyForm() {
  const { profile, user, loading, signOut, refreshProfile } = useAuth()
  const [, setLocation] = useLocation()
  const [otp, setOtp] = useState('')
  const [busy, setBusy] = useState(false)
  const [sending, setSending] = useState(false)
  const [message, setMessage] = useState('')
  const [error, setError] = useState('')
  const autoSent = useRef(false)

  useEffect(() => {
    if (user) refreshProfile()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user])

  useEffect(() => {
    if (!user || !profile || profile.email_verified || autoSent.current) return
    if (!isEmailJsConfigured) {
      setError('EmailJS is not configured in .env')
      return
    }
    autoSent.current = true
    setSending(true)
    sendEmailOtp({
      email: profile.email || user.email,
      fullName: profile.full_name,
    })
      .then(({ error: err }) => {
        if (err) {
          setError(err.message)
          autoSent.current = false
        } else {
          setMessage('OTP sent to your email. Valid for 10 minutes.')
        }
      })
      .finally(() => setSending(false))
  }, [user, profile])

  useEffect(() => {
    if (profile?.email_verified) {
      const search = typeof window !== 'undefined' ? window.location.search : ''
      setLocation(resolvePostAuthPath(homePathForRole(profile.role), search))
    }
  }, [profile, setLocation])

  useEffect(() => {
    if (!loading && !user) setLocation('/login')
  }, [loading, user, setLocation])

  async function resend() {
    setSending(true)
    setError('')
    setMessage('')
    const { error: err, toEmail } = await sendEmailOtp({
      email: profile?.email || user?.email,
      fullName: profile?.full_name || user?.user_metadata?.full_name,
    })
    setSending(false)
    if (err) {
      setError(err.message)
      return
    }
    setMessage(`New OTP sent to ${toEmail}. Check inbox/spam.`)
    await refreshProfile()
  }

  async function handleVerify(e) {
    e.preventDefault()
    setBusy(true)
    setError('')
    setMessage('')
    const { ok, error: err } = await verifyEmailOtp(otp)
    if (err) {
      setBusy(false)
      setError(err.message)
      return
    }
    if (!ok) {
      setBusy(false)
      setError('Invalid or expired OTP. Try again or resend.')
      return
    }
    const latest = await refreshProfile()
    setBusy(false)
    setMessage('Email verified — welcome aboard.')
    const search = typeof window !== 'undefined' ? window.location.search : ''
    setTimeout(
      () => setLocation(resolvePostAuthPath(homePathForRole(latest?.role), search)),
      600,
    )
  }

  if (loading || (user && !profile)) {
    return (
      <AuthStage mode="verify" mood="busy" title="Loading…" subtitle="">
        <p className="muted">Preparing verification…</p>
      </AuthStage>
    )
  }

  if (!user) return null

  const displayEmail = profile?.email || user?.email

  return (
    <AuthStage
      mode="verify"
      mood={error ? 'error' : busy || sending ? 'busy' : 'idle'}
      eyebrow="Orbit confirmation"
      title="Enter your 6-digit code"
      subtitle={
        <>
          We sent a one-time pass to{' '}
          <strong className="es-auth__email-chip">{displayEmail}</strong>. Valid for 10 minutes.
        </>
      }
      footer={
        <p className="muted es-auth__foot-note">
          <button
            type="button"
            className="btn btn-quiet"
            onClick={async () => {
              await signOut()
              setLocation('/')
            }}
          >
            Sign out
          </button>
          {' · '}
          <Link href="/">Public home</Link>
        </p>
      }
    >
      {!isEmailJsConfigured && (
        <p className="es-auth__alert es-auth__alert--danger">
          EmailJS is not configured in <code>.env</code>.
        </p>
      )}

      {sending && !message ? (
        <p className="es-auth__alert es-auth__alert--info">
          <Mail size={14} aria-hidden /> Sending OTP…
        </p>
      ) : null}

      <form onSubmit={handleVerify}>
        <label className="label" htmlFor="verify-otp">
          OTP code
        </label>
        <input
          id="verify-otp"
          className="input es-auth__otp"
          inputMode="numeric"
          maxLength={6}
          value={otp}
          onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
          required
          autoComplete="one-time-code"
          placeholder="000000"
        />
        {error ? <p className="es-auth__alert es-auth__alert--danger">{error}</p> : null}
        {message ? <p className="es-auth__alert es-auth__alert--ok">{message}</p> : null}
        <button
          className="btn btn-primary"
          style={{ width: '100%', marginTop: 18 }}
          disabled={busy || otp.length !== 6}
        >
          {busy ? 'Checking…' : <>Verify & continue <ArrowRight size={15} /></>}
        </button>
        <button
          type="button"
          className="btn es-auth__link-btn"
          style={{ width: '100%', marginTop: 10 }}
          disabled={sending}
          onClick={resend}
        >
          {sending ? 'Sending…' : 'Resend OTP'}
        </button>
      </form>
    </AuthStage>
  )
}

import { createContext, useContext, useEffect, useRef } from 'react'
import { useReducedMotion } from 'framer-motion'

/** Scroll container ref for framer-motion whileInView inside workspace stage. */
export const EsScrollRootContext = createContext(null)

export function useEsScrollRoot() {
  return useContext(EsScrollRootContext)
}

const REVEAL_SELECTOR = [
  '.page-head',
  '.es-page-head',
  '.section',
  '.surface',
  '.stats-card',
  '.empty',
  '.es-empty',
  '.es-role-dash__stat',
  '.es-event-card',
  '.event-card',
  '.grid-2 > *',
  '.grid-3 > *',
  '.grid-4 > *',
  '.detail-grid > *',
  '.table-wrap',
  '.chart',
  '.activity-item',
  '.pass',
  '.notification-row',
  '.es-page-head + *',
].join(', ')

function collectRevealTargets(root) {
  const nodes = [...root.querySelectorAll(REVEAL_SELECTOR)]
  return nodes.filter((el) => {
    if (el.closest('.stu-dash')) return false
    if (el.closest('[data-es-reveal-skip]')) return false
    if (el.closest('[data-es-no-reveal]')) return false
    // Never animate interactive forms / dialogs — opacity:0 + remounts break typing
    if (el.closest('.modal, .modal-backdrop, .form-grid, form, [data-testid="event-visual-fields"]'))
      return false
    if (el.querySelector?.('input, textarea, select')) return false
    if (el.matches('input, textarea, select, button, label')) return false
    if (el.classList.contains('es-scroll-reveal')) return false
    return !nodes.some((other) => other !== el && other.contains(el))
  })
}

/**
 * Lightweight scroll-reveal for all workspace pages.
 * Uses IntersectionObserver + CSS (GPU-friendly) — no per-element React motion trees.
 */
export default function EsScrollMotion({ children, scrollRef, routeKey = '' }) {
  const reduce = useReducedMotion()
  const observerRef = useRef(null)
  const debounceRef = useRef(null)

  useEffect(() => {
    const root = scrollRef?.current
    if (!root) return

    const narrow =
      typeof window !== 'undefined' && window.matchMedia('(max-width: 760px)').matches

    if (reduce || narrow) {
      root.querySelectorAll('.es-scroll-reveal').forEach((el) => {
        el.classList.add('es-scroll-reveal--in')
      })
      return undefined
    }

    let stagger = 0

    const observe = (el) => {
      if (!observerRef.current) return
      el.classList.add('es-scroll-reveal')
      el.style.setProperty('--es-reveal-delay', `${Math.min(stagger * 0.06, 0.42)}s`)
      stagger += 1
      observerRef.current.observe(el)
    }

    const scan = () => {
      stagger = 0
      collectRevealTargets(root).forEach(observe)
    }

    observerRef.current = new IntersectionObserver(
      (entries) => {
        entries.forEach(({ target, isIntersecting }) => {
          if (!isIntersecting) return
          target.classList.add('es-scroll-reveal--in')
          observerRef.current?.unobserve(target)
        })
      },
      { root, threshold: 0.12, rootMargin: '0px 0px -6% 0px' },
    )

    scan()

    const scheduleScan = () => {
      if (debounceRef.current) window.clearTimeout(debounceRef.current)
      debounceRef.current = window.setTimeout(scan, 120)
    }

    const mo = new MutationObserver(scheduleScan)
    mo.observe(root, { childList: true, subtree: true })

    return () => {
      observerRef.current?.disconnect()
      observerRef.current = null
      mo.disconnect()
      if (debounceRef.current) window.clearTimeout(debounceRef.current)
    }
  }, [scrollRef, reduce, routeKey])

  return (
    <EsScrollRootContext.Provider value={scrollRef}>
      {children}
    </EsScrollRootContext.Provider>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'wouter'
import { ArrowRight, CalendarDays, Loader2, MapPin, ShieldCheck, Ticket } from 'lucide-react'
import { getEvent } from '@/services/events'
import { registerForEvent } from '@/services/registrations'
import { createCheckoutSession, confirmCheckoutSession } from '@/services/payments'
import { validatePromoCode, applyPromoDiscount } from '@/services/growth'
import {
  eventRequiresPayment,
  formatEarlyBirdEnds,
  formatMoney,
  formatRegistrationCloses,
  getEventPricing,
  isPublicGuestEvent,
  isRegistrationClosed,
  pricingLabel,
} from '@/lib/eventMappers'
import { formatEventSchedule } from '@/lib/eventDate'
import {
  notifyCampusEmail,
  paymentSuccessEmailCopy,
  registrationEmailCopy,
} from '@/lib/studentNotify'

export default function GuestRegisterFlow({ eventId, user, setToast, onComplete, onCancel }) {
  const [event, setEvent] = useState(null)
  const [loading, setLoading] = useState(true)
  const [busy, setBusy] = useState(false)
  const [referralCode, setReferralCode] = useState('')
  const [acceptedTerms, setAcceptedTerms] = useState(false)
  const [promoInput, setPromoInput] = useState('')
  const [promoApplied, setPromoApplied] = useState(null)
  const [promoError, setPromoError] = useState('')

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      if (!eventId) {
        setLoading(false)
        return
      }
      setLoading(true)
      const { data, error } = await getEvent(eventId)
      if (cancelled) return
      setLoading(false)
      if (error || !data) {
        setToast?.(error?.message || 'Event not found')
        setEvent(null)
        return
      }
      setEvent(data)
    })()
    return () => {
      cancelled = true
    }
  }, [eventId, setToast])

  useEffect(() => {
    const search = typeof window !== 'undefined' ? window.location.search : ''
    const q = new URLSearchParams(search)
    if (q.get('paid') !== '1') return
    const sessionId = q.get('session_id')
    const paidEvent = q.get('event') || eventId
    if (!sessionId && !paidEvent) return
    setBusy(true)
    void (async () => {
      const { data, error } = await confirmCheckoutSession({
        sessionId,
        eventId: paidEvent,
      })
      setBusy(false)
      if (error) {
        setToast?.(error.message || 'Could not confirm payment')
        return
      }
      setToast?.(data?.alreadyPaid ? 'Payment already confirmed' : 'Payment confirmed — your guest pass is ready')
      try {
        let ev = event
        if (!ev && paidEvent) {
          const loaded = await getEvent(paidEvent)
          ev = loaded.data
        }
        const copy = paymentSuccessEmailCopy(ev)
        await notifyCampusEmail({
          toEmail: user?.email,
          toName: user?.user_metadata?.full_name || user?.email || 'Guest',
          ...copy,
          dedupeKey: `pay_ok_${user?.id}_${paidEvent || data?.registrationId}`,
        })
      } catch {
        /* ignore notify errors */
      }
      onComplete?.()
    })()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  if (loading) {
    return (
      <section className="surface es-guest-register" style={{ padding: 24 }}>
        <p className="muted" style={{ margin: 0 }}>
          <Loader2 size={16} style={{ animation: 'spin 0.9s linear infinite', verticalAlign: -3, marginRight: 8 }} />
          Loading event…
        </p>
      </section>
    )
  }

  if (!event) {
    return (
      <section className="surface es-guest-register" style={{ padding: 24 }}>
        <p className="muted" style={{ margin: 0 }}>This event is unavailable.</p>
        <button type="button" className="btn" style={{ marginTop: 12 }} onClick={onCancel}>
          Back to hub
        </button>
      </section>
    )
  }

  if (!isPublicGuestEvent(event)) {
    return (
      <section className="surface es-guest-register" style={{ padding: 24 }}>
        <div className="eyebrow">Campus only</div>
        <h2 className="display" style={{ margin: '8px 0', fontSize: 20 }}>
          Public registration not open
        </h2>
        <p className="muted" style={{ fontSize: 13 }}>
          This event is for campus students only. The organizer has not opened public guest seats.
        </p>
        <Link href="/events" className="btn btn-primary" style={{ marginTop: 14 }}>
          Browse public events
        </Link>
      </section>
    )
  }

  const closed = isRegistrationClosed(event)
  const closes = formatRegistrationCloses(event)
  const publicLeft =
    event.publicSeatsAvailable != null
      ? event.publicSeatsAvailable
      : Math.max(0, Number(event.publicCapacity || 0))
  const pricing = getEventPricing(event)
  const needsPay = eventRequiresPayment(event)
  const feeAmount = pricing.fee
  const depositAmount = pricing.deposit
  const discountedFee = promoApplied ? applyPromoDiscount(feeAmount, promoApplied) : feeAmount
  const payTotal = discountedFee + depositAmount

  const applyPromo = async () => {
    setPromoError('')
    if (!promoInput.trim()) {
      setPromoError('Enter a promo code')
      return
    }
    setBusy(true)
    const { data, error } = await validatePromoCode(promoInput, {
      eventId: event.id,
      studentId: user?.id,
    })
    setBusy(false)
    if (error) {
      setPromoApplied(null)
      setPromoError(error.message || 'Invalid code')
      return
    }
    setPromoApplied(data)
    setToast?.(`Promo ${data.code} applied`)
  }

  const submit = async () => {
    if (closed) {
      setToast?.('Registration is closed for this event')
      return
    }
    if (publicLeft <= 0) {
      setToast?.('No public seats remaining')
      return
    }
    if (!acceptedTerms) {
      setToast?.('Please confirm you agree to event rules and contact sharing')
      return
    }
    if (!user?.id) {
      setToast?.('Sign in as a guest to register')
      return
    }

    setBusy(true)
    try {
      if (needsPay) {
        const origin = window.location.origin
        const { data, error } = await createCheckoutSession({
          eventId: event.id,
          promoCode: promoApplied?.code || undefined,
          successUrl: `${origin}/guest?paid=1&event=${encodeURIComponent(event.id)}&session_id={CHECKOUT_SESSION_ID}`,
          cancelUrl: `${origin}/guest?event=${encodeURIComponent(event.id)}`,
        })
        if (error) {
          setToast?.(error.message || 'Could not start checkout')
          return
        }
        if (data?.alreadyPaid || data?.freeWithPromo) {
          setToast?.(
            data?.freeWithPromo ? 'Promo covered the fee — you are registered.' : 'Already paid — seat confirmed.',
          )
          try {
            const copy = data?.freeWithPromo
              ? registrationEmailCopy(event, 'confirmed')
              : paymentSuccessEmailCopy(event)
            await notifyCampusEmail({
              toEmail: user?.email,
              toName: user?.user_metadata?.full_name || user?.email || 'Guest',
              ...copy,
              dedupeKey: data?.freeWithPromo
                ? `reg_${user?.id}_${event.id}_confirmed`
                : `pay_ok_${user?.id}_${event.id}`,
            })
          } catch {
            /* ignore */
          }
          onComplete?.()
          return
        }
        if (data?.url) {
          window.location.assign(data.url)
          return
        }
        setToast?.('Checkout unavailable — contact the organizer')
        return
      }

      const { data, error } = await registerForEvent(event.id, {
        referralCode: referralCode.trim() || undefined,
      })
      if (error) {
        setToast?.(error.message || 'Registration failed')
        return
      }
      const status = data?.status
      setToast?.(
        status === 'waitlist'
          ? 'Public pool full — you are on the waitlist.'
          : status === 'pending'
            ? 'Registration pending organizer approval.'
            : 'Registered — your guest pass is ready.',
      )
      try {
        const copy = registrationEmailCopy(event, status)
        await notifyCampusEmail({
          toEmail: user?.email,
          toName: user?.user_metadata?.full_name || user?.email || 'Guest',
          ...copy,
          dedupeKey: `reg_${user?.id}_${event.id}_${status}`,
        })
      } catch {
        /* ignore notify errors */
      }
      onComplete?.()
    } finally {
      setBusy(false)
    }
  }

  return (
    <section className="surface es-guest-register" style={{ padding: 24 }} data-testid="guest-register-flow">
      <div className="eyebrow">Public registration</div>
      <h2 className="display" style={{ margin: '8px 0 12px', fontSize: 22 }}>{event.title}</h2>

      <div className="es-guest-register__meta">
        <span>
          <CalendarDays size={13} style={{ verticalAlign: -2, marginRight: 4 }} />
          {formatEventSchedule(event)}
        </span>
        <span>
          <MapPin size={13} style={{ verticalAlign: -2, marginRight: 4 }} />
          {event.venue || 'Campus venue'}
        </span>
        <span>
          <Ticket size={13} style={{ verticalAlign: -2, marginRight: 4 }} />
          {needsPay ? pricingLabel(event) : 'Free'} · {publicLeft} public seats left
        </span>
        {closes ? (
          <span>{closed ? 'Registration closed' : `Closes ${closes}`}</span>
        ) : null}
      </div>

      {event.description ? (
        <p className="muted" style={{ fontSize: 13, lineHeight: 1.6, marginTop: 14 }}>
          {event.description}
        </p>
      ) : null}

      {event.rules ? (
        <div className="es-guest-register__rules" style={{ marginTop: 14 }}>
          <strong style={{ fontSize: 12 }}>Event rules</strong>
          <p className="muted" style={{ fontSize: 12, margin: '6px 0 0', whiteSpace: 'pre-wrap' }}>
            {event.rules}
          </p>
        </div>
      ) : null}

      <div className="form-grid" style={{ marginTop: 20 }}>
        <div className="full">
          <label className="label">Student referral code (optional)</label>
          <input
            className="input"
            value={referralCode}
            onChange={(e) => setReferralCode(e.target.value.toUpperCase())}
            placeholder="If a campus student invited you"
            data-testid="input-guest-register-referral"
          />
        </div>

        {needsPay ? (
          <div className="full">
            <label className="label">Promo code (optional)</label>
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              <input
                className="input"
                value={promoInput}
                onChange={(e) => setPromoInput(e.target.value.toUpperCase())}
                placeholder="PROMO"
                style={{ flex: 1, minWidth: 140 }}
              />
              <button type="button" className="btn" disabled={busy} onClick={applyPromo}>
                Apply
              </button>
            </div>
            {promoError ? (
              <p className="subtle" style={{ color: 'var(--danger)', fontSize: 11, marginTop: 6 }}>
                {promoError}
              </p>
            ) : null}
            <p className="subtle" style={{ fontSize: 11, marginTop: 8 }}>
              Total due: <strong>{formatMoney(payTotal, event.currency)}</strong>
              {depositAmount > 0 ? ` (includes ${formatMoney(depositAmount, event.currency)} refundable deposit)` : ''}
              {pricing.isEarlyBird && formatEarlyBirdEnds(event) ? (
                <>
                  <br />
                  Early bird until {formatEarlyBirdEnds(event)}
                  {pricing.regularFee > feeAmount
                    ? ` · then ${formatMoney(pricing.regularFee, event.currency)}`
                    : ''}
                </>
              ) : null}
            </p>
          </div>
        ) : null}

        <div className="full">
          <label style={{ display: 'flex', alignItems: 'flex-start', gap: 10, fontSize: 12, cursor: 'pointer' }}>
            <input
              type="checkbox"
              checked={acceptedTerms}
              onChange={(e) => setAcceptedTerms(e.target.checked)}
              data-testid="checkbox-guest-register-terms"
              style={{ marginTop: 3 }}
            />
            <span>
              I confirm my details are correct, I may be contacted about this event, and I agree to follow campus
              venue rules. <ShieldCheck size={12} style={{ verticalAlign: -2 }} />
            </span>
          </label>
        </div>
      </div>

      <div className="es-guest-register__actions">
        <button type="button" className="btn" onClick={onCancel} disabled={busy}>
          Cancel
        </button>
        <button
          type="button"
          className="btn btn-primary"
          disabled={busy || closed || publicLeft <= 0}
          onClick={submit}
          data-testid="button-guest-register-submit"
        >
          {busy ? (
            <>
              <Loader2 size={14} style={{ animation: 'spin 0.9s linear infinite' }} /> Processing…
            </>
          ) : needsPay ? (
            <>Pay {formatMoney(payTotal, event.currency)} <ArrowRight size={14} /></>
          ) : (
            <>Confirm registration <ArrowRight size={14} /></>
          )}
        </button>
      </div>
    </section>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Pencil, Plus, Trash2 } from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import { EVENT_CATEGORIES, TABLES } from '@/constants/domain'
import { createCategory, deleteCategory, listCategories, updateCategory } from '@/services/categories'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'
import EsModal from '@/components/shared/EsModal'
import { useConfirmDialog } from '@/hooks/useConfirmDialog.jsx'

export default function CategoriesManager({ events = [], setToast, canManage = true }) {
  const { user } = useAuth()
  const { confirm, dialog: confirmUi } = useConfirmDialog()
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [open, setOpen] = useState(false)
  const [editing, setEditing] = useState(null)
  const [name, setName] = useState('')
  const [busy, setBusy] = useState(false)

  const load = useCallback(async (opts = {}) => {
    const silent = Boolean(opts.silent)
    if (!silent) setLoading(true)
    const { data, error } = await listCategories()
    if (error) {
      const fromEvents = Array.from(new Set((events || []).map((e) => e.category).filter(Boolean)))
      setRows(
        [...new Set([...EVENT_CATEGORIES, ...fromEvents])].map((n) => ({ id: n, name: n, _local: true })),
      )
      if (!silent) setToast?.(error.message + ' — run supabase/eventsphere-categories.sql')
    } else {
      setRows(data || [])
    }
    if (!silent) setLoading(false)
  }, [events, setToast])

  useEffect(() => {
    load()
  }, [load])

  useRealtimeTables([TABLES.EVENT_CATEGORIES], () => load({ silent: true }), {
    channelName: 'es-categories',
  })

  function openCreate() {
    setEditing(null)
    setName('')
    setOpen(true)
  }

  function openEdit(row) {
    if (row._local) {
      setToast?.('Local/default category — run eventsphere-categories.sql to manage permanently')
      return
    }
    setEditing(row)
    setName(row.name || '')
    setOpen(true)
  }

  function closeForm() {
    setOpen(false)
    setEditing(null)
    setName('')
  }

  async function save() {
    const nextName = name.trim()
    if (!nextName) {
      setToast?.('Category name is required')
      return
    }
    const isEdit = Boolean(editing && !editing._local)
    const editId = editing?.id
    setBusy(true)
    const { data, error } = isEdit
      ? await updateCategory(editId, nextName)
      : await createCategory(nextName, user?.id)
    setBusy(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    if (isEdit && data?.name) {
      setRows((prev) => prev.map((r) => (r.id === editId ? { ...r, name: data.name } : r)))
    }
    closeForm()
    setToast?.(isEdit ? 'Category updated' : 'Category added')
    load()
  }

  async function remove(row) {
    if (row._local) {
      setToast?.('Default/local category — create DB table to manage permanently')
      return
    }
    const ok = await confirm({
      title: 'Delete category?',
      message: `"${row.name}" will be removed from the taxonomy.`,
      confirmLabel: 'Delete category',
      tone: 'danger',
    })
    if (!ok) return
    const { error } = await deleteCategory(row.id)
    if (error) setToast?.(error.message)
    else {
      setToast?.('Category deleted')
      load()
    }
  }

  return (
    <>
      {confirmUi}
      <div className="page-head">
        <div>
          <div className="eyebrow">Taxonomy</div>
          <h1>Categories</h1>
          <p>Live categories from the database. Used when creating events.</p>
        </div>
        {canManage && (
          <button className="btn btn-primary" type="button" onClick={openCreate} data-testid="button-add-category">
            <Plus size={15} /> Add category
          </button>
        )}
      </div>
      {loading && <p className="muted">Loading categories…</p>}
      {!loading && !rows.length && (
        <div className="surface" style={{ padding: 24 }}>
          <p className="muted" style={{ margin: 0 }}>No categories yet. Add one to get started.</p>
        </div>
      )}
      <div className="grid-4 stagger">
        {rows.map((c, i) => (
          <div className="surface" style={{ padding: 17 }} key={c.id || c.name}>
            <div className="section-title">
              <span
                className="avatar"
                style={{
                  background: i % 2 ? 'rgba(229,121,210,.18)' : 'rgba(84,216,232,.18)',
                  color: i % 2 ? 'var(--pink)' : 'var(--cyan)',
                }}
              >
                {(c.name || '?')[0]}
              </span>
              {canManage && (
                <div style={{ display: 'flex', gap: 4 }}>
                  <button className="btn btn-quiet" type="button" onClick={() => openEdit(c)} aria-label="Edit category" data-testid={`button-edit-category-${c.id}`}>
                    <Pencil size={14} />
                  </button>
                  {!c._local && (
                    <button className="btn btn-quiet btn-danger" type="button" onClick={() => remove(c)} aria-label="Delete category" data-testid={`button-delete-category-${c.id}`}>
                      <Trash2 size={14} />
                    </button>
                  )}
                </div>
              )}
            </div>
            <h3 className="display" style={{ margin: '15px 0 4px' }}>{c.name}</h3>
            <span className="muted" style={{ fontSize: 11 }}>
              {(events || []).filter((e) => e.category === c.name).length} events
            </span>
          </div>
        ))}
      </div>

      {open && (
        <EsModal title={editing ? 'Edit category' : 'Add category'} onClose={closeForm}>
          <label className="label">Category name</label>
          <input
            className="input"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. Community"
            data-testid="input-category-name"
            autoFocus
          />
          <div style={{ display: 'flex', gap: 8, marginTop: 18 }}>
            <button className="btn" type="button" style={{ flex: 1 }} onClick={closeForm}>
              Cancel
            </button>
            <button className="btn btn-primary" style={{ flex: 1 }} type="button" disabled={busy} onClick={save} data-testid="button-save-category">
              {busy ? 'Saving…' : editing ? 'Update category' : 'Save category'}
            </button>
          </div>
        </EsModal>
      )}
    </>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Eye, EyeOff, RefreshCw } from 'lucide-react'
import { TABLES } from '@/constants/domain'
import { hideMedia, listMediaForModeration } from '@/services/media'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'

export default function MediaModeration({ eventId = null, setToast, title = 'Media moderation' }) {
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [busyId, setBusyId] = useState(null)
  const [filter, setFilter] = useState('all') // all | visible | hidden

  const load = useCallback(
    async (opts = {}) => {
      const silent = Boolean(opts.silent)
      if (!silent) setLoading(true)
      const { data, error } = await listMediaForModeration({ eventId: eventId || undefined })
      if (error && !silent) setToast?.(error.message)
      setRows(data || [])
      if (!silent) setLoading(false)
    },
    [eventId, setToast],
  )

  useEffect(() => {
    load()
  }, [load])

  useRealtimeTables([TABLES.MEDIA_GALLERY], () => load({ silent: true }), {
    channelName: `es-media-${eventId || 'all'}`,
  })

  const visible = rows.filter((r) => {
    if (filter === 'visible') return !r.is_hidden
    if (filter === 'hidden') return r.is_hidden
    return true
  })

  const toggle = async (row) => {
    setBusyId(row.id)
    const next = !row.is_hidden
    const { error } = await hideMedia(row.id, next)
    setBusyId(null)
    if (error) {
      setToast?.(error.message)
      return
    }
    setToast?.(next ? 'Media hidden from public gallery' : 'Media restored to public gallery')
    load()
  }

  return (
    <div className="surface" style={{ padding: 18 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap', alignItems: 'center' }}>
        <div>
          <div className="eyebrow">Gallery · moderation</div>
          <h3 className="display" style={{ margin: '6px 0 0', fontSize: 18 }}>{title}</h3>
        </div>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          <div className="chips">
            {[
              ['all', 'All'],
              ['visible', 'Public'],
              ['hidden', 'Hidden'],
            ].map(([id, label]) => (
              <button
                key={id}
                type="button"
                className={`chip ${filter === id ? 'active' : ''}`}
                onClick={() => setFilter(id)}
              >
                {label}
              </button>
            ))}
          </div>
          <button className="btn" type="button" onClick={load} disabled={loading} aria-label="Refresh media">
            <RefreshCw size={14} /> Refresh
          </button>
        </div>
      </div>

      {loading && <p className="muted" style={{ marginTop: 14 }}>Loading media…</p>}
      {!loading && !visible.length && (
        <p className="muted" style={{ marginTop: 14 }}>No media in this filter.</p>
      )}

      <div className="grid-3" style={{ marginTop: 16 }}>
        {visible.map((item) => (
          <article
            key={item.id}
            className="surface"
            style={{ overflow: 'hidden', border: item.is_hidden ? '1px dashed var(--line)' : undefined }}
          >
            {item.file_type === 'video' ? (
              <video
                src={item.file_url}
                controls
                style={{ width: '100%', display: 'block', aspectRatio: '16/10', objectFit: 'cover' }}
              />
            ) : (
              <img
                src={item.file_url}
                alt={item.caption || item.events?.title || 'Event media'}
                loading="lazy"
                style={{ width: '100%', display: 'block', aspectRatio: '16/10', objectFit: 'cover' }}
              />
            )}
            <div style={{ padding: 12 }}>
              <div className="eyebrow">{item.is_hidden ? 'Hidden' : 'Public'} · {item.events?.category || 'Campus'}</div>
              <strong style={{ display: 'block', marginTop: 6, fontSize: 13 }}>
                {item.events?.title || 'Event media'}
              </strong>
              <p className="muted" style={{ fontSize: 11, margin: '4px 0 10px' }}>
                {item.caption || 'No caption'}
              </p>
              <button
                className="btn"
                type="button"
                disabled={busyId === item.id}
                onClick={() => toggle(item)}
                aria-label={item.is_hidden ? 'Show in public gallery' : 'Hide from public gallery'}
              >
                {item.is_hidden ? <><Eye size={14} /> Unhide</> : <><EyeOff size={14} /> Hide</>}
              </button>
            </div>
          </article>
        ))}
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useAuth } from '@/context/AuthContext'
import { EVENT_CATEGORIES, EVENT_STATUS, DEFAULT_EVENT_CURRENCY } from '@/constants/domain'
import { addDaysToDate } from '@/lib/eventDate'
import {
  isoToLocalDateTimeParts,
  localDateTimeToIso,
  validateEarlyBirdPricing,
  formatMoney,
  formatEarlyBirdEnds,
  isEarlyBirdActive,
} from '@/lib/eventMappers'
import { listCategories } from '@/services/categories'
import { listVenues } from '@/services/venues'
import { EventVisualFields } from '@/components/design-system'
import EsModal from '@/components/shared/EsModal'
import { useConfirmDialog } from '@/hooks/useConfirmDialog.jsx'

/** HTML date input needs YYYY-MM-DD — DB sometimes returns ISO timestamps. */
function toDateInput(value) {
  if (!value) return ''
  const s = String(value).trim()
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10)
  const d = new Date(s)
  if (Number.isNaN(d.getTime())) return ''
  const pad = (n) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

/** HTML time input needs HH:MM — Postgres often returns HH:MM:SS(.sss). */
function toTimeInput(value) {
  if (!value) return ''
  const m = String(value).trim().match(/(\d{1,2}):(\d{2})/)
  if (!m) return ''
  return `${String(m[1]).padStart(2, '0')}:${m[2]}`
}

function buildEditForm(event) {
  const closeParts = isoToLocalDateTimeParts(event?.registrationClosesAt)
  const earlyParts = isoToLocalDateTimeParts(event?.earlyBirdUntil)
  const date = toDateInput(event?.date)
  const hasEarly =
    event?.earlyBirdFee != null && Boolean(event?.earlyBirdUntil)
  return {
    title: event?.title || '',
    description: event?.description || '',
    category: event?.category || 'Technology',
    date,
    time: toTimeInput(event?.time),
    endTime: toTimeInput(event?.endTime),
    venue: event?.venue || '',
    capacity: String(event?.capacity ?? 100),
    publicCapacity: String(event?.publicCapacity ?? 0),
    allowPublicGuests: Number(event?.publicCapacity ?? 0) > 0,
    rules: event?.rules || '',
    entryFee: String(event?.entryFee ?? 0),
    earlyBirdEnabled: hasEarly,
    earlyBirdFee: hasEarly ? String(event.earlyBirdFee) : '',
    earlyBirdUntilDate: earlyParts.date || '',
    earlyBirdUntilTime: earlyParts.time || '23:59',
    securityDeposit: String(event?.securityDeposit ?? 0),
    bannerUrl: event?.bannerUrl || '',
    characterKey: event?.characterKey || '',
    characterUrl: event?.characterUrl || '',
    isPromoted: Boolean(event?.isPromoted),
    registrationClosesDate: closeParts.date || date || '',
    registrationClosesTime: closeParts.time || '23:59',
    extendReason: '',
  }
}

/**
 * Organizer event management modals: edit | postpone | cancel | delete
 */
export default function OrganizerEventManage({ mode, event, actions, setToast, onClose, onSwitchMode }) {
  const { user } = useAuth()
  const { confirm, dialog: confirmUi } = useConfirmDialog()
  const [busy, setBusy] = useState(false)
  const [catOptions, setCatOptions] = useState([...EVENT_CATEGORIES])
  const [venueOptions, setVenueOptions] = useState([])
  const [form, setForm] = useState(() => buildEditForm(event))
  const [postpone, setPostpone] = useState(() => ({
    date: addDaysToDate(toDateInput(event?.date), 7),
    time: toTimeInput(event?.time),
    reason: '',
    days: '7',
  }))
  const [reason, setReason] = useState('')

  useEffect(() => {
    if (!event?.id) return
    setForm(buildEditForm(event))
    setPostpone({
      date: addDaysToDate(toDateInput(event.date), 7),
      time: toTimeInput(event.time),
      reason: '',
      days: '7',
    })
    setReason('')
  }, [event?.id])

  useEffect(() => {
    ;(async () => {
      const [c, v] = await Promise.all([listCategories(), listVenues()])
      if (!c.error && c.data?.length) setCatOptions(c.data.map((x) => x.name))
      if (!v.error && v.data?.length) setVenueOptions(v.data)
    })()
  }, [])

  if (!event || !mode) return null

  const update = (key) => (e) => {
    const value = e?.target?.value ?? ''
    setForm((prev) => ({ ...prev, [key]: value }))
  }

  const venueNames = venueOptions.map((v) => v.name).filter(Boolean)
  const venueSelectOptions =
    form.venue && !venueNames.includes(form.venue)
      ? [{ id: '__current', name: form.venue }, ...venueOptions]
      : venueOptions

  const categorySelectOptions =
    form.category && !catOptions.includes(form.category)
      ? [form.category, ...catOptions]
      : catOptions

  async function saveEdit() {
    if (!form.title.trim()) {
      setToast?.('Event title is required')
      return
    }
    if (!form.date) {
      setToast?.('Start date is required')
      return
    }
    if (!form.registrationClosesDate) {
      setToast?.('Registration close date is required')
      return
    }
    const registrationClosesAt = localDateTimeToIso(
      form.registrationClosesDate,
      form.registrationClosesTime || '23:59',
    )
    if (!registrationClosesAt) {
      setToast?.('Invalid registration close date/time')
      return
    }
    const eventStart = localDateTimeToIso(form.date, form.time || '23:59')
    if (eventStart && new Date(registrationClosesAt) > new Date(eventStart)) {
      setToast?.('Registration must close on or before the event start')
      return
    }

    if (typeof actions?.updateEvent !== 'function') {
      setToast?.('Update action unavailable — refresh and try again')
      return
    }

    const oldTs = event.registrationClosesAt
      ? new Date(event.registrationClosesAt).getTime()
      : null
    const newTs = new Date(registrationClosesAt).getTime()
    const isExtension = oldTs == null || newTs > oldTs

    const entryFee = Math.max(0, Number(form.entryFee) || 0)
    const securityDeposit = Math.max(0, Number(form.securityDeposit) || 0)
    let earlyBirdFee = null
    let earlyBirdUntil = null
    if (form.earlyBirdEnabled) {
      earlyBirdUntil = localDateTimeToIso(
        form.earlyBirdUntilDate || form.date,
        form.earlyBirdUntilTime || '23:59',
      )
      earlyBirdFee = Math.max(0, Number(form.earlyBirdFee) || 0)
      const earlyErr = validateEarlyBirdPricing({
        entryFee,
        earlyBirdFee,
        earlyBirdUntil,
        eventStartIso: localDateTimeToIso(form.date, form.time || '00:00'),
      })
      if (earlyErr) {
        setToast?.(earlyErr)
        return
      }
    }

    const patch = {
      title: form.title.trim(),
      description: form.description,
      category: form.category,
      date: form.date,
      time: form.time || null,
      endTime: form.endTime || null,
      venue: form.venue,
      capacity: form.capacity,
      publicCapacity: form.allowPublicGuests
        ? Math.max(0, Number(form.publicCapacity) || 0)
        : 0,
      rules: form.rules,
      entryFee,
      earlyBirdFee,
      earlyBirdUntil,
      securityDeposit,
      currency: DEFAULT_EVENT_CURRENCY,
      bannerUrl: form.bannerUrl?.trim() || null,
      characterKey: form.characterKey || null,
      characterUrl: form.characterUrl?.trim() || null,
      isPromoted: Boolean(form.isPromoted),
      promotedUntil: form.isPromoted
        ? new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString()
        : null,
      promotionTier: 'standard',
    }

    setBusy(true)
    if (isExtension && actions.extendRegistrationDeadline) {
      const { error } = await actions.extendRegistrationDeadline(event.id, {
        registrationClosesAt,
        reason: form.extendReason,
        createdBy: user?.id,
        title: form.title.trim() || event.title,
      })
      if (error) {
        setBusy(false)
        setToast?.(error.message)
        return
      }
      const { error: updErr } = await actions.updateEvent(event.id, patch)
      setBusy(false)
      if (updErr) {
        setToast?.(updErr.message)
        return
      }
      setToast?.('Event updated. Registration extended — all students notified.')
      onClose?.()
      return
    }

    const { error } = await actions.updateEvent(event.id, {
      ...patch,
      registrationClosesAt,
    })
    setBusy(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    setToast?.('Event updated')
    onClose?.()
  }

  async function saveExtendRegistration() {
    if (!form.registrationClosesDate) {
      setToast?.('Pick a new registration close date')
      return
    }
    const registrationClosesAt = localDateTimeToIso(
      form.registrationClosesDate,
      form.registrationClosesTime || '23:59',
    )
    const oldTs = event.registrationClosesAt
      ? new Date(event.registrationClosesAt).getTime()
      : 0
    if (new Date(registrationClosesAt).getTime() <= oldTs) {
      setToast?.('New close time must be later than the current one')
      return
    }
    setBusy(true)
    const { error, notified } = await actions.extendRegistrationDeadline(event.id, {
      registrationClosesAt,
      reason: form.extendReason,
      createdBy: user?.id,
      title: event.title,
    })
    setBusy(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    setToast?.(
      `Registration extended. ${notified != null ? `${notified} students notified.` : 'Students notified.'}`,
    )
    onClose?.()
  }

  async function savePostpone() {
    if (!postpone.date) {
      setToast?.('New date is required')
      return
    }
    const current = String(event.date || '').slice(0, 10)
    if (postpone.date <= current) {
      setToast?.('Postpone date must be after the current event date')
      return
    }
    setBusy(true)
    const { error } = await actions.postponeEvent(event.id, {
      date: postpone.date,
      time: postpone.time || event.time || '',
      reason: postpone.reason,
      createdBy: user?.id,
      title: event.title,
    })
    setBusy(false)
    if (error) {
      // Date may still have updated — show message and close so UI can refresh
      setToast?.(error.message)
      onClose?.()
      return
    }
    setToast?.(`Event postponed to ${postpone.date}. Students notified.`)
    onClose?.()
  }

  async function saveCancel() {
    setBusy(true)
    const { error } = await actions.cancelEvent(event.id, {
      reason,
      createdBy: user?.id,
      title: event.title,
    })
    setBusy(false)
    if (error) {
      const fallback = await actions.setStatus(event.id, EVENT_STATUS.CANCELLED)
      if (fallback.error) {
        setToast?.(error.message)
        return
      }
      setToast?.('Event cancelled (notification may have failed)')
      onClose?.()
      return
    }
    setToast?.('Event cancelled. Students notified.')
    onClose?.()
  }

  async function saveDelete() {
    const ok = await confirm({
      title: 'Delete event permanently?',
      message: `"${event.title}" will be removed. This cannot be undone.`,
      confirmLabel: 'Delete forever',
      tone: 'danger',
    })
    if (!ok) return
    setBusy(true)
    const { error } = await actions.deleteEvent(event.id)
    setBusy(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    setToast?.('Event deleted')
    onClose?.()
  }

  if (mode === 'delete') {
    const hasRegs = Number(event.registrations || 0) > 0
    const isLive = ['Approved', 'Pending'].includes(event.status)
    return (
      <>
      {confirmUi}
      <EsModal title={isLive || hasRegs ? 'Use Cancel instead' : 'Delete event'} onClose={onClose}>
        {isLive || hasRegs ? (
          <>
            <p className="muted" style={{ fontSize: 13, lineHeight: 1.6 }}>
              This event is live or has registrations. Hard delete would wipe attendance history.
              Use <strong>Cancel event</strong> so students get a notification.
            </p>
            <div style={{ display: 'flex', gap: 8, marginTop: 18 }}>
              <button className="btn" type="button" style={{ flex: 1 }} onClick={onClose}>Close</button>
              <button
                className="btn btn-primary"
                type="button"
                style={{ flex: 1 }}
                onClick={() => onSwitchMode?.('cancel')}
              >
                Cancel event
              </button>
            </div>
          </>
        ) : (
          <>
            <p className="muted" style={{ fontSize: 13 }}>
              Permanently remove <strong>{event.title}</strong> from your workspace?
            </p>
            <div style={{ display: 'flex', gap: 8, marginTop: 18 }}>
              <button className="btn" type="button" style={{ flex: 1 }} onClick={onClose}>Keep</button>
              <button className="btn btn-danger" type="button" style={{ flex: 1 }} disabled={busy} onClick={saveDelete} data-testid="button-confirm-delete-event">
                {busy ? 'Deleting…' : 'Delete forever'}
              </button>
            </div>
          </>
        )}
      </EsModal>
      </>
    )
  }

  if (mode === 'cancel') {
    return (
      <>
      {confirmUi}
      <EsModal title="Cancel event" onClose={onClose}>
        <p className="muted" style={{ fontSize: 12, marginBottom: 12 }}>
          Marks the event as Cancelled and notifies students. History is kept for audit.
        </p>
        <label className="label">Reason (optional)</label>
        <textarea className="input" rows={3} value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Venue conflict, weather, …" />
        <div style={{ display: 'flex', gap: 8, marginTop: 18 }}>
          <button className="btn" type="button" style={{ flex: 1 }} onClick={onClose}>Back</button>
          <button className="btn btn-danger" type="button" style={{ flex: 1 }} disabled={busy} onClick={saveCancel} data-testid="button-confirm-cancel-event">
            {busy ? 'Cancelling…' : 'Cancel event'}
          </button>
        </div>
      </EsModal>
      </>
    )
  }

  if (mode === 'postpone') {
    return (
      <EsModal title="Postpone event" onClose={onClose}>
        <p className="muted" style={{ fontSize: 12, marginBottom: 12 }}>
          Current: <strong>{event.date}</strong>{event.time ? ` · ${event.time}` : ''}.
          Date moves forward and students get a notification in the bell menu.
        </p>
        <div className="form-grid">
          <div>
            <label className="label">Quick jump</label>
            <select
              className="input"
              value={postpone.days}
              onChange={(e) => {
                const days = e.target.value
                setPostpone({
                  ...postpone,
                  days,
                  date: addDaysToDate(event.date, Number(days)),
                })
              }}
            >
              <option value="7">+7 days</option>
              <option value="14">+14 days</option>
              <option value="30">+30 days</option>
            </select>
          </div>
          <div>
            <label className="label">New date</label>
            <input
              className="input"
              type="date"
              value={postpone.date}
              onChange={(e) => setPostpone((p) => ({ ...p, date: e.target.value }))}
              data-testid="input-postpone-date"
            />
          </div>
          <div>
            <label className="label">New time</label>
            <input
              className="input"
              type="time"
              value={postpone.time}
              onChange={(e) => setPostpone((p) => ({ ...p, time: e.target.value }))}
            />
          </div>
          <div className="full">
            <label className="label">Reason (shown in notification)</label>
            <textarea
              className="input"
              rows={3}
              value={postpone.reason}
              onChange={(e) => setPostpone((p) => ({ ...p, reason: e.target.value }))}
              placeholder="Why is this postponed?"
            />
          </div>
        </div>
        <div style={{ display: 'flex', gap: 8, marginTop: 18 }}>
          <button className="btn" type="button" style={{ flex: 1 }} onClick={onClose}>Back</button>
          <button className="btn btn-primary" type="button" style={{ flex: 1 }} disabled={busy} onClick={savePostpone} data-testid="button-confirm-postpone">
            {busy ? 'Saving…' : 'Postpone & notify'}
          </button>
        </div>
      </EsModal>
    )
  }

  return (
    <EsModal title="Edit event" onClose={onClose}>
      <div className="form-grid">
        <div className="full">
          <label className="label">Event title</label>
          <input
            className="input"
            value={form.title}
            onChange={update('title')}
            autoFocus
            data-testid="input-edit-event-title"
          />
        </div>
        <div className="full">
          <label className="label">Description</label>
          <textarea className="input" rows={3} value={form.description} onChange={update('description')} />
        </div>
        <div>
          <label className="label">Category</label>
          <select className="input" value={form.category} onChange={update('category')}>
            {categorySelectOptions.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">Venue</label>
          <select className="input" value={form.venue} onChange={update('venue')}>
            {venueSelectOptions.length ? (
              venueSelectOptions.map((v) => (
                <option key={v.id || v.name} value={v.name}>
                  {v.name}
                </option>
              ))
            ) : (
              <option value={form.venue}>{form.venue || '—'}</option>
            )}
          </select>
        </div>
        <div>
          <label className="label">Date</label>
          <input className="input" type="date" value={form.date} onChange={update('date')} />
        </div>
        <div>
          <label className="label">Time</label>
          <input className="input" type="time" value={form.time} onChange={update('time')} />
        </div>
        <div>
          <label className="label">End time</label>
          <input className="input" type="time" value={form.endTime} onChange={update('endTime')} />
        </div>
        <div>
          <label className="label">Student capacity</label>
          <input className="input" type="number" min={0} value={form.capacity} onChange={update('capacity')} />
        </div>
        <div className="full">
          <label style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 12, cursor: 'pointer' }}>
            <input
              type="checkbox"
              checked={Boolean(form.allowPublicGuests)}
              onChange={(e) =>
                setForm((f) => ({
                  ...f,
                  allowPublicGuests: e.target.checked,
                  publicCapacity: e.target.checked && Number(f.publicCapacity) <= 0 ? '25' : f.publicCapacity,
                }))
              }
              data-testid="checkbox-edit-allow-public-guests"
            />
            Allow public guests on website
          </label>
        </div>
        {form.allowPublicGuests ? (
          <div>
            <label className="label">Public guest capacity</label>
            <input className="input" type="number" min={1} value={form.publicCapacity} onChange={update('publicCapacity')} data-testid="input-edit-public-capacity" />
          </div>
        ) : null}
        <div>
          <label className="label">Regular entry fee (PKR)</label>
          <input
            className="input"
            type="number"
            min="0"
            step="1"
            value={form.entryFee}
            onChange={update('entryFee')}
            data-testid="input-edit-event-fee"
          />
          <p className="subtle" style={{ fontSize: 10, marginTop: 4 }}>
            After payments start, fee can only increase — not decrease.
          </p>
        </div>
        <div>
          <label className="label">Security deposit (PKR)</label>
          <input className="input" type="number" min="0" step="0.01" value={form.securityDeposit} onChange={update('securityDeposit')} data-testid="input-edit-event-deposit" />
        </div>
        <div className="full">
          <label style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 12, cursor: 'pointer' }}>
            <input
              type="checkbox"
              checked={Boolean(form.earlyBirdEnabled)}
              onChange={(e) =>
                setForm((f) => ({
                  ...f,
                  earlyBirdEnabled: e.target.checked,
                  earlyBirdUntilDate: f.earlyBirdUntilDate || f.registrationClosesDate || f.date,
                  earlyBirdFee:
                    f.earlyBirdFee ||
                    (Number(f.entryFee) > 0
                      ? String(Math.max(0, Math.floor(Number(f.entryFee) * 0.8)))
                      : ''),
                }))
              }
              data-testid="checkbox-edit-early-bird"
            />
            Enable early-bird pricing
          </label>
          {event?.earlyBirdUntil && isEarlyBirdActive(event) ? (
            <p className="subtle" style={{ fontSize: 11, marginTop: 6, color: 'var(--lime)' }}>
              Early bird live until {formatEarlyBirdEnds(event)} · now{' '}
              {formatMoney(event.earlyBirdFee, event.currency)} (then{' '}
              {formatMoney(event.entryFee, event.currency)})
            </p>
          ) : null}
        </div>
        {form.earlyBirdEnabled ? (
          <>
            <div>
              <label className="label">Early-bird fee (PKR)</label>
              <input
                className="input"
                type="number"
                min="0"
                step="1"
                value={form.earlyBirdFee}
                onChange={update('earlyBirdFee')}
                data-testid="input-edit-early-bird-fee"
              />
            </div>
            <div>
              <label className="label">Early bird ends (date)</label>
              <input
                className="input"
                type="date"
                value={form.earlyBirdUntilDate}
                max={form.date || undefined}
                onChange={update('earlyBirdUntilDate')}
                data-testid="input-edit-early-bird-until-date"
              />
            </div>
            <div>
              <label className="label">Early bird ends (time)</label>
              <input
                className="input"
                type="time"
                value={form.earlyBirdUntilTime}
                onChange={update('earlyBirdUntilTime')}
                data-testid="input-edit-early-bird-until-time"
              />
            </div>
          </>
        ) : null}
        <div>
          <label className="label">Registration closes (date)</label>
          <input
            className="input"
            type="date"
            value={form.registrationClosesDate}
            max={form.date || undefined}
            onChange={update('registrationClosesDate')}
            data-testid="input-edit-registration-closes-date"
          />
        </div>
        <div>
          <label className="label">Registration closes (time)</label>
          <input
            className="input"
            type="time"
            value={form.registrationClosesTime}
            onChange={update('registrationClosesTime')}
            data-testid="input-edit-registration-closes-time"
          />
        </div>
        <div className="full">
          <label className="label">If extending close date — note to students (optional)</label>
          <input
            className="input"
            value={form.extendReason}
            onChange={update('extendReason')}
            placeholder="Venue confirmed later slots, more seats opened…"
          />
          <p className="subtle" style={{ fontSize: 10, marginTop: 4 }}>
            Moving the deadline later notifies every student on EventSphere.
          </p>
        </div>
        <div className="full">
          <label className="label">Rules</label>
          <textarea className="input" rows={2} value={form.rules} onChange={update('rules')} />
        </div>
        <EventVisualFields
          bannerUrl={form.bannerUrl}
          characterKey={form.characterKey}
          characterUrl={form.characterUrl}
          onChange={(patch) => setForm((f) => ({ ...f, ...patch }))}
        />
        <div className="full">
          <label style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 12, cursor: 'pointer' }}>
            <input
              type="checkbox"
              checked={Boolean(form.isPromoted)}
              onChange={(e) => setForm((f) => ({ ...f, isPromoted: e.target.checked }))}
              data-testid="checkbox-promote-event"
            />
            Feature on homepage / Recommended slider (14 days)
          </label>
        </div>
      </div>
      <div style={{ display: 'flex', gap: 8, marginTop: 18, flexWrap: 'wrap' }}>
        <button className="btn" type="button" style={{ flex: 1 }} onClick={onClose}>Close</button>
        <button className="btn" type="button" style={{ flex: 1 }} disabled={busy} onClick={saveExtendRegistration} data-testid="button-extend-registration">
          {busy ? 'Saving…' : 'Extend registration only'}
        </button>
        <button className="btn btn-primary" type="button" style={{ flex: 1 }} disabled={busy} onClick={saveEdit} data-testid="button-save-edit-event">
          {busy ? 'Saving…' : 'Save changes'}
        </button>
      </div>
    </EsModal>
  )
}

import { useCallback, useEffect, useId, useRef, useState } from 'react'
import { Html5Qrcode } from 'html5-qrcode'
import { Camera, CameraOff } from 'lucide-react'

function pickBackCamera(cameras) {
  if (!cameras?.length) return null
  const rear = cameras.find((c) => /back|rear|environment/i.test(c.label || ''))
  return rear || cameras[0]
}

export default function PassQrCameraScanner({
  active = true,
  disabled = false,
  onScan,
  scanCooldownMs = 2800,
}) {
  const elementId = useId().replace(/:/g, '')
  const scannerRef = useRef(null)
  const lastScanRef = useRef({ text: '', at: 0 })
  const onScanRef = useRef(onScan)
  const disabledRef = useRef(disabled)
  const [cameraOn, setCameraOn] = useState(true)
  const [starting, setStarting] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    onScanRef.current = onScan
  }, [onScan])

  useEffect(() => {
    disabledRef.current = disabled
  }, [disabled])

  const stopScanner = useCallback(async () => {
    const scanner = scannerRef.current
    if (!scanner) return
    scannerRef.current = null
    try {
      if (scanner.isScanning) await scanner.stop()
    } catch {
      /* ignore stop races */
    }
    try {
      scanner.clear()
    } catch {
      /* ignore clear races */
    }
  }, [])

  // Only start/stop when camera power or tab visibility changes — never on parent re-render.
  useEffect(() => {
    if (!active || !cameraOn) {
      void stopScanner()
      return undefined
    }

    let cancelled = false
    const scanner = new Html5Qrcode(elementId, { verbose: false })
    scannerRef.current = scanner
    setStarting(true)
    setError('')

    async function start() {
      try {
        const cameras = await Html5Qrcode.getCameras()
        if (cancelled) return
        const camera = pickBackCamera(cameras)
        if (!camera) {
          setError('No camera found on this device')
          setCameraOn(false)
          return
        }
        await scanner.start(
          camera.id,
          {
            fps: 10,
            qrbox: { width: 240, height: 240 },
            aspectRatio: 1,
          },
          (decodedText) => {
            if (cancelled) return
            const payload = String(decodedText || '').trim()
            if (!payload || disabledRef.current) return
            const now = Date.now()
            const last = lastScanRef.current
            if (payload === last.text && now - last.at < scanCooldownMs) return
            lastScanRef.current = { text: payload, at: now }
            onScanRef.current?.(payload)
          },
          () => {},
        )
        if (!cancelled) setError('')
      } catch (err) {
        if (!cancelled) {
          setError(err?.message || 'Could not access camera — allow permission and retry')
          setCameraOn(false)
        }
      } finally {
        if (!cancelled) setStarting(false)
      }
    }

    void start()

    return () => {
      cancelled = true
      void stopScanner()
    }
  }, [active, cameraOn, elementId, scanCooldownMs, stopScanner])

  useEffect(() => {
    if (active) setCameraOn(true)
    else setCameraOn(false)
  }, [active])

  return (
    <div className="es-qr-scan__camera" data-testid="pass-qr-camera">
      <div className="es-qr-scan__viewport-wrap">
        <div id={elementId} className="es-qr-scan__viewport" />
        {!cameraOn && (
          <div className="es-qr-scan__viewport-placeholder">
            <CameraOff size={28} strokeWidth={1.5} />
            <span>Camera off</span>
          </div>
        )}
        {starting && cameraOn && (
          <div className="es-qr-scan__viewport-loading">Starting camera…</div>
        )}
      </div>

      {error ? (
        <p className="es-qr-scan__camera-error" role="alert">
          {error}
        </p>
      ) : (
        <p className="muted es-qr-scan__camera-hint">
          Keep camera on — scan the next pass after each Present. Point at{' '}
          <strong>My Passes / Guest wallet</strong> QR.
        </p>
      )}

      <button
        type="button"
        className={`btn ${cameraOn ? '' : 'btn-primary'}`}
        disabled={starting}
        onClick={() => setCameraOn((on) => !on)}
        data-testid="button-toggle-camera"
      >
        {cameraOn ? <CameraOff size={14} /> : <Camera size={14} />}
        {cameraOn ? 'Turn camera off' : 'Turn camera on'}
      </button>
    </div>
  )
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { useAuth } from '@/context/AuthContext'
import { PAYMENT_STATUS_LABEL, TABLES } from '@/constants/domain'
import { formatMoney } from '@/lib/eventMappers'
import { listAllRegistrations, listEventRegistrations } from '@/services/registrations'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'
import OrganizerRegistrations from '@/components/organizer/OrganizerRegistrations'
import '@/styles/eventsphere-organizer-regs.css'

export default function RegistrationsDirectory({ events = [], setToast, scope = 'all' }) {
  const { user } = useAuth()
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)

  const scopedEvents = useMemo(() => {
    if (scope === 'organizer') {
      const owned = (events || []).filter((e) => e.organizerId === user?.id)
      return owned.length ? owned : events || []
    }
    return events || []
  }, [events, scope, user?.id])

  const load = useCallback(
    async (opts = {}) => {
      const silent = Boolean(opts.silent)
      if (!silent) setLoading(true)
      if (scope === 'all') {
        const { data, error } = await listAllRegistrations()
        if (error && !silent) setToast?.(error.message)
        setRows(data || [])
      } else {
        const batches = await Promise.all(
          scopedEvents.map(async (ev) => {
            const { data, error } = await listEventRegistrations(ev.id)
            if (error) return []
            return (data || []).map((r) => ({
              ...r,
              eventTitle: ev.title,
              organizerName: ev.organizer,
            }))
          }),
        )
        setRows(batches.flat())
      }
      if (!silent) setLoading(false)
    },
    [scope, scopedEvents, setToast],
  )

  useEffect(() => {
    load()
  }, [load])

  useRealtimeTables(
    [TABLES.REGISTRATIONS, TABLES.EVENT_PAYMENTS],
    () => load({ silent: true }),
    { channelName: `es-regs-${scope}` },
  )

  if (scope === 'organizer') {
    return (
      <OrganizerRegistrations
        rows={rows}
        events={scopedEvents}
        loading={loading}
        onRefresh={() => load()}
        setToast={setToast}
      />
    )
  }

  const paidCount = rows.filter(
    (r) => r.paymentStatus === 'paid' || r.paymentStatus === 'partially_refunded',
  ).length
  const pendingPay = rows.filter((r) => r.paymentStatus === 'pending').length
  const refunded = rows.filter(
    (r) => r.paymentStatus === 'partially_refunded' || r.paymentStatus === 'refunded',
  ).length
  const forfeited = rows.filter((r) => r.paymentStatus === 'forfeited').length

  return (
    <>
      <div className="page-head">
        <div>
          <div className="eyebrow">Operations</div>
          <h1>Registrations</h1>
          <p>Live registration rows from Supabase — including Stripe payment status.</p>
        </div>
      </div>
      <div className="grid-4" style={{ marginBottom: 16 }}>
        <div className="surface" style={{ padding: 14 }}>
          <div className="fact-label">Paid</div>
          <div className="fact-value">{paidCount}</div>
        </div>
        <div className="surface" style={{ padding: 14 }}>
          <div className="fact-label">Payment pending</div>
          <div className="fact-value">{pendingPay}</div>
        </div>
        <div className="surface" style={{ padding: 14 }}>
          <div className="fact-label">Refunded</div>
          <div className="fact-value">{refunded}</div>
        </div>
        <div className="surface" style={{ padding: 14 }}>
          <div className="fact-label">Forfeited</div>
          <div className="fact-value">{forfeited}</div>
        </div>
      </div>
      {loading && <p className="muted">Loading registrations…</p>}
      {!loading && !rows.length && (
        <div className="surface" style={{ padding: 24 }}>
          <p className="muted" style={{ margin: 0 }}>No registrations yet.</p>
        </div>
      )}
      <div className="surface table-wrap">
        <table className="data-table">
          <thead>
            <tr>
              <th>Student</th>
              <th>Event</th>
              <th>Organizer</th>
              <th>Registered</th>
              <th>Status</th>
              <th>Payment</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.id}>
                <td>
                  <strong>{r.student?.full_name || r.studentId || 'Student'}</strong>
                  <br />
                  <span className="subtle">{r.student?.email}</span>
                </td>
                <td>{r.eventTitle || r.event?.title || r.eventId}</td>
                <td>{r.organizerName || r.event?.organizer || '—'}</td>
                <td>{r.registeredOn ? new Date(r.registeredOn).toLocaleString() : '—'}</td>
                <td>{r.status}</td>
                <td data-testid={`payment-status-${r.id}`}>
                  {PAYMENT_STATUS_LABEL[r.paymentStatus] || r.paymentStatus || 'Free'}
                  {Number(r.amountTotal) > 0
                    ? ` · ${formatMoney(r.amountTotal, r.event?.currency || r.currency || 'pkr')}`
                    : ''}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { Download, Printer, RefreshCw, X } from 'lucide-react'
import { QRCodeSVG } from 'qrcode.react'
import { formatEventSchedule } from '@/lib/eventDate'
import { buildStationCheckinUrl } from '@/lib/stationCheckin'
import { ensureEventCheckinToken } from '@/services/events'

/**
 * Organizer/admin: generate station QR + print/save as PDF poster.
 */
export default function StationCheckinPoster({ event, open, onClose, setToast }) {
  const [meta, setMeta] = useState(null)
  const [busy, setBusy] = useState(false)
  const printRef = useRef(null)

  const load = useCallback(
    async (rotate = false) => {
      if (!event?.id) return
      setBusy(true)
      const { data, error } = await ensureEventCheckinToken(event.id, { rotate })
      setBusy(false)
      if (error) {
        setToast?.(error.message)
        return
      }
      setMeta(data)
      if (rotate) setToast?.('New station code generated — reprint the poster')
    },
    [event?.id, setToast],
  )

  useEffect(() => {
    if (open) load(false)
  }, [open, load])

  if (!open || typeof document === 'undefined') return null

  const token = meta?.checkin_token || ''
  const url = buildStationCheckinUrl(event.id, token)
  const title = meta?.title || event.title || 'Event'
  const venue = meta?.venue || event.venue || ''
  const when = formatEventSchedule({
    date: meta?.event_date || event.date,
    time: meta?.event_time || event.time,
    endTime: meta?.event_end_time || event.endTime,
  })

  const onPrint = () => {
    window.print()
  }

  const onCopyUrl = async () => {
    if (!url) return
    try {
      await navigator.clipboard?.writeText(url)
      setToast?.('Check-in link copied')
    } catch {
      setToast?.('Copy failed — select the link manually')
    }
  }

  return createPortal(
    <div
      className="modal-backdrop es-station-poster-root"
      role="presentation"
      data-es-no-reveal
      style={{ zIndex: 10060 }}
      onMouseDown={(e) => e.target === e.currentTarget && onClose?.()}
    >
      <div
        className="modal"
        role="dialog"
        aria-modal="true"
        style={{ width: 'min(640px, 100%)', pointerEvents: 'auto' }}
        onMouseDown={(e) => e.stopPropagation()}
      >
        <div className="modal-head">
          <h2>Station QR poster</h2>
          <button type="button" className="icon-btn" onClick={onClose} aria-label="Close">
            <X size={16} />
          </button>
        </div>
        <p className="muted" style={{ fontSize: 12, marginTop: 0, lineHeight: 1.45 }}>
          Print or Save as PDF, then post at the venue. Scan opens:{' '}
          <code style={{ fontSize: 11 }}>https://eventsphere-sceep.netlify.app/checkin/…</code>
        </p>

        <div ref={printRef} className="es-station-poster" data-testid="station-checkin-poster">
          <div className="es-station-poster__brand">EventSphere · Check-in</div>
          <h3 className="es-station-poster__title">{title}</h3>
          <p className="es-station-poster__when">
            {when}
            {venue ? ` · ${venue}` : ''}
          </p>
          <div className="es-station-poster__qr">
            {url ? (
              <QRCodeSVG value={url} size={220} level="M" includeMargin />
            ) : (
              <p className="muted">Generating code…</p>
            )}
          </div>
          <p className="es-station-poster__cta">Scan to mark your attendance</p>
          <p className="es-station-poster__hint">Must be registered · Sign in on your phone</p>
        </div>

        <p className="muted" style={{ fontSize: 11, wordBreak: 'break-all', marginTop: 10 }}>
          {url || '—'}
        </p>

        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 14 }}>
          <button type="button" className="btn btn-primary" disabled={busy || !url} onClick={onPrint} data-testid="button-print-station-qr">
            <Printer size={14} /> Print / Save PDF
          </button>
          <button type="button" className="btn" disabled={!url} onClick={onCopyUrl}>
            <Download size={14} /> Copy link
          </button>
          <button
            type="button"
            className="btn btn-quiet"
            disabled={busy}
            onClick={() => load(true)}
            data-testid="button-rotate-station-qr"
          >
            <RefreshCw size={14} /> New code
          </button>
        </div>
      </div>
    </div>,
    document.body,
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Pencil, Plus, Trash2 } from 'lucide-react'
import { TABLES, VENUE_AVAILABILITY } from '@/constants/domain'
import { createVenue, deleteVenue, listVenues, updateVenue } from '@/services/venues'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'
import VenueMapPicker from '@/components/ops/VenueMapPicker'
import EsModal from '@/components/shared/EsModal'
import { useConfirmDialog } from '@/hooks/useConfirmDialog.jsx'

const emptyForm = {
  name: '',
  location: '',
  capacity: '100',
  availability: VENUE_AVAILABILITY.AVAILABLE,
  latitude: null,
  longitude: null,
  map_place_id: null,
}

export default function VenuesManager({ events = [], setToast, canManage = true }) {
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [open, setOpen] = useState(false)
  const [editing, setEditing] = useState(null)
  const [busy, setBusy] = useState(false)
  const [form, setForm] = useState(emptyForm)
  const { confirm, dialog: confirmUi } = useConfirmDialog()

  const load = useCallback(async (opts = {}) => {
    const silent = Boolean(opts.silent)
    if (!silent) setLoading(true)
    const { data, error } = await listVenues()
    if (error && !silent) setToast?.(error.message)
    setRows(data || [])
    if (!silent) setLoading(false)
  }, [setToast])

  useEffect(() => {
    load()
  }, [load])

  useRealtimeTables([TABLES.VENUES], () => load({ silent: true }), {
    channelName: 'es-venues',
  })

  function openCreate() {
    setEditing(null)
    setForm(emptyForm)
    setOpen(true)
  }

  function openEdit(row) {
    setEditing(row)
    setForm({
      name: row.name || '',
      location: row.location || '',
      capacity: String(row.capacity ?? 100),
      availability: row.availability || VENUE_AVAILABILITY.AVAILABLE,
      latitude: row.latitude ?? null,
      longitude: row.longitude ?? null,
      map_place_id: row.map_place_id ?? null,
    })
    setOpen(true)
  }

  function closeForm() {
    setOpen(false)
    setEditing(null)
    setForm(emptyForm)
  }

  async function save() {
    if (!form.name.trim()) {
      setToast?.('Venue name is required')
      return
    }
    setBusy(true)
    const payload = {
      name: form.name.trim(),
      location: form.location,
      capacity: form.capacity,
      availability: form.availability,
      latitude: form.latitude,
      longitude: form.longitude,
      map_place_id: form.map_place_id,
    }
    const { error } = editing
      ? await updateVenue(editing.id, payload)
      : await createVenue(payload)
    setBusy(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    closeForm()
    setToast?.(editing ? 'Venue updated' : 'Venue added')
    load()
  }

  async function remove(row) {
    const ok = await confirm({
      title: 'Delete venue?',
      message: `"${row.name}" will be removed from the venue list.`,
      confirmLabel: 'Delete venue',
      tone: 'danger',
    })
    if (!ok) return
    const { error } = await deleteVenue(row.id)
    if (error) setToast?.(error.message)
    else {
      setToast?.('Venue deleted')
      load()
    }
  }

  function scheduledCount(name) {
    return (events || []).filter((e) => e.venue === name).length
  }

  return (
    <>
      {confirmUi}
      <div className="page-head">
        <div>
          <div className="eyebrow">Places & capacity</div>
          <h1>Venues</h1>
          <p>Live venues from Supabase. Used when creating events.</p>
        </div>
        {canManage && (
          <button className="btn btn-primary" type="button" onClick={openCreate} data-testid="button-add-venue">
            <Plus size={15} /> Add venue
          </button>
        )}
      </div>
      {loading && <p className="muted">Loading venues…</p>}
      {!loading && !rows.length && (
        <div className="surface" style={{ padding: 24 }}>
          <p className="muted" style={{ margin: 0 }}>No venues yet. Add one or run eventsphere-seed.sql.</p>
        </div>
      )}
      <div className="surface table-wrap">
        <table className="data-table">
          <thead>
            <tr>
              <th>Venue</th>
              <th>Location</th>
              <th>Capacity</th>
              <th>Scheduled events</th>
              <th>Availability</th>
              {canManage && <th>Actions</th>}
            </tr>
          </thead>
          <tbody>
            {rows.map((v) => (
              <tr key={v.id}>
                <td><strong>{v.name}</strong></td>
                <td>
                  {v.location || '—'}
                  {v.latitude != null && v.longitude != null && (
                    <div className="mono muted" style={{ fontSize: 11, marginTop: 2 }}>
                      {Number(v.latitude).toFixed(4)}, {Number(v.longitude).toFixed(4)}
                    </div>
                  )}
                </td>
                <td className="mono">{v.capacity}</td>
                <td>{scheduledCount(v.name)}</td>
                <td>
                  <span
                    style={{
                      color:
                        v.availability === 'booked'
                          ? 'var(--danger)'
                          : v.availability === 'limited'
                            ? '#ffca7f'
                            : 'var(--lime)',
                      textTransform: 'capitalize',
                    }}
                  >
                    {v.availability || 'available'}
                  </span>
                </td>
                {canManage && (
                  <td>
                    <div style={{ display: 'flex', gap: 4 }}>
                      <button className="btn btn-quiet" type="button" onClick={() => openEdit(v)} aria-label="Edit venue" data-testid={`button-edit-venue-${v.id}`}>
                        <Pencil size={14} />
                      </button>
                      <button className="btn btn-quiet btn-danger" type="button" onClick={() => remove(v)} aria-label="Delete venue" data-testid={`button-delete-venue-${v.id}`}>
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {open && (
        <EsModal title={editing ? 'Edit venue' : 'Add venue'} onClose={closeForm}>
          <div className="form-grid">
            <div>
              <label className="label">Venue name</label>
              <input
                className="input"
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                data-testid="input-venue-name"
                autoFocus
              />
            </div>
            <div>
              <label className="label">Capacity</label>
              <input
                className="input"
                type="number"
                value={form.capacity}
                onChange={(e) => setForm({ ...form, capacity: e.target.value })}
                data-testid="input-venue-capacity"
              />
            </div>
            <VenueMapPicker
              location={form.location}
              latitude={form.latitude}
              longitude={form.longitude}
              onChange={(geo) =>
                setForm((prev) => ({
                  ...prev,
                  location: geo.location ?? prev.location,
                  latitude: geo.latitude,
                  longitude: geo.longitude,
                  map_place_id: geo.map_place_id,
                }))
              }
            />
            <div className="full">
              <label className="label">Availability</label>
              <select
                className="input"
                value={form.availability}
                onChange={(e) => setForm({ ...form, availability: e.target.value })}
              >
                {Object.values(VENUE_AVAILABILITY).map((a) => (
                  <option key={a} value={a}>{a}</option>
                ))}
              </select>
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8, marginTop: 18 }}>
            <button className="btn" type="button" style={{ flex: 1 }} onClick={closeForm}>
              Cancel
            </button>
            <button className="btn btn-primary" style={{ flex: 1 }} type="button" disabled={busy} onClick={save} data-testid="button-save-venue">
              {busy ? 'Saving…' : editing ? 'Update venue' : 'Save venue'}
            </button>
          </div>
        </EsModal>
      )}
    </>
  )
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { Banknote, RefreshCw, Wallet } from 'lucide-react'
import EsModal from '@/components/shared/EsModal'
import { SETTLEMENT_STATUS, TABLES } from '@/constants/domain'
import { useConfirmDialog } from '@/hooks/useConfirmDialog.jsx'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'
import { formatMoney } from '@/lib/eventMappers'
import {
  isEarningsEligible,
  resolveRegistrationSplit,
} from '@/lib/commission'
import {
  cancelOrganizerWithdraw,
  listMyWithdrawRequests,
  requestOrganizerWithdraw,
} from '@/services/withdrawals'

const TABS = [
  { id: 'settled', label: 'Settled details' },
  { id: 'held', label: 'Held (due)' },
  { id: 'withdraw', label: 'Withdraw requests' },
]

function formatWhen(iso) {
  if (!iso) return '—'
  try {
    return new Intl.DateTimeFormat(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    }).format(new Date(iso))
  } catch {
    return iso
  }
}

export default function OrganizerEarningsPanel({
  rows = [],
  events = [],
  setToast,
  onRefreshRegs,
}) {
  const [tab, setTab] = useState('settled')
  const [withdraws, setWithdraws] = useState([])
  const [loadingW, setLoadingW] = useState(true)
  const [withdrawOpen, setWithdrawOpen] = useState(false)
  const [note, setNote] = useState('')
  const [busy, setBusy] = useState(false)
  const { confirm, dialog: confirmUi } = useConfirmDialog()

  const loadWithdraws = useCallback(async () => {
    setLoadingW(true)
    const { data, error } = await listMyWithdrawRequests()
    if (error) setToast?.(error.message)
    setWithdraws(data || [])
    setLoadingW(false)
  }, [setToast])

  useEffect(() => {
    loadWithdraws()
  }, [loadWithdraws])

  useRealtimeTables(
    [TABLES.ORGANIZER_WITHDRAW_REQUESTS, TABLES.REGISTRATIONS],
    () => {
      loadWithdraws()
      onRefreshRegs?.()
    },
    { channelName: 'es-org-earnings' },
  )

  const eventTitle = (eventId) =>
    events.find((e) => String(e.id) === String(eventId))?.title ||
    rows.find((r) => String(r.eventId) === String(eventId))?.eventTitle ||
    eventId

  const { heldRows, settledRows, earningsHeld, earningsSettled, platformCut } = useMemo(() => {
    const held = []
    const settled = []
    let h = 0
    let s = 0
    let p = 0
    for (const r of rows) {
      if (!isEarningsEligible(r) && r.settlementStatus !== SETTLEMENT_STATUS.SETTLED) continue
      if (r.settlementStatus === SETTLEMENT_STATUS.VOID) continue
      const split = resolveRegistrationSplit(r)
      if (split.fee <= 0 && split.organizerShare <= 0) continue
      p += split.platformFee
      if (r.settlementStatus === SETTLEMENT_STATUS.SETTLED) {
        settled.push({ ...r, split })
        s += split.organizerShare
      } else if (
        r.settlementStatus === SETTLEMENT_STATUS.HELD ||
        (split.organizerShare > 0 && isEarningsEligible(r))
      ) {
        held.push({ ...r, split })
        h += split.organizerShare
      }
    }
    settled.sort((a, b) => String(b.settledAt || '').localeCompare(String(a.settledAt || '')))
    return {
      heldRows: held,
      settledRows: settled,
      earningsHeld: h,
      earningsSettled: s,
      platformCut: p,
    }
  }, [rows])

  const pendingWithdraw = withdraws.find((w) => w.status === 'pending')

  const submitWithdraw = async () => {
    if (earningsHeld <= 0) {
      await confirm({
        title: 'Nothing to withdraw',
        message: 'You have no held earnings yet. After students pay entry fees, your 80% share appears as Held.',
        confirmLabel: 'Got it',
        hideCancel: true,
      })
      return
    }
    setBusy(true)
    const { data, error } = await requestOrganizerWithdraw(note)
    setBusy(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    setWithdrawOpen(false)
    setNote('')
    setToast?.(
      `Demo withdraw requested for ${formatMoney(data?.amount || earningsHeld, 'pkr')}. Waiting for admin approval.`,
    )
    setTab('withdraw')
    await loadWithdraws()
  }

  const cancelPending = async (id) => {
    const ok = await confirm({
      title: 'Cancel withdraw request?',
      message: 'Your held earnings stay available. You can request again later.',
      confirmLabel: 'Cancel request',
      cancelLabel: 'Keep pending',
      tone: 'danger',
    })
    if (!ok) return
    const { error } = await cancelOrganizerWithdraw(id)
    if (error) setToast?.(error.message)
    else setToast?.('Withdraw request cancelled')
    await loadWithdraws()
  }

  return (
    <div className="surface es-earnings-panel" data-testid="organizer-earnings" style={{ padding: 18 }}>
      {confirmUi}
      <div className="eyebrow">Earnings & settlement</div>
      <h2 style={{ margin: '6px 0 8px', font: '600 20px var(--font-display)' }}>
        Your organizer share
      </h2>
      <p className="es-earnings-panel__note">
        Platform keeps 20% of each entry fee. Your 80% is <strong>held</strong> until admin settles
        (or approves your demo withdraw). Deposits are not included. This is a campus demo — no real
        bank transfer.
      </p>

      <div className="grid-3" style={{ marginBottom: 8 }}>
        <div>
          <div className="fact-label">Due (held)</div>
          <div className="fact-value">{formatMoney(earningsHeld, 'pkr')}</div>
        </div>
        <div>
          <div className="fact-label">Settled to you</div>
          <div className="fact-value" style={{ color: 'var(--lime)' }}>
            {formatMoney(earningsSettled, 'pkr')}
          </div>
        </div>
        <div>
          <div className="fact-label">Platform cut (info)</div>
          <div className="fact-value">{formatMoney(platformCut, 'pkr')}</div>
        </div>
      </div>

      <div className="es-earnings-panel__actions">
        <button
          type="button"
          className="btn btn-primary"
          disabled={Boolean(pendingWithdraw) || earningsHeld <= 0}
          onClick={() => setWithdrawOpen(true)}
          data-testid="button-demo-withdraw"
        >
          <Wallet size={14} /> Demo withdraw
        </button>
        <button type="button" className="btn" onClick={() => { loadWithdraws(); onRefreshRegs?.() }}>
          <RefreshCw size={14} /> Refresh
        </button>
        {pendingWithdraw ? (
          <span className="badge badge-pending">Withdraw pending · {formatMoney(pendingWithdraw.amount, 'pkr')}</span>
        ) : null}
      </div>

      <div className="es-earnings-panel__tabs chips">
        {TABS.map((t) => (
          <button
            key={t.id}
            type="button"
            className={`chip ${tab === t.id ? 'active' : ''}`}
            onClick={() => setTab(t.id)}
          >
            {t.label}
          </button>
        ))}
      </div>

      {tab === 'settled' && (
        <>
          {!settledRows.length ? (
            <p className="muted" style={{ margin: 0, fontSize: 13 }}>
              No settled payouts yet. When admin marks your share settled (or approves withdraw),
              each booking appears here with student, event, amount, and time.
            </p>
          ) : (
            <div className="table-wrap">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Settled on</th>
                    <th>Student</th>
                    <th>Event</th>
                    <th>Entry fee</th>
                    <th>Your share (80%)</th>
                    <th>Platform (20%)</th>
                  </tr>
                </thead>
                <tbody>
                  {settledRows.map((r) => (
                    <tr key={r.id} data-testid={`settled-row-${r.id}`}>
                      <td>{formatWhen(r.settledAt)}</td>
                      <td>
                        <strong>{r.student?.full_name || 'Attendee'}</strong>
                        <br />
                        <span className="subtle">{r.student?.email}</span>
                      </td>
                      <td>{eventTitle(r.eventId)}</td>
                      <td>{formatMoney(r.split.fee, 'pkr')}</td>
                      <td>
                        <strong>{formatMoney(r.split.organizerShare, 'pkr')}</strong>
                      </td>
                      <td>{formatMoney(r.split.platformFee, 'pkr')}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {tab === 'held' && (
        <>
          {!heldRows.length ? (
            <p className="muted" style={{ margin: 0, fontSize: 13 }}>
              No held earnings. Paid entry fees on your events will show here until admin settles.
            </p>
          ) : (
            <div className="table-wrap">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Paid on</th>
                    <th>Student</th>
                    <th>Event</th>
                    <th>Your share</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {heldRows.map((r) => (
                    <tr key={r.id}>
                      <td>{formatWhen(r.paidAt || r.registeredOn)}</td>
                      <td>
                        <strong>{r.student?.full_name || 'Attendee'}</strong>
                        <br />
                        <span className="subtle">{r.student?.email}</span>
                      </td>
                      <td>{eventTitle(r.eventId)}</td>
                      <td>
                        <strong>{formatMoney(r.split.organizerShare, 'pkr')}</strong>
                      </td>
                      <td>
                        <span className="badge badge-pending">Held</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {tab === 'withdraw' && (
        <>
          {loadingW ? (
            <p className="muted">Loading withdraw history…</p>
          ) : !withdraws.length ? (
            <p className="muted" style={{ margin: 0, fontSize: 13 }}>
              No withdraw requests yet. Use <strong>Demo withdraw</strong> when you have held
              earnings.
            </p>
          ) : (
            <div className="table-wrap">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Requested</th>
                    <th>Amount</th>
                    <th>Bookings</th>
                    <th>Status</th>
                    <th>Admin note</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {withdraws.map((w) => (
                    <tr key={w.id}>
                      <td>{formatWhen(w.createdAt)}</td>
                      <td>
                        <strong>{formatMoney(w.amount, w.currency)}</strong>
                      </td>
                      <td>{(w.heldRegistrationIds || []).length}</td>
                      <td>
                        <span
                          className={`badge ${
                            w.status === 'approved'
                              ? 'badge-approved'
                              : w.status === 'pending'
                                ? 'badge-pending'
                                : 'badge-cancelled'
                          }`}
                        >
                          {w.status}
                        </span>
                        {w.processedAt ? (
                          <>
                            <br />
                            <span className="subtle">{formatWhen(w.processedAt)}</span>
                          </>
                        ) : null}
                      </td>
                      <td>{w.adminNote || w.note || '—'}</td>
                      <td>
                        {w.status === 'pending' ? (
                          <button className="btn btn-quiet" type="button" onClick={() => cancelPending(w.id)}>
                            Cancel
                          </button>
                        ) : null}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {withdrawOpen ? (
        <EsModal title="Demo withdraw request" onClose={() => !busy && setWithdrawOpen(false)}>
          <p className="muted" style={{ fontSize: 13, marginTop: 0 }}>
            Request <strong>{formatMoney(earningsHeld, 'pkr')}</strong> from{' '}
            <strong>{heldRows.length}</strong> held booking{heldRows.length === 1 ? '' : 's'}. Admin
            will approve to mark those shares <strong>settled</strong> (offline payout demo — no
            bank API).
          </p>
          <label className="label">Note for admin (optional)</label>
          <textarea
            className="input"
            rows={3}
            value={note}
            onChange={(e) => setNote(e.target.value)}
            placeholder="e.g. Please settle via JazzCash this week"
            data-testid="input-withdraw-note"
          />
          <div className="es-confirm-dialog__actions" style={{ marginTop: 16 }}>
            <button className="btn" type="button" disabled={busy} onClick={() => setWithdrawOpen(false)}>
              Close
            </button>
            <button
              className="btn btn-primary"
              type="button"
              disabled={busy}
              onClick={submitWithdraw}
              data-testid="button-submit-withdraw"
            >
              <Banknote size={14} /> {busy ? 'Submitting…' : 'Submit request'}
            </button>
          </div>
        </EsModal>
      ) : null}
    </div>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { ArrowLeft, MessageCircle, Search, Send } from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import { EsPageChrome } from '@/components/design-system'
import { listOrganizerQuestions, replyToQuestion } from '@/services/questions'
import { isSupabaseConfigured, supabase } from '@/lib/supabase'

function threadKey(row) {
  return `${row.student_id}::${row.event_id}`
}

function initials(name, email) {
  const src = String(name || email || '?').trim()
  const parts = src.split(/\s+/).filter(Boolean)
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase()
  return src.slice(0, 2).toUpperCase()
}

function buildThreads(rows) {
  const map = new Map()
  for (const row of rows || []) {
    const key = threadKey(row)
    if (!map.has(key)) {
      map.set(key, {
        key,
        studentId: row.student_id,
        eventId: row.event_id,
        eventTitle: row.events?.title || 'Event',
        name: row.profiles?.full_name || 'Student',
        email: row.profiles?.email || '',
        messages: [],
      })
    }
    const t = map.get(key)
    if (row.profiles?.full_name) t.name = row.profiles.full_name
    if (row.profiles?.email) t.email = row.profiles.email
    if (row.events?.title) t.eventTitle = row.events.title
    t.messages.push(row)
  }

  const threads = [...map.values()].map((t) => {
    const messages = [...t.messages].sort(
      (a, b) => new Date(a.created_at) - new Date(b.created_at),
    )
    const last = messages[messages.length - 1]
    const unanswered = messages.filter((m) => !m.answer).length
    const preview = last?.answer
      ? `You: ${last.answer}`
      : last?.question || ''
    const lastAt = last?.answered_at || last?.created_at
    return {
      ...t,
      messages,
      unanswered,
      preview,
      lastAt,
    }
  })

  threads.sort((a, b) => new Date(b.lastAt || 0) - new Date(a.lastAt || 0))
  return threads
}

export default function OrganizerQuestionsInbox({ events = [], setToast }) {
  const { user } = useAuth()
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [activeKey, setActiveKey] = useState(null)
  const [draft, setDraft] = useState('')
  const [busy, setBusy] = useState(false)
  const [query, setQuery] = useState('')
  const [mobileChat, setMobileChat] = useState(false)
  const scrollerRef = useRef(null)

  const myEventIds = useMemo(() => {
    if (!user?.id) return []
    return (events || [])
      .filter((e) => e.organizerId === user.id || e.organizer_id === user.id)
      .map((e) => e.id)
      .filter(Boolean)
  }, [events, user?.id])

  const load = useCallback(async () => {
    if (!user?.id) {
      setRows([])
      setLoading(false)
      return
    }
    setLoading(true)
    const { data, error } = await listOrganizerQuestions(myEventIds, user.id)
    if (error) setToast?.(error.message)
    setRows(data || [])
    setLoading(false)
  }, [myEventIds, user?.id, setToast])

  useEffect(() => {
    load()
  }, [load])

  useEffect(() => {
    if (!isSupabaseConfigured || !user?.id) return undefined
    const channel = supabase
      .channel(`org-questions-chat-${user.id}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'event_questions' },
        () => load(),
      )
      .subscribe()
    return () => {
      supabase.removeChannel(channel)
    }
  }, [user?.id, load])

  const threads = useMemo(() => buildThreads(rows), [rows])

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return threads
    return threads.filter(
      (t) =>
        t.name.toLowerCase().includes(q) ||
        t.email.toLowerCase().includes(q) ||
        t.eventTitle.toLowerCase().includes(q) ||
        t.preview.toLowerCase().includes(q),
    )
  }, [threads, query])

  const active = useMemo(
    () => threads.find((t) => t.key === activeKey) || null,
    [threads, activeKey],
  )

  useEffect(() => {
    if (activeKey && !threads.some((t) => t.key === activeKey)) {
      setActiveKey(null)
      setMobileChat(false)
    }
  }, [threads, activeKey])

  useEffect(() => {
    const el = scrollerRef.current
    if (!el || !active) return
    el.scrollTop = el.scrollHeight
  }, [active])

  const openChat = (key) => {
    setActiveKey(key)
    setDraft('')
    setMobileChat(true)
  }

  const closeChat = () => {
    setMobileChat(false)
  }

  const replyTarget = active?.messages?.filter((m) => !m.answer).slice(-1)[0] || null

  const sendReply = async (e) => {
    e?.preventDefault?.()
    if (!active || !replyTarget || !draft.trim()) return
    setBusy(true)
    const { error } = await replyToQuestion({
      questionId: replyTarget.id,
      answer: draft,
      answeredBy: user?.id,
      studentId: active.studentId,
      eventTitle: active.eventTitle,
    })
    setBusy(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    setDraft('')
    setToast?.('Reply sent')
    await load()
  }

  return (
    <>
      <EsPageChrome
        eyebrow="Student chats"
        title="Ask Organizer"
        description="WhatsApp-style inbox — open a student to see full history, then reply in the thread."
      />

      {loading ? (
        <p className="muted">Loading chats…</p>
      ) : !threads.length ? (
        <div className="surface empty">
          <MessageCircle size={22} />
          <h3>No chats yet</h3>
          <p className="muted">When students ask a question, their chat appears here with name and email.</p>
          <button type="button" className="btn" style={{ marginTop: 12 }} onClick={load}>
            Refresh
          </button>
        </div>
      ) : (
        <div className={`es-org-chat ${mobileChat ? 'es-org-chat--mobile-open' : ''}`}>
          <aside className="es-org-chat__list surface">
            <div className="es-org-chat__list-head">
              <h2>Chats</h2>
              <div className="es-org-chat__search">
                <Search size={14} />
                <input
                  className="input"
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  placeholder="Search name or email…"
                  aria-label="Search chats"
                />
              </div>
            </div>
            <ul className="es-org-chat__contacts">
              {filtered.map((t) => {
                const selected = t.key === activeKey
                return (
                  <li key={t.key}>
                    <button
                      type="button"
                      className={`es-org-chat__contact ${selected ? 'is-active' : ''}`}
                      onClick={() => openChat(t.key)}
                    >
                      <span className="es-org-chat__avatar" aria-hidden>
                        {initials(t.name, t.email)}
                      </span>
                      <span className="es-org-chat__meta">
                        <span className="es-org-chat__name-row">
                          <strong>{t.name}</strong>
                          <time>
                            {t.lastAt
                              ? new Date(t.lastAt).toLocaleTimeString([], {
                                  hour: '2-digit',
                                  minute: '2-digit',
                                })
                              : ''}
                          </time>
                        </span>
                        <span className="es-org-chat__email">{t.email || 'No email'}</span>
                        <span className="es-org-chat__preview">
                          <span className="es-org-chat__event">{t.eventTitle}</span>
                          {' · '}
                          {t.preview.slice(0, 64)}
                          {t.preview.length > 64 ? '…' : ''}
                        </span>
                      </span>
                      {t.unanswered > 0 ? (
                        <span className="es-org-chat__badge">{t.unanswered}</span>
                      ) : null}
                    </button>
                  </li>
                )
              })}
              {!filtered.length ? (
                <li className="muted" style={{ padding: 16, fontSize: 13 }}>
                  No chats match your search.
                </li>
              ) : null}
            </ul>
          </aside>

          <section className="es-org-chat__panel surface">
            {!active ? (
              <div className="es-org-chat__empty">
                <MessageCircle size={28} />
                <h3>Select a chat</h3>
                <p className="muted">Pick a student on the left to open their message history.</p>
              </div>
            ) : (
              <>
                <header className="es-org-chat__header">
                  <button
                    type="button"
                    className="icon-btn es-org-chat__back"
                    onClick={closeChat}
                    aria-label="Back to chats"
                  >
                    <ArrowLeft size={16} />
                  </button>
                  <span className="es-org-chat__avatar" aria-hidden>
                    {initials(active.name, active.email)}
                  </span>
                  <div className="es-org-chat__header-text">
                    <strong>{active.name}</strong>
                    <span className="muted">{active.email || 'No email on profile'}</span>
                    <span className="eyebrow">{active.eventTitle}</span>
                  </div>
                </header>

                <div className="es-org-chat__messages" ref={scrollerRef}>
                  {active.messages.map((m) => (
                    <div key={m.id} className="es-org-chat__turn">
                      <div className="es-org-chat__bubble es-org-chat__bubble--in">
                        <p>{m.question}</p>
                        <time>
                          {m.created_at ? new Date(m.created_at).toLocaleString() : ''}
                        </time>
                      </div>
                      {m.answer ? (
                        <div className="es-org-chat__bubble es-org-chat__bubble--out">
                          <p>{m.answer}</p>
                          <time>
                            {m.answered_at
                              ? new Date(m.answered_at).toLocaleString()
                              : 'Replied'}
                          </time>
                        </div>
                      ) : null}
                    </div>
                  ))}
                </div>

                <form className="es-org-chat__composer" onSubmit={sendReply}>
                  {replyTarget ? (
                    <>
                      <input
                        className="input"
                        value={draft}
                        onChange={(e) => setDraft(e.target.value)}
                        placeholder={`Reply to ${active.name}…`}
                        disabled={busy}
                        data-testid="input-org-chat-reply"
                      />
                      <button
                        type="submit"
                        className="btn btn-primary"
                        disabled={busy || !draft.trim()}
                        aria-label="Send reply"
                      >
                        <Send size={15} />
                      </button>
                    </>
                  ) : (
                    <p className="muted" style={{ margin: 0, fontSize: 12, padding: '8px 4px' }}>
                      Waiting for the next question from {active.name}. All messages in this chat are answered.
                    </p>
                  )}
                </form>
              </>
            )}
          </section>
        </div>
      )}
    </>
  )
}

import { useEffect, useRef, useState } from 'react'
import { Bell, Plus, Radio, Send } from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import { ANNOUNCEMENT_AUDIENCE, TABLES } from '@/constants/domain'
import { createAnnouncement, listAnnouncements } from '@/services/announcements'
import { listMyNotices, markNoticeRead } from '@/services/studentExperience'
import { isSupabaseConfigured, supabase } from '@/lib/supabase'
import EsModal from '@/components/shared/EsModal'

function audienceForRole(role) {
  if (role === 'admin') return ANNOUNCEMENT_AUDIENCE.ADMINS
  if (role === 'organizer') return ANNOUNCEMENT_AUDIENCE.ORGANIZERS
  return ANNOUNCEMENT_AUDIENCE.STUDENTS
}

function visibleToRole(row, role) {
  const aud = row?.audience
  if (!aud || aud === ANNOUNCEMENT_AUDIENCE.EVERYONE) return true
  if (role === 'admin') return aud === ANNOUNCEMENT_AUDIENCE.ADMINS || aud === ANNOUNCEMENT_AUDIENCE.EVERYONE
  if (role === 'organizer') {
    return aud === ANNOUNCEMENT_AUDIENCE.ORGANIZERS || aud === ANNOUNCEMENT_AUDIENCE.EVERYONE
  }
  return aud === ANNOUNCEMENT_AUDIENCE.STUDENTS || aud === ANNOUNCEMENT_AUDIENCE.EVERYONE
}

export default function LiveAnnouncements({ role, setToast, canPublish = false }) {
  const { user } = useAuth()
  const [rows, setRows] = useState([])
  const [personal, setPersonal] = useState([])
  const [loading, setLoading] = useState(true)
  const [open, setOpen] = useState(false)
  const [live, setLive] = useState(false)
  const [form, setForm] = useState({
    title: '',
    body: '',
    audience: ANNOUNCEMENT_AUDIENCE.EVERYONE,
  })
  const knownIds = useRef(new Set())

  async function load() {
    setLoading(true)
    const { data, error } = await listAnnouncements({ audience: audienceForRole(role) })
    if (error) setToast?.(error.message)
    const list = data || []
    knownIds.current = new Set(list.map((r) => r.id))
    setRows(list)
    if (role === 'student' || role === 'organizer' || (!canPublish && role)) {
      const { data: notices } = await listMyNotices({ limit: 20 })
      setPersonal(notices || [])
    } else {
      setPersonal([])
    }
    setLoading(false)
  }

  useEffect(() => {
    load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [role])

  useEffect(() => {
    if (!isSupabaseConfigured) return undefined
    const channel = supabase
      .channel(`announcements-live-${role || 'guest'}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: TABLES.ANNOUNCEMENTS },
        (payload) => {
          const row = payload.new
          if (!row || row.is_published === false) {
            if (payload.eventType === 'DELETE' || payload.old?.id) {
              const id = payload.old?.id || row?.id
              setRows((prev) => prev.filter((r) => r.id !== id))
            }
            return
          }
          if (!visibleToRole(row, role)) return
          setRows((prev) => {
            const without = prev.filter((r) => r.id !== row.id)
            return [row, ...without].sort((a, b) =>
              String(b.published_at || '').localeCompare(String(a.published_at || '')),
            )
          })
          if (payload.eventType === 'INSERT' && row.id && !knownIds.current.has(row.id)) {
            knownIds.current.add(row.id)
            setToast?.(`Live: ${row.title || 'New announcement'}`)
          }
        },
      )
      .subscribe((status) => {
        setLive(status === 'SUBSCRIBED')
      })

    return () => {
      supabase.removeChannel(channel)
      setLive(false)
    }
  }, [role, setToast])

  async function publish() {
    if (!form.title.trim()) {
      setToast?.('Title is required')
      return
    }
    const { error } = await createAnnouncement({
      ...form,
      createdBy: user?.id,
      isPublished: true,
    })
    if (error) {
      setToast?.(error.message)
      return
    }
    setOpen(false)
    setForm({ title: '', body: '', audience: ANNOUNCEMENT_AUDIENCE.EVERYONE })
    setToast?.('Announcement published')
    load()
  }

  return (
    <>
      <div className="page-head">
        <div>
          <div className="eyebrow">{canPublish ? 'Broadcast studio' : 'Your signal'}</div>
          <h1>{canPublish ? 'Announcements' : 'Notifications'}</h1>
          <p>
            {canPublish
              ? 'Publish to the campus orbit — listeners update in realtime.'
              : 'Announcements stream live from Supabase Realtime when enabled.'}
          </p>
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
          <span
            className={`chip ${live ? 'active' : ''}`}
            aria-live="polite"
            title={live ? 'Realtime connected' : 'Realtime connecting / offline'}
          >
            <Radio size={12} /> {live ? 'Live' : 'Polling'}
          </span>
          {canPublish && (
            <button className="btn btn-primary" type="button" onClick={() => setOpen(true)} data-testid="button-new-announcement">
              <Plus size={15} /> New announcement
            </button>
          )}
        </div>
      </div>

      {loading && <p className="muted">Loading…</p>}
      {!loading && !rows.length && !personal.length && (
        <div className="surface" style={{ padding: 24 }}>
          <p className="muted" style={{ margin: 0 }}>No published announcements yet.</p>
        </div>
      )}

      {!!personal.length && (
        <div className="surface" style={{ padding: '5px 20px', marginBottom: 14 }} role="feed" aria-label="Personal notices">
          <div className="eyebrow" style={{ paddingTop: 14 }}>Personal signals</div>
          {personal.map((n) => (
            <article className="notification-row" key={`n-${n.id}`}>
              <span className="avatar" aria-hidden="true">
                <Bell size={13} />
              </span>
              <div style={{ flex: 1 }}>
                <p>
                  <strong>{n.title}</strong>
                  <br />
                  {n.body}
                </p>
                <time dateTime={n.created_at || undefined}>
                  {n.kind}
                  {' · '}
                  {n.events?.title || 'Event'}
                  {' · '}
                  {n.created_at ? new Date(n.created_at).toLocaleString() : '—'}
                </time>
              </div>
              {!n.read_at && (
                <button
                  className="btn btn-quiet"
                  type="button"
                  onClick={async () => {
                    await markNoticeRead(n.id)
                    load()
                  }}
                >
                  Mark read
                </button>
              )}
            </article>
          ))}
        </div>
      )}

      <div className="surface" style={{ padding: '5px 20px' }} role="feed" aria-label="Campus announcements">
        {rows.map((n) => (
          <article className="notification-row" key={n.id}>
            <span className="avatar" aria-hidden="true">
              <Bell size={13} />
            </span>
            <div>
              <p>
                <strong>{n.title}</strong>
                <br />
                {n.body}
              </p>
              <time dateTime={n.published_at || undefined}>
                From: {n.profiles?.full_name || 'Campus staff'}
                {n.profiles?.role ? ` (${n.profiles.role})` : ''}
                {' · '}
                {n.audience}
                {' · '}
                {n.published_at ? new Date(n.published_at).toLocaleString() : '—'}
              </time>
            </div>
          </article>
        ))}
      </div>

      {open && (
        <EsModal title="Publish announcement" onClose={() => setOpen(false)} labelledBy="announcement-dialog-title">
            <div className="form-grid">
              <div className="full">
                <label className="label" htmlFor="announcement-title">Title</label>
                <input
                  id="announcement-title"
                  className="input"
                  value={form.title}
                  onChange={(e) => setForm({ ...form, title: e.target.value })}
                  data-testid="input-announcement-title"
                />
              </div>
              <div className="full">
                <label className="label" htmlFor="announcement-body">Message</label>
                <textarea
                  id="announcement-body"
                  className="input"
                  rows={4}
                  value={form.body}
                  onChange={(e) => setForm({ ...form, body: e.target.value })}
                />
              </div>
              <div className="full">
                <label className="label" htmlFor="announcement-audience">Audience</label>
                <select
                  id="announcement-audience"
                  className="input"
                  value={form.audience}
                  onChange={(e) => setForm({ ...form, audience: e.target.value })}
                >
                  {Object.values(ANNOUNCEMENT_AUDIENCE).map((a) => (
                    <option key={a} value={a}>
                      {a}
                    </option>
                  ))}
                </select>
              </div>
            </div>
            <button className="btn btn-primary" style={{ width: '100%', marginTop: 18 }} type="button" onClick={publish}>
              <Send size={14} /> Publish announcement
            </button>
        </EsModal>
      )}
    </>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Award, Check, CheckCircle2, QrCode, Upload, UserCheck } from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import { ATTENDANCE_METHOD, REGISTRATION_STATUS, TABLES } from '@/constants/domain'
import { formatMoney } from '@/lib/eventMappers'
import {
  eventNotStartedMessage,
  formatEventSchedule,
  getEventPhase,
  isEventDayOrPast,
  isEventEnded,
} from '@/lib/eventDate'
import { parseAttendancePayload } from '@/lib/qrPayload'
import { listEventAttendance, markAttendance } from '@/services/attendance'
import { listEventRegistrations, updateRegistrationStatus } from '@/services/registrations'
import { processRegistrationPayment } from '@/services/payments'
import { issueCertificate, listCertificatesForEvent } from '@/services/certificates'
import { addMedia } from '@/services/media'
import { uploadEventMedia } from '@/services/storage'
import MediaModeration from '@/components/ops/MediaModeration'
import PassQrCameraScanner from '@/components/ops/PassQrCameraScanner'
import StationCheckinPoster from '@/components/ops/StationCheckinPoster'
import { useRealtimeTables } from '@/hooks/useRealtimeTables'
import { attendanceMethodLabel } from '@/lib/stationCheckin'
import { attendeeAudience, isPublicGuestRole } from '@/constants/roles'

function studentKey(row) {
  return row?.studentId || row?.student_id || row?.student?.id || ''
}

function rowIsPublicGuest(row) {
  return (
    isPublicGuestRole(row?.student?.role) ||
    isPublicGuestRole(row?.profiles?.role) ||
    attendeeAudience(row?.student || row?.profiles) === 'public'
  )
}

export default function OrganizerOpsPanel({ events, setToast }) {
  const { user } = useAuth()
  const mine = useMemo(() => {
    const list = events || []
    const owned = list.filter((e) => e.organizerId && user?.id && e.organizerId === user.id)
    return owned.length ? owned : list
  }, [events, user?.id])
  const [eventId, setEventId] = useState(mine[0]?.id || '')
  const [tab, setTab] = useState('attendance')
  const [regs, setRegs] = useState([])
  const [attendance, setAttendance] = useState([])
  const [qrText, setQrText] = useState('')
  const [busy, setBusy] = useState(false)
  const [markingId, setMarkingId] = useState('')
  const [statusMsg, setStatusMsg] = useState('')
  const [statusKind, setStatusKind] = useState('ok') // ok | err
  const [caption, setCaption] = useState('')
  const [certs, setCerts] = useState([])
  const [certUrl, setCertUrl] = useState('')
  const [mediaTick, setMediaTick] = useState(0)
  const [stationPosterOpen, setStationPosterOpen] = useState(false)
  const [lastScanMsg, setLastScanMsg] = useState('')
  const [lastScanKind, setLastScanKind] = useState('ok')
  const qrBusyRef = useRef(false)

  useEffect(() => {
    if (!eventId && mine[0]?.id) setEventId(mine[0].id)
  }, [mine, eventId])

  const selectedEvent = mine.find((e) => String(e.id) === String(eventId))
  const attendanceUnlocked = isEventDayOrPast(selectedEvent?.date)
  const certsUnlocked = selectedEvent ? isEventEnded(selectedEvent) : false
  const phase = selectedEvent ? getEventPhase(selectedEvent) : 'unknown'

  function flash(message, kind = 'ok') {
    setStatusMsg(message)
    setStatusKind(kind)
    setToast?.(message)
  }

  const refresh = useCallback(async () => {
    if (!eventId) return
    const [r, a, c] = await Promise.all([
      listEventRegistrations(eventId),
      listEventAttendance(eventId),
      listCertificatesForEvent(eventId),
    ])
    if (!r.error) setRegs(r.data || [])
    if (!a.error) setAttendance(a.data || [])
    if (!c.error) setCerts(c.data || [])
  }, [eventId])

  useEffect(() => {
    setStatusMsg('')
    refresh()
  }, [eventId, refresh])

  useRealtimeTables(
    [TABLES.REGISTRATIONS, TABLES.ATTENDANCE, TABLES.CERTIFICATES, TABLES.MEDIA_GALLERY],
    refresh,
    { channelName: `es-org-ops-${eventId || 'none'}`, enabled: Boolean(eventId) },
  )

  async function markManual(studentId, label) {
    if (!eventId) {
      flash('Select an event first', 'err')
      return
    }
    if (!attendanceUnlocked) {
      flash(eventNotStartedMessage(selectedEvent?.date), 'err')
      return
    }
    if (!studentId) {
      flash('Missing student id on this registration row', 'err')
      return
    }
    setBusy(true)
    setMarkingId(studentId)
    const { data, error } = await markAttendance({
      eventId,
      studentId,
      attended: true,
      method: ATTENDANCE_METHOD.MANUAL,
      markedBy: user?.id,
    })
    setBusy(false)
    setMarkingId('')
    if (error) {
      flash(error.message || 'Could not mark attendance', 'err')
      return
    }
    // Optimistic UI so Present shows immediately
    setAttendance((prev) => {
      const others = (prev || []).filter((a) => a.student_id !== studentId)
      return [
        data || {
          event_id: eventId,
          student_id: studentId,
          attended: true,
          method: ATTENDANCE_METHOD.MANUAL,
        },
        ...others,
      ]
    })
    flash(`Attendance marked: ${label || 'student'} is Present`, 'ok')
    // Auto-refund security deposit after Present (Stripe sandbox)
    const reg = (regs || []).find((r) => String(studentKey(r)) === String(studentId))
    if (reg?.id && Number(reg.depositAmount || 0) > 0 && reg.paymentStatus === 'paid') {
      const { error: refundErr } = await processRegistrationPayment({
        registrationId: reg.id,
        eventId,
        kind: 'deposit',
        studentId,
      })
      if (refundErr) flash(`Present saved — deposit refund: ${refundErr.message}`, 'err')
      else flash(`Present + security deposit refunded`, 'ok')
    }
    await refresh()
  }

  const markFromQrText = useCallback(
    async (rawText, { clearInput = false } = {}) => {
      if (qrBusyRef.current) return
      if (!attendanceUnlocked) {
        const msg = eventNotStartedMessage(selectedEvent?.date)
        setLastScanMsg(msg)
        setLastScanKind('err')
        setStatusMsg(msg)
        setStatusKind('err')
        setToast?.(msg)
        return
      }
      const { data, error } = parseAttendancePayload(rawText)
      if (error) {
        setLastScanMsg(error.message)
        setLastScanKind('err')
        setStatusMsg(error.message)
        setStatusKind('err')
        setToast?.(error.message)
        return
      }
      if (!eventId) {
        const msg = 'Select an event first'
        setLastScanMsg(msg)
        setLastScanKind('err')
        setStatusMsg(msg)
        setStatusKind('err')
        setToast?.(msg)
        return
      }
      if (String(data.eventId) !== String(eventId)) {
        const msg = 'QR belongs to a different event — switch the event selector'
        setLastScanMsg(msg)
        setLastScanKind('err')
        setStatusMsg(msg)
        setStatusKind('err')
        setToast?.(msg)
        return
      }

      const reg = (regs || []).find((r) => String(studentKey(r)) === String(data.studentId))
      const label = reg?.student?.full_name || 'Student'
      const alreadyPresent = (attendance || []).some(
        (a) => a.attended && String(a.student_id) === String(data.studentId),
      )
      if (alreadyPresent) {
        const msg = `${label} already checked in`
        setLastScanMsg(msg)
        setLastScanKind('ok')
        setStatusMsg(msg)
        setStatusKind('ok')
        setToast?.(msg)
        if (clearInput) setQrText('')
        return
      }

      qrBusyRef.current = true
      setBusy(true)
      try {
        const { data: row, error: err } = await markAttendance({
          eventId: data.eventId,
          studentId: data.studentId,
          attended: true,
          method: ATTENDANCE_METHOD.QR,
          markedBy: user?.id,
        })
        if (err) {
          setLastScanMsg(err.message || 'QR mark failed')
          setLastScanKind('err')
          setStatusMsg(err.message || 'QR mark failed')
          setStatusKind('err')
          setToast?.(err.message || 'QR mark failed')
          return
        }
        setAttendance((prev) => {
          const others = (prev || []).filter((a) => a.student_id !== data.studentId)
          return [row || { event_id: data.eventId, student_id: data.studentId, attended: true, method: 'qr' }, ...others]
        })
        if (clearInput) setQrText('')
        const okMsg = `Present: ${label}`
        setLastScanMsg(okMsg)
        setLastScanKind('ok')
        setStatusMsg(`${okMsg} — attendance recorded`)
        setStatusKind('ok')
        setToast?.(`${okMsg} — attendance recorded`)
        if (reg?.id && Number(reg.depositAmount || 0) > 0 && reg.paymentStatus === 'paid') {
          const { error: refundErr } = await processRegistrationPayment({
            registrationId: reg.id,
            eventId: data.eventId,
            kind: 'deposit',
            studentId: data.studentId,
          })
          if (refundErr) {
            setToast?.(`Present saved — deposit refund: ${refundErr.message}`)
            setStatusMsg(`Present saved — deposit refund: ${refundErr.message}`)
            setStatusKind('err')
          } else {
            setToast?.('Present + security deposit refunded')
            setStatusMsg('Present + security deposit refunded')
            setStatusKind('ok')
          }
        }
        await refresh()
      } finally {
        qrBusyRef.current = false
        setBusy(false)
      }
    },
    [attendance, attendanceUnlocked, eventId, regs, refresh, selectedEvent?.date, setToast, user?.id],
  )

  async function scanQr() {
    await markFromQrText(qrText, { clearInput: true })
  }

  async function setRegStatus(id, status) {
    const { error } = await updateRegistrationStatus(id, status)
    if (error) flash(error.message, 'err')
    else {
      flash(`Registration ${status}`, 'ok')
      refresh()
    }
  }

  async function onUpload(e) {
    const file = e.target.files?.[0]
    if (!file || !eventId) return
    setBusy(true)
    const { data: up, error: upErr } = await uploadEventMedia(file, { folder: `events/${eventId}` })
    if (upErr) {
      setBusy(false)
      flash(upErr.message, 'err')
      return
    }
    const isVideo = String(file.type || '').startsWith('video')
    const { error } = await addMedia({
      eventId,
      fileUrl: up.publicUrl,
      fileType: isVideo ? 'video' : 'image',
      caption,
      uploadedBy: user?.id,
    })
    setBusy(false)
    if (error) flash(error.message, 'err')
    else {
      flash('Media uploaded to gallery', 'ok')
      setCaption('')
      setMediaTick((n) => n + 1)
      e.target.value = ''
    }
  }

  const attendedIds = new Set(
    (attendance || [])
      .filter((a) => a.attended)
      .map((a) => String(a.student_id)),
  )

  const methodByStudent = useMemo(() => {
    const m = new Map()
    for (const a of attendance || []) {
      if (a?.student_id) m.set(String(a.student_id), a.method)
    }
    return m
  }, [attendance])

  const confirmed = (regs || []).filter(
    (r) => r.status === REGISTRATION_STATUS.CONFIRMED || r.status === 'confirmed',
  )
  const confirmedStudents = confirmed.filter((r) => !rowIsPublicGuest(r))
  const confirmedPublic = confirmed.filter((r) => rowIsPublicGuest(r))
  const regsStudents = (regs || []).filter((r) => !rowIsPublicGuest(r))
  const regsPublic = (regs || []).filter((r) => rowIsPublicGuest(r))

  const certIds = new Set((certs || []).map((c) => String(c.student_id)))
  const presentForCerts = confirmedStudents.filter((r) => attendedIds.has(String(studentKey(r))))
  const pendingCertCount = presentForCerts.filter((r) => !certIds.has(String(studentKey(r)))).length

  async function issueOne(studentId, label) {
    if (!certsUnlocked) {
      flash('Certificates unlock after the event end time', 'err')
      return
    }
    if (!attendedIds.has(String(studentId))) {
      flash('Mark attendance Present before issuing a certificate', 'err')
      return
    }
    const row = confirmed.find((r) => String(studentKey(r)) === String(studentId))
    if (rowIsPublicGuest(row)) {
      flash('Certificates are for campus students only — not public guests', 'err')
      return
    }
    setBusy(true)
    const { error } = await issueCertificate({
      eventId,
      studentId,
      certificateUrl: certUrl || null,
    })
    setBusy(false)
    if (error) flash(error.message, 'err')
    else {
      flash(`Certificate issued${label ? `: ${label}` : ''}`, 'ok')
      refresh()
    }
  }

  async function issueAllPresent() {
    if (!certsUnlocked) {
      flash('Certificates unlock after the event end time', 'err')
      return
    }
    const pending = presentForCerts.filter((r) => !certIds.has(String(studentKey(r))))
    if (!pending.length) {
      flash('All present students already have certificates (guests never receive certificates)', 'ok')
      return
    }
    setBusy(true)
    let ok = 0
    for (const r of pending) {
      const sid = studentKey(r)
      const { error } = await issueCertificate({
        eventId,
        studentId: sid,
        certificateUrl: certUrl || null,
      })
      if (!error) ok += 1
    }
    setBusy(false)
    flash(`Issued ${ok}/${pending.length} certificates`, ok ? 'ok' : 'err')
    refresh()
  }

  const phaseLabel =
    phase === 'live'
      ? 'Live now'
      : phase === 'starting_soon'
        ? 'Starting soon'
        : phase === 'ended'
          ? 'Ended — certificates open'
          : phase === 'upcoming'
            ? 'Upcoming'
            : ''

  return (
    <>
      <div className="page-head">
        <div>
          <div className="eyebrow">Event operations</div>
          <h1>Attendance & certificates</h1>
          <p>Mark attendance on event day. After end time, issue certificates to Present students.</p>
          <button
            type="button"
            className="btn btn-primary"
            disabled={!eventId}
            onClick={() => setStationPosterOpen(true)}
            data-testid="button-open-station-poster"
          >
            <QrCode size={14} /> Station QR poster (PDF)
          </button>
        </div>
      </div>

      {statusMsg && (
        <div
          className="surface"
          style={{
            padding: '12px 16px',
            marginBottom: 14,
            borderColor: statusKind === 'err' ? 'var(--danger)' : 'var(--lime)',
            display: 'flex',
            alignItems: 'center',
            gap: 10,
          }}
          data-testid="attendance-status"
        >
          {statusKind === 'err' ? (
            <span className="muted" style={{ color: 'var(--danger)' }}>{statusMsg}</span>
