import { useEffect, useState } from 'react'
import { Download, Printer } from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import { downloadCertificate, printCertificate } from '@/lib/certificateGenerate'
import { listCertificatesForStudent } from '@/services/certificates'
import { isPublicGuestRole } from '@/constants/roles'

export default function StudentCertificates({ setToast }) {
  const { user, profile } = useAuth()
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(true)
  const [busyId, setBusyId] = useState('')

  async function load() {
    if (!user?.id) return
    if (isPublicGuestRole(profile?.role)) {
      setRows([])
      setLoading(false)
      return
    }
    setLoading(true)
    const { data, error } = await listCertificatesForStudent(user.id)
    if (error) setToast?.(error.message)
    setRows(data || [])
    setLoading(false)
  }

  useEffect(() => {
    load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id, profile?.role])

  function certPayload(c) {
    return {
      studentName: profile?.full_name || user?.email || 'Participant',
      eventTitle: c.events?.title || 'Campus Event',
      eventDate: c.events?.event_date || null,
      issuedOn: c.issued_on,
      organizerLabel: 'EventSphere',
    }
  }

  async function onDownload(c) {
    const url = String(c.certificate_url || '')
    if (/^https?:\/\//i.test(url)) {
      window.open(url, '_blank', 'noopener,noreferrer')
      return
    }
    setBusyId(c.id)
    try {
      await downloadCertificate(certPayload(c))
      setToast?.('Certificate PNG downloaded')
    } catch (err) {
      setToast?.(err?.message || 'Could not generate certificate')
    }
    setBusyId('')
  }

  function onPrint(c) {
    const { error } = printCertificate(certPayload(c))
    if (error) setToast?.(error.message)
  }

  if (isPublicGuestRole(profile?.role)) {
    return (
      <div className="surface" style={{ padding: 24 }}>
        <p className="muted" style={{ margin: 0 }}>
          Certificates are for campus students only. Public guests keep QR passes in the Guest Hub.
        </p>
      </div>
    )
  }

  return (
    <>
      <div className="page-head">
        <div>
          <div className="eyebrow">Your credentials</div>
          <h1>Certificates</h1>
          <p>Issued after the organizer marks you Present — download PNG or print / Save as PDF.</p>
        </div>
      </div>

      {loading && <p className="muted">Loading…</p>}

      {!loading && !rows.length && (
        <div className="surface" style={{ padding: 24 }}>
          <p className="muted" style={{ margin: 0 }}>
            No certificates yet. Attend the event, wait until it ends, then the organizer issues them.
          </p>
        </div>
      )}

      {!loading && rows.length > 0 && (
        <div className="grid-2 stagger">
          {rows.map((c) => {
            const issued = Boolean(c.issued_on)
            const title = c.events?.title || 'Campus event'
            const date = c.events?.event_date ? String(c.events.event_date).slice(0, 10) : 'Date TBA'
            const name = profile?.full_name || user?.email || 'Student'
            return (
              <div className="surface pass" key={c.id} data-testid={`cert-card-${c.id}`}>
                <div className="pass-top">
                  <div className="eyebrow">
                    EventSphere · {issued ? 'Issued' : 'Pending'}
                  </div>
                  <h2 className="display" style={{ fontSize: 25, margin: '16px 0 6px' }}>
                    {title}
                  </h2>
                  <div className="muted" style={{ fontSize: 11 }}>
                    {date}
                    {issued
                      ? ` · Issued ${new Date(c.issued_on).toLocaleDateString()}`
                      : ' · Awaiting organizer'}
                  </div>
                </div>
                <div className="pass-bottom">
                  <div>
                    <div className="subtle" style={{ fontSize: 9, letterSpacing: '.12em' }}>
                      STUDENT
                    </div>
                    <strong style={{ display: 'block', marginTop: 5 }}>{name}</strong>
                    <div className="subtle mono" style={{ marginTop: 16, fontSize: 10 }}>
                      CERT · ES-{String(c.event_id || c.id).slice(0, 4).toUpperCase()}
                    </div>
                  </div>
                  <div
                    className="muted"
                    style={{
                      width: 96,
                      height: 96,
                      borderRadius: 12,
                      display: 'grid',
                      placeItems: 'center',
                      border: '1px solid var(--line)',
                      fontSize: 11,
                      textAlign: 'center',
                      padding: 8,
                      lineHeight: 1.35,
                    }}
                  >
                    {issued ? 'Ready to download' : 'Not issued yet'}
                  </div>
                </div>
                <div style={{ padding: '0 24px 20px', display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                  {issued ? (
                    <>
                      <button
                        className="btn btn-primary"
                        type="button"
                        disabled={busyId === c.id}
                        onClick={() => onDownload(c)}
                        data-testid={`button-download-cert-${c.id}`}
                      >
                        <Download size={14} />{' '}
                        {busyId === c.id ? 'Generating…' : 'Download PNG'}
                      </button>
                      <button className="btn" type="button" onClick={() => onPrint(c)}>
                        <Printer size={14} /> Print / PDF
                      </button>
                    </>
                  ) : (
                    <button className="btn" type="button" disabled>
                      Awaiting issue
                    </button>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      )}
    </>
  )
}

import { Download, Share2 } from 'lucide-react'
import { bannerForEvent, characterForEvent } from '@/constants/campusCharacters'
import { logEventShare } from '@/services/share'
import { useAuth } from '@/context/AuthContext'

async function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image()
    img.crossOrigin = 'anonymous'
    img.onload = () => resolve(img)
    img.onerror = reject
    img.src = src
  })
}

export async function renderEventStoryCard(event) {
  const canvas = document.createElement('canvas')
  canvas.width = 1080
  canvas.height = 1920
  const ctx = canvas.getContext('2d')

  const grad = ctx.createLinearGradient(0, 0, 1080, 1920)
  grad.addColorStop(0, '#0b0a14')
  grad.addColorStop(0.5, '#12101c')
  grad.addColorStop(1, '#081018')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, 1080, 1920)

  const banner = bannerForEvent(event)
  if (banner) {
    try {
      const img = await loadImage(banner)
      ctx.globalAlpha = 0.45
      ctx.drawImage(img, 0, 0, 1080, 720)
      ctx.globalAlpha = 1
    } catch {
      /* ignore CORS failures */
    }
  }

  ctx.fillStyle = 'rgba(7,6,12,0.55)'
  ctx.fillRect(0, 560, 1080, 200)

  ctx.fillStyle = '#5ce1ff'
  ctx.font = '600 36px Inter, system-ui, sans-serif'
  ctx.fillText('EVENTSPHERE', 72, 640)

  ctx.fillStyle = '#ffffff'
  ctx.font = '800 72px Inter, system-ui, sans-serif'
  const title = String(event?.title || 'Campus event')
  wrapText(ctx, title, 72, 760, 936, 82)

  ctx.fillStyle = '#aab0c8'
  ctx.font = '500 34px Inter, system-ui, sans-serif'
  ctx.fillText([event?.date, event?.time].filter(Boolean).join(' · ') || 'Date TBA', 72, 980)
  ctx.fillText(event?.venue || 'Campus venue', 72, 1040)

  try {
    const mascot = characterForEvent(event)
    const m = await loadImage(mascot.src)
    ctx.drawImage(m, 680, 1180, 320, 320)
  } catch {
    /* ignore */
  }

  ctx.fillStyle = '#ff4fd8'
  ctx.font = '600 28px Inter, system-ui, sans-serif'
  ctx.fillText('Scan the vibe · Join on EventSphere', 72, 1780)

  return canvas
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight) {
  const words = text.split(' ')
  let line = ''
  let yy = y
  for (let n = 0; n < words.length; n++) {
    const test = `${line}${words[n]} `
    if (ctx.measureText(test).width > maxWidth && n > 0) {
      ctx.fillText(line.trim(), x, yy)
      line = `${words[n]} `
      yy += lineHeight
    } else {
      line = test
    }
  }
  ctx.fillText(line.trim(), x, yy)
}

export default function StoryShareButton({ event, setToast }) {
  const { user } = useAuth()
  if (!event) return null

  const download = async () => {
    try {
      const canvas = await renderEventStoryCard(event)
      const url = canvas.toDataURL('image/png')
      const a = document.createElement('a')
      a.href = url
      a.download = `${event.symbol || 'event'}-story.png`
      a.click()
      setToast?.('Story card downloaded (1080×1920)')
      await logEventShare({
        userId: user?.id || null,
        eventId: event.id,
        platform: 'story_png',
        shareMessage: event.title,
      })
    } catch (err) {
      setToast?.(err?.message || 'Could not build story card')
    }
  }

  const shareNative = async () => {
    try {
      const canvas = await renderEventStoryCard(event)
      const blob = await new Promise((res) => canvas.toBlob(res, 'image/png'))
      if (!blob) throw new Error('Could not create image')
      const file = new File([blob], 'eventsphere-story.png', { type: 'image/png' })
      if (navigator.share && navigator.canShare?.({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: event.title,
          text: `Join me at ${event.title} on EventSphere`,
        })
        setToast?.('Shared to your apps')
      } else {
        await download()
      }
    } catch (err) {
      if (err?.name === 'AbortError') return
      setToast?.(err?.message || 'Share cancelled')
    }
  }

  return (
    <div className="es-story-share" style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
      <button type="button" className="btn" onClick={download} data-testid="button-story-download">
        <Download size={14} /> Story card PNG
      </button>
      <button type="button" className="btn btn-primary" onClick={shareNative} data-testid="button-story-share">
        <Share2 size={14} /> Share story
      </button>
    </div>
  )
}

