const SPLASH_KEY = 'es_splash_v1'
const SPLASH_MS = 2800

export function hasSeenSplash() {
  if (typeof window === 'undefined') return true
  try {
    return sessionStorage.getItem(SPLASH_KEY) === '1'
  } catch {
    return false
  }
}

export function markSplashSeen() {
  try {
    sessionStorage.setItem(SPLASH_KEY, '1')
  } catch {
    /* ignore */
  }
}

export function clearSplashSeen() {
  try {
    sessionStorage.removeItem(SPLASH_KEY)
  } catch {
    /* ignore */
  }
}

/**
 * One-shot branded splash for guest entry (once per browser tab session).
 * Portaled to document.body so it always covers the viewport above app chrome.
 */
export default function EsSplash({ onDone, force = false }) {
  const reduce = useReducedMotion()
  const onDoneRef = useRef(onDone)
  onDoneRef.current = onDone

  const [visible, setVisible] = useState(() => {
    if (force) return true
    return !hasSeenSplash()
  })
  const [exiting, setExiting] = useState(false)
  const finishedRef = useRef(false)

  const finish = () => {
    if (finishedRef.current) return
    finishedRef.current = true
    markSplashSeen()
    setVisible(false)
    onDoneRef.current?.()
  }

  useEffect(() => {
    if (!visible) {
      if (!finishedRef.current) {
        finishedRef.current = true
        onDoneRef.current?.()
      }
      return undefined
    }

    const duration = reduce ? 500 : SPLASH_MS
    const exitAt = Math.max(120, duration - 380)
    const exitTimer = window.setTimeout(() => setExiting(true), exitAt)
    const doneTimer = window.setTimeout(finish, duration)

    return () => {
      window.clearTimeout(exitTimer)
      window.clearTimeout(doneTimer)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- run once while visible; finish via ref
  }, [visible, reduce])

  useEffect(() => {
    if (!visible) return undefined
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => {
      document.body.style.overflow = prev
    }
  }, [visible])

  if (!visible || typeof document === 'undefined') return null

  return createPortal(
    <div
      className={`es-splash ${exiting ? 'es-splash--out' : ''} ${reduce ? 'es-splash--reduce' : ''}`}
      role="dialog"
      aria-modal="true"
      aria-label="EventSphere welcome"
      data-testid="es-splash"
    >
      <div className="es-splash__veil" aria-hidden />
      <div className="es-splash__orbit" aria-hidden />
      <div className="es-splash__core">
        <EsBrandMark cycle={0} />
        <p className="es-splash__brand">EventSphere</p>
        <p className="es-splash__tag">Campus events, in orbit</p>
      </div>
      <button type="button" className="es-splash__skip" onClick={finish} data-testid="button-skip-splash">
        Skip
      </button>
    </div>,
    document.body,
  )
}

import { CAMPUS_CHARACTERS } from '@/constants/campusCharacters'

function mascotSrc(m) {
  return m?.src || m?.image_url || m?.url || ''
}

function mascotKey(m, i = 0) {
  return m?.id || m?.slug || mascotSrc(m) || `mascot-${i}`
}

function mascotLabel(m) {
  return m?.label || m?.name || m?.slug || 'Campus mascot'
}

/** Resolve library row or fall back to built-in campus character. */
export function resolvePublicMascot(id, library = []) {
  const fromLib = library.find((m) => m.id === id || m.slug === id)
  if (fromLib && mascotSrc(fromLib)) return fromLib
  return CAMPUS_CHARACTERS[id] || CAMPUS_CHARACTERS.hero
}

/**
 * Hero mascot cluster — one lead + orbiting accents (public landing).
 */
export function PublicMascotHero({ library = [] }) {
  const pool = library.length
    ? library.filter((m) => mascotSrc(m))
    : [CAMPUS_CHARACTERS.banner, CAMPUS_CHARACTERS.hero, CAMPUS_CHARACTERS.robot, CAMPUS_CHARACTERS.plane]

  const lead =
    pool.find((m) => m.slug === 'banner' || m.id === 'banner') ||
    pool.find((m) => m.slug === 'hero' || m.id === 'hero') ||
    pool[0]

  const orbit = pool.filter((m) => m !== lead).slice(0, 3)

  if (!lead || !mascotSrc(lead)) return null

  return (
    <div className="es-public-mascot-scene" aria-hidden="true" data-testid="public-mascot-hero">
      <img
        className="es-public-mascot-scene__lead"
        src={mascotSrc(lead)}
        alt=""
        draggable={false}
      />
      {orbit.map((m, i) => (
        <img
          key={mascotKey(m, i)}
          className={`es-public-mascot-scene__orbit es-public-mascot-scene__orbit--${i + 1}`}
          src={mascotSrc(m)}
          alt=""
          draggable={false}
        />
      ))}
    </div>
  )
}

/** Compact mascot for path cards / empty states. */
export function PublicMascotBadge({ mascot, size = 'md', className = '' }) {
  const src = mascotSrc(mascot)
  if (!src) return null
  return (
    <img
      className={`es-public-mascot-badge es-public-mascot-badge--${size} ${className}`.trim()}
      src={src}
      alt={mascotLabel(mascot)}
      draggable={false}
    />
  )
}

/** Empty-state mascot with label. */
export function PublicMascotEmpty({ library = [], message }) {
  const mascot = resolvePublicMascot('hero', library)
  return (
    <div className="es-public-mascot-empty surface">
      <PublicMascotBadge mascot={mascot} size="lg" />
      <p className="muted" style={{ margin: '12px 0 0', fontSize: 13 }}>
        {message}
      </p>
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { MessageCircle, Send } from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import { askOrganizer, listQuestionsForEvent } from '@/services/questions'
import { isSupabaseConfigured, supabase } from '@/lib/supabase'

export default function AskOrganizerButton({ eventId, eventTitle, setToast, compact = false }) {
  const { user } = useAuth()
  const [open, setOpen] = useState(false)
  const [question, setQuestion] = useState('')
  const [busy, setBusy] = useState(false)
  const [thread, setThread] = useState([])
  const [loadingThread, setLoadingThread] = useState(false)

  const loadThread = useCallback(async () => {
    if (!user?.id || !eventId) return
    setLoadingThread(true)
    const { data, error } = await listQuestionsForEvent(eventId, { studentId: user.id })
    setLoadingThread(false)
    if (error) {
      setToast?.(error.message)
      return
    }
    setThread(data || [])
  }, [eventId, user?.id, setToast])

  useEffect(() => {
    if (!open) return undefined
    loadThread()
    if (!isSupabaseConfigured) return undefined
    const channel = supabase
      .channel(`ask-org-${eventId}-${user?.id || 'x'}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'event_questions',
          filter: `event_id=eq.${eventId}`,
        },
        () => loadThread(),
      )
      .subscribe()
    return () => {
      supabase.removeChannel(channel)
    }
  }, [open, eventId, user?.id, loadThread])

  if (!user?.id || !eventId) return null

  const submit = async (e) => {
    e?.preventDefault?.()
    if (!question.trim()) return
    setBusy(true)
    const { data, error } = await askOrganizer({
      eventId,
      studentId: user.id,
      question,
    })
    setBusy(false)
    if (error) {
      setToast?.(error.message || 'Could not send question')
      return
    }
    setToast?.(`Question sent to organizer${eventTitle ? ` · ${eventTitle}` : ''}`)
    setQuestion('')
    if (data) {
      setThread((prev) => [...prev, data])
    } else {
      await loadThread()
    }
  }

  return (
    <div className="es-ask-organizer" data-testid={`ask-organizer-${eventId}`}>
      <button
        type="button"
        className={compact ? 'btn btn-quiet' : 'btn'}
        onClick={() => setOpen((v) => !v)}
        data-testid="button-ask-organizer"
      >
        <MessageCircle size={14} /> Ask Organizer
        {thread.length ? ` (${thread.length})` : ''}
      </button>
      {open ? (
        <div className="es-ask-organizer__panel surface" style={{ marginTop: 10, padding: 14 }}>
          <div className="eyebrow" style={{ marginBottom: 8 }}>Your chat with organizer</div>
          {loadingThread && !thread.length ? (
            <p className="muted" style={{ fontSize: 12 }}>Loading messages…</p>
          ) : null}
          {!loadingThread && !thread.length ? (
            <p className="muted" style={{ fontSize: 12, marginBottom: 10 }}>
              No messages yet. Ask about schedule, venue, or entry.
            </p>
          ) : null}
          {thread.length ? (
            <ul
              style={{
                listStyle: 'none',
                padding: 0,
                margin: '0 0 12px',
                maxHeight: 220,
                overflow: 'auto',
                display: 'grid',
                gap: 8,
              }}
            >
              {thread.map((row) => (
                <li key={row.id} className="surface-soft" style={{ padding: 10 }}>
                  <p style={{ fontSize: 12, margin: 0 }}>{row.question}</p>
                  <p className="muted" style={{ fontSize: 10, margin: '4px 0 0' }}>
                    You · {row.created_at ? new Date(row.created_at).toLocaleString() : ''}
                  </p>
                  {row.answer ? (
                    <div style={{ marginTop: 8, paddingTop: 8, borderTop: '1px solid var(--line, rgba(255,255,255,.08))' }}>
                      <div className="eyebrow">Organizer reply</div>
                      <p style={{ fontSize: 12, margin: '4px 0 0' }}>{row.answer}</p>
                    </div>
                  ) : (
                    <p className="muted" style={{ fontSize: 11, margin: '6px 0 0' }}>Waiting for reply…</p>
                  )}
                </li>
              ))}
            </ul>
          ) : null}
          <form onSubmit={submit}>
            <label className="label">Your question</label>
            <textarea
              className="input"
              rows={3}
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              placeholder="Ask about schedule, venue, gear, VIP access…"
              data-testid="input-ask-organizer"
              required
            />
            <button type="submit" className="btn btn-primary" disabled={busy} style={{ marginTop: 10 }}>
              <Send size={14} /> {busy ? 'Sending…' : 'Send to organizer'}
            </button>
          </form>
        </div>
      ) : null}
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Crown, Sparkles, Star } from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import { listCampusFavs, listVipInvitesForEvent, sendVipInvite } from '@/services/experience'

export default function CampusFavPanel({ eventId, eventTitle, canManage = false, setToast }) {
  const { user } = useAuth()
  const [favs, setFavs] = useState([])
  const [invited, setInvited] = useState(new Set())
  const [loading, setLoading] = useState(true)
  const [busyId, setBusyId] = useState(null)

  const load = useCallback(async () => {
    if (!canManage) {
      setLoading(false)
      return
    }
    setLoading(true)
    const [favRes, vipRes] = await Promise.all([
      listCampusFavs(15),
      eventId ? listVipInvitesForEvent(eventId) : Promise.resolve({ data: [] }),
    ])
    if (favRes.error) setToast?.(favRes.error.message)
    setFavs(favRes.data || [])
    setInvited(new Set((vipRes.data || []).map((r) => r.student_id)))
    setLoading(false)
  }, [canManage, eventId, setToast])

  useEffect(() => {
    load()
  }, [load])

  if (!canManage || !eventId) return null

  const invite = async (row) => {
    setBusyId(row.user_id)
    const { error } = await sendVipInvite({
      eventId,
      studentId: row.user_id,
      invitedBy: user?.id,
      note: `VIP for ${eventTitle || 'this event'}`,
    })
    setBusyId(null)
    if (error) {
      setToast?.(error.message)
      return
    }
    setToast?.(`VIP invite sent to ${row.full_name || 'student'}`)
    setInvited((prev) => new Set([...prev, row.user_id]))
  }

  return (
    <div className="surface" style={{ padding: 18, marginTop: 16 }} data-testid="campus-fav-panel">
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <Crown size={18} style={{ color: 'var(--es-sun, #ffca7f)' }} />
        <div>
          <div className="eyebrow">Campus Fav → VIP</div>
          <h3 className="display" style={{ margin: 0, fontSize: 18 }}>Invite standout students</h3>
        </div>
      </div>
      <p className="muted" style={{ fontSize: 12, marginTop: 8 }}>
        Ranked by real activity: attendance, feedback, and earned badges — not self-scored quizzes.
      </p>

      {loading ? (
        <p className="muted" style={{ marginTop: 12 }}>Loading Campus Favs…</p>
      ) : !favs.length ? (
        <p className="muted" style={{ marginTop: 12, fontSize: 12 }}>
          No Campus Fav scores yet. Mark attendance and collect feedback — badges unlock automatically.
          Run <code>eventsphere-achievements-roi.sql</code> if this stays empty.
        </p>
      ) : (
        <ol className="es-leaderboard" style={{ marginTop: 14 }}>
          {favs.map((row, i) => {
            const isVip = invited.has(row.user_id)
            return (
              <li key={row.user_id} style={{ alignItems: 'flex-start' }}>
                <span className="es-leaderboard__rank">#{i + 1}</span>
                <div style={{ minWidth: 0, flex: 1 }}>
                  <strong>{row.full_name || 'Student'}</strong>
                  <div className="muted" style={{ fontSize: 11 }}>{row.email || '—'}</div>
                  <div className="muted" style={{ fontSize: 10, marginTop: 2 }}>
                    {row.attend_count || 0} attended · {row.feedback_count || 0} feedback ·{' '}
                    {row.badge_count || 0} badges
                  </div>
                </div>
                <span className="es-leaderboard__score" style={{ marginRight: 8 }}>
                  <Star size={12} style={{ verticalAlign: 'middle' }} /> {row.fav_score || 0}
                </span>
                <button
                  type="button"
                  className={`btn ${isVip ? 'btn-quiet' : 'btn-primary'}`}
                  style={{ fontSize: 11, padding: '6px 10px' }}
                  disabled={isVip || busyId === row.user_id}
                  onClick={() => invite(row)}
                >
                  <Sparkles size={12} /> {isVip ? 'VIP invited' : busyId === row.user_id ? '…' : 'VIP invite'}
                </button>
              </li>
            )
          })}
        </ol>
      )}
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { useLocation } from 'wouter'
import { Archive, ChevronDown, ChevronUp, ListFilter, Plus, Search, SlidersHorizontal } from 'lucide-react'
import { EVENT_CATEGORIES, EVENT_STATUS } from '@/constants/domain'
import { EsEventCard, EsPageChrome } from '@/components/design-system'
import OrganizerEventManage from '@/components/ops/OrganizerEventManage'
import FeaturedEventsStrip from '@/components/shared/FeaturedEventsStrip'
import PromoCampaignBanner from '@/components/shared/PromoCampaignBanner'
import SponsorStrip from '@/components/shared/SponsorStrip'
import { featuredEvents, isEventFeatured, sortFeaturedFirst } from '@/lib/featuredEvents'
import { getEventPhase, isEventEnded } from '@/lib/eventDate'
import { eventRequiresPayment, isPublicGuestEvent, isRegistrationClosed } from '@/lib/eventMappers'
import { listCategories } from '@/services/categories'
