import { useEffect, useMemo, useState } from 'react'
import { Plus } from 'lucide-react'
import { formatEventSchedule, getEventPhase, todayLocalDate } from '@/lib/eventDate'

const WEEKDAYS = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT']
const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
]

function parseYmd(raw) {
  const s = String(raw || '').slice(0, 10)
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s)
  if (!m) return null
  return { y: Number(m[1]), mo: Number(m[2]), d: Number(m[3]), ymd: s }
}

function buildMonthGrid(year, monthIndex) {
  // monthIndex: 0-11
  const first = new Date(year, monthIndex, 1)
  const startPad = first.getDay() // 0 = Sunday
  const daysInMonth = new Date(year, monthIndex + 1, 0).getDate()
  const cells = []

  for (let i = 0; i < startPad; i += 1) {
    cells.push({ key: `pad-b-${i}`, day: null, inMonth: false })
  }
  for (let d = 1; d <= daysInMonth; d += 1) {
    const ymd = `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`
    cells.push({ key: ymd, day: d, inMonth: true, ymd })
  }
  while (cells.length % 7 !== 0) {
    cells.push({ key: `pad-a-${cells.length}`, day: null, inMonth: false })
  }
  // Prefer 6 rows (42) for stable height when needed
  while (cells.length < 35) {
    cells.push({ key: `pad-x-${cells.length}`, day: null, inMonth: false })
  }
  return cells
}

function initialCursor() {
  const today = todayLocalDate()
  const p = parseYmd(today)
  if (p && p.y === 2026) return { year: 2026, month: p.mo - 1 }
  if (p && p.y > 2026) return { year: 2026, month: 11 }
  return { year: 2026, month: 0 }
}

function phaseClass(phase) {
  if (phase === 'ended') return 'cal-ended'
  if (phase === 'live') return 'cal-live'
  if (phase === 'starting_soon') return 'cal-soon'
  return ''
}

function phaseLabel(phase) {
  if (phase === 'ended') return 'Ended'
  if (phase === 'live') return 'Live'
  if (phase === 'starting_soon') return 'Soon'
  return null
}

/**
 * Student calendar — full 2026 month grid with registered events.
 * Reflects Live / Soon / Ended from event start–end times.
 */
export default function StudentCalendar({ events = [], registrations = [], go }) {
  const [cursor, setCursor] = useState(initialCursor)
  const [clock, setClock] = useState(0)
  const today = todayLocalDate()

  // Re-evaluate ended/live phases while the calendar is open
  useEffect(() => {
    const id = setInterval(() => setClock((n) => n + 1), 30000)
    return () => clearInterval(id)
  }, [])

  const phaseNow = useMemo(() => new Date(), [clock])

  const registeredEvents = useMemo(() => {
    const ids = new Set((registrations || []).map(String))
    return (events || []).filter((e) => ids.has(String(e.id)) && e.date)
  }, [events, registrations])

  const byDate = useMemo(() => {
    const map = new Map()
    registeredEvents.forEach((e) => {
      const key = String(e.date).slice(0, 10)
      if (!map.has(key)) map.set(key, [])
      map.get(key).push(e)
    })
    return map
  }, [registeredEvents])

  const cells = useMemo(
    () => buildMonthGrid(cursor.year, cursor.month),
    [cursor.year, cursor.month],
  )

  const monthLabel = `${MONTHS[cursor.month]} ${cursor.year}`

  function prevMonth() {
    setCursor((c) => {
      if (c.month === 0) {
        if (c.year <= 2026) return { year: 2026, month: 0 }
        return { year: c.year - 1, month: 11 }
      }
      return { year: c.year, month: c.month - 1 }
    })
  }

  function nextMonth() {
    setCursor((c) => {
      if (c.month === 11) {
        if (c.year >= 2026) return { year: 2026, month: 11 }
        return { year: c.year + 1, month: 0 }
      }
      return { year: c.year, month: c.month + 1 }
    })
  }

  function goToday() {
    setCursor(initialCursor())
  }

  const monthEvents = registeredEvents
    .filter((e) => {
      const p = parseYmd(e.date)
      return p && p.y === cursor.year && p.mo === cursor.month + 1
    })
    .slice()
    .sort((a, b) => {
      const dateCmp = String(a.date).localeCompare(String(b.date))
      if (dateCmp !== 0) return dateCmp
      const order = { live: 0, starting_soon: 1, upcoming: 2, unknown: 3, ended: 4 }
      return (order[getEventPhase(a, phaseNow)] ?? 3) - (order[getEventPhase(b, phaseNow)] ?? 3)
    })

  const endedCount = monthEvents.filter((e) => getEventPhase(e, phaseNow) === 'ended').length
  const activeCount = monthEvents.length - endedCount

  const canPrev = !(cursor.year === 2026 && cursor.month === 0)
  const canNext = !(cursor.year === 2026 && cursor.month === 11)
  return (
    <>
      <div className="page-head">
        <div>
          <div className="eyebrow">Your year in view</div>
          <h1>Calendar</h1>
          <p>2026 campus calendar — registered events update to Live, Soon, or Ended by schedule.</p>
        </div>
        <button className="btn" type="button" onClick={() => go('/student/discover')}>
          <Plus size={14} /> Find an event
        </button>
      </div>

      <div className="surface" style={{ padding: 17 }}>
        <div className="section-title">
          <h2>{monthLabel}</h2>
          <div className="toolbar">
            <button className="btn" type="button" onClick={goToday} data-testid="button-cal-today">
              Today
            </button>
            <button
              className="btn"
              type="button"
              onClick={prevMonth}
              disabled={!canPrev}
              aria-label="Previous month"
              data-testid="button-cal-prev"
            >
              ‹
            </button>
            <button
              className="btn"
              type="button"
              onClick={nextMonth}
              disabled={!canNext}
              aria-label="Next month"
              data-testid="button-cal-next"
            >
              ›
            </button>
          </div>
        </div>

        <div className="calendar" data-testid="student-calendar-2026">
          {WEEKDAYS.map((d) => (
            <div className="cal-head" key={d}>{d}</div>
          ))}
          {cells.map((cell) => {
            const dayEvents = cell.ymd ? byDate.get(cell.ymd) || [] : []
            const isToday = cell.ymd === today
            return (
              <div
                className={`cal-day ${!cell.inMonth ? 'subtle' : ''} ${isToday ? 'cal-today' : ''}`}
                key={cell.key}
              >
                {cell.day != null && <strong>{cell.day}</strong>}
                {dayEvents.slice(0, 2).map((ev) => {
                  const phase = getEventPhase(ev, phaseNow)
                  const tag = phaseLabel(phase)
                  return (
                    <button
                      key={ev.id}
                      type="button"
                      className={`cal-event ${phaseClass(phase)}`}
                      onClick={() => go(`/student/event/${ev.id}`)}
                      data-testid={`button-calendar-event-${ev.id}`}
                      title={`${ev.title} · ${formatEventSchedule(ev)}${tag ? ` · ${tag}` : ''}`}
                    >
                      {tag ? `${tag} · ` : ''}{ev.title}
                    </button>
                  )
                })}
                {dayEvents.length > 2 && (
                  <span className="subtle" style={{ fontSize: 9 }}>
                    +{dayEvents.length - 2} more
                  </span>
                )}
              </div>
            )
          })}
        </div>
      </div>

      <div className="section surface" style={{ padding: 18, marginTop: 16 }}>
        <div className="section-title">
          <h2>This month</h2>
          <span className="muted" style={{ fontSize: 12 }}>
            {activeCount} active{endedCount ? ` · ${endedCount} ended` : ''} · {monthEvents.length} registered
          </span>
        </div>
        {!monthEvents.length ? (
          <p className="muted" style={{ margin: 0, fontSize: 13 }}>
            No registered events in {monthLabel}. Discover an approved event and register to see it here.
          </p>
        ) : (
          <div style={{ display: 'grid', gap: 10 }}>
            {monthEvents.map((ev) => {
              const phase = getEventPhase(ev, phaseNow)
              const tag = phaseLabel(phase)
              return (
                <button
                  key={ev.id}
                  type="button"
                  className="btn"
                  style={{
                    justifyContent: 'space-between',
                    width: '100%',
                    opacity: phase === 'ended' ? 0.72 : 1,
                  }}
                  onClick={() => go(`/student/event/${ev.id}`)}
                  data-testid={`button-calendar-month-${ev.id}`}
                >
                  <span style={{ textAlign: 'left' }}>
                    <strong>{ev.title}</strong>
                    <span className="muted" style={{ marginLeft: 8, fontSize: 12 }}>
                      {formatEventSchedule(ev)} · {ev.venue || 'TBA'}
                    </span>
                  </span>
                  <span
                    className={`badge ${phase === 'ended' ? 'badge-draft' : ''}`}
                    style={
                      phase === 'live'
                        ? { background: 'rgba(182,239,159,.18)', color: 'var(--lime)' }
                        : phase === 'starting_soon'
                          ? { background: 'rgba(84,216,232,.18)', color: 'var(--cyan)' }
                          : phase === 'ended'
                            ? undefined
                            : { background: 'rgba(154,123,255,.14)', color: 'var(--violet)' }
                    }
                  >
                    {tag || 'Upcoming'}
                  </span>
                </button>
              )
            })}
          </div>
        )}
      </div>
    </>
  )
}

import { createContext, useContext, useEffect, useState } from 'react'
import { ROLES, normalizeRole } from '../constants/roles'
import { supabase, isSupabaseConfigured } from '../lib/supabase'

const AuthContext = createContext(null)

export function AuthProvider({ children }) {
  const [session, setSession] = useState(null)
  const [profile, setProfile] = useState(null)
  const [loading, setLoading] = useState(true)

  async function fetchProfile() {
    // Prefer RPC (security definer) so RLS cannot block role read
    const { data: ensured, error: ensureError } = await supabase.rpc(
      'ensure_my_profile',
    )

    if (!ensureError && ensured) {
      return ensured
    }

    if (ensureError) {
      console.warn('ensure_my_profile RPC:', ensureError.message)
    }

    const { data: mine, error: getError } = await supabase.rpc('get_my_profile')
    if (!getError && mine) {
      return mine
    }

    if (getError) {
      console.warn('get_my_profile RPC:', getError.message)
    }

    // Fallback: direct table read
    const {
      data: { user },
    } = await supabase.auth.getUser()
    if (!user) return null

    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', user.id)
      .maybeSingle()

    if (error) {
      console.error('Failed to load profile:', error.message)
      return null
    }
    return data
  }

  useEffect(() => {
    if (!isSupabaseConfigured) {
      setLoading(false)
      return
    }

    let mounted = true

    supabase.auth.getSession().then(async ({ data: { session: current } }) => {
      if (!mounted) return
      setSession(current)
      if (current?.user) {
        const p = await fetchProfile()
        if (mounted) setProfile(p)
      }
      if (mounted) setLoading(false)
    })

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, nextSession) => {
      setSession(nextSession)
      setTimeout(async () => {
        if (!mounted) return
        if (nextSession?.user) {
          const p = await fetchProfile()
          if (mounted) setProfile(p)
        } else {
          setProfile(null)
        }
        setLoading(false)
      }, 0)
    })

    return () => {
      mounted = false
      subscription.unsubscribe()
    }
  }, [])

  async function signUp({
    email,
    password,
    fullName,
    mobile,
    department,
    enrollmentNo,
    interests,
    intent,
  }) {
    const isGuestIntent = String(intent || '').toLowerCase() === 'guest'
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          full_name: fullName,
          mobile: mobile || '',
          department: department || '',
          enrollment_no: enrollmentNo || '',
          interests: Array.isArray(interests) ? interests : [],
          role: isGuestIntent ? 'guest' : 'user',
        },
      },
    })
    if (!error && data?.user?.id) {
  // Ensure role sticks even if trigger raced / old SQL not yet applied
      // Only attempt when insert may have defaulted to user — admin trigger blocks non-admin updates,
      // so this succeeds only if RLS allows or row still missing role=guest from trigger.
      if (isGuestIntent) {
        try {
          await supabase.rpc('ensure_my_profile')
          await supabase
            .from('profiles')
            .update({ role: ROLES.GUEST })
            .eq('id', data.user.id)
        } catch {
          /* needs eventsphere-guest-mode.sql (handle_new_user + role claim allowlist) */
        }
      }
    }
    if (!error && data?.user?.id && Array.isArray(interests) && interests.length) {
      try {
        const { data: existing } = await supabase
          .from('profiles')
          .select('preferences')
          .eq('id', data.user.id)
          .maybeSingle()
        await supabase
          .from('profiles')
          .update({
            preferences: {
              ...(existing?.preferences || {}),
              interests,
            },
          })
          .eq('id', data.user.id)
      } catch {
        /* preferences may apply after ensure_my_profile */
      }
    }
    return { data, error }
  }

  async function signIn({ email, password }) {
    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password,
    })
    if (!error && data?.user) {
      setSession(data.session)
      const p = await fetchProfile()
      setProfile(p)
      return { data, error, profile: p }
    }
    return { data, error, profile: null }
  }

  async function signOut() {
    // Local scope: clear this tab's session only (other tabs keep their logins)
    const { error } = await supabase.auth.signOut({ scope: 'local' })
    setSession(null)
    setProfile(null)
    return { error }
  }

  async function refreshProfile() {
    const {
      data: { user },
    } = await supabase.auth.getUser()
    if (!user) return null
    const p = await fetchProfile()
    setProfile(p)
    return p
  }

  const role = normalizeRole(profile?.role)
  const isAdmin = role === ROLES.ADMIN
  const isOrganizer = role === ROLES.ORGANIZER
  const isPublicGuest = role === ROLES.GUEST
  const isGuest = !session?.user

  const value = {
    session,
    user: session?.user ?? null,
    profile,
    role: profile?.role ?? null,
    isAdmin,
    isOrganizer,
    isPublicGuest,
    isGuest,
    loading,
    configured: isSupabaseConfigured,
    signUp,
    signIn,
    signOut,
    refreshProfile,
  }

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export function useAuth() {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used within AuthProvider')
  return ctx
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import {
  fallbackCampusMascots,
  getMascotExperienceSettings,
  listCampusMascots,
} from '@/services/mascots'
import { isSupabaseConfigured } from '@/lib/supabase'

const MascotLibraryContext = createContext(null)

export function MascotLibraryProvider({ children }) {
  const [library, setLibrary] = useState(() => fallbackCampusMascots())
  const [settings, setSettings] = useState({
    student_upload_enabled: true,
    max_upload_mb: 2,
  })
  const [loading, setLoading] = useState(Boolean(isSupabaseConfigured))

  const refresh = useCallback(async ({ includeDisabled = false } = {}) => {
    if (!isSupabaseConfigured) {
      setLibrary(fallbackCampusMascots())
      setLoading(false)
      return { library: fallbackCampusMascots(), settings: { student_upload_enabled: true, max_upload_mb: 2 } }
    }

    setLoading(true)
    const [libRes, setRes] = await Promise.all([
      listCampusMascots({ includeDisabled }),
      getMascotExperienceSettings(),
    ])

    const nextLibrary = libRes.data?.length ? libRes.data : fallbackCampusMascots()
    setLibrary(nextLibrary)

    const nextSettings = setRes.data
      ? {
          student_upload_enabled: setRes.data.student_upload_enabled !== false,
          max_upload_mb: setRes.data.max_upload_mb || 2,
        }
      : { student_upload_enabled: true, max_upload_mb: 2 }

    setSettings(nextSettings)
    setLoading(false)
    return { library: nextLibrary, settings: nextSettings }
  }, [])

  useEffect(() => {
    refresh()
  }, [refresh])

  const enabledLibrary = useMemo(
    () => library.filter((m) => m.enabled !== false),
    [library],
  )

  const value = useMemo(
    () => ({
      library,
      enabledLibrary,
      settings,
      loading,
      refresh,
    }),
    [library, enabledLibrary, settings, loading, refresh],
  )

  return (
    <MascotLibraryContext.Provider value={value}>{children}</MascotLibraryContext.Provider>
  )
}

export function useMascotLibrary() {
  const ctx = useContext(MascotLibraryContext)
  if (!ctx) {
    return {
      library: fallbackCampusMascots(),
      enabledLibrary: fallbackCampusMascots(),
      settings: { student_upload_enabled: true, max_upload_mb: 2 },
      loading: false,
      refresh: async () => ({ library: fallbackCampusMascots() }),
    }
  }
  return ctx
}

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react'
import { useAuth } from '@/context/AuthContext'
import {
  DEFAULT_NEON_TRAIL_CONFIG,
  applyNeonTrailConfig,
  loadNeonTrailConfig,
  normalizeNeonTrailConfig,
  saveNeonTrailConfig,
} from '@/lib/neonTrail'
import { isSupabaseConfigured, supabase } from '@/lib/supabase'
import {
  NEON_TRAIL_SETTINGS_KEY,
  getNeonTrailSettings,
  saveNeonTrailSettings,
} from '@/services/neonTrail'

const NeonTrailContext = createContext(null)
const REMOTE_SAVE_DEBOUNCE_MS = 450

export function NeonTrailProvider({ children }) {
  const { isAdmin } = useAuth()
  const [config, setConfigState] = useState(() => loadNeonTrailConfig())
  const [syncStatus, setSyncStatus] = useState(() =>
    isSupabaseConfigured ? 'loading' : 'local',
  )
  const [syncError, setSyncError] = useState(null)

  const remoteReadyRef = useRef(!isSupabaseConfigured)
  const skipRemoteWriteRef = useRef(false)
  const saveTimerRef = useRef(null)
  const latestConfigRef = useRef(config)
  const isAdminRef = useRef(isAdmin)

  latestConfigRef.current = config
  isAdminRef.current = isAdmin

  const flushRemoteSave = useCallback(async (nextConfig) => {
    if (!isSupabaseConfigured || !remoteReadyRef.current) return { error: null }
    setSyncStatus('saving')
    setSyncError(null)
    const { error } = await saveNeonTrailSettings(nextConfig)
    if (error) {
      setSyncStatus('error')
      setSyncError(error.message || 'Could not save campus theme')
      return { error }
    }
    setSyncStatus('synced')
    setSyncError(null)
    return { error: null }
  }, [])

  const scheduleRemoteSave = useCallback(
    (nextConfig) => {
      if (!isSupabaseConfigured || !remoteReadyRef.current || !isAdminRef.current) return
      if (saveTimerRef.current) window.clearTimeout(saveTimerRef.current)
      saveTimerRef.current = window.setTimeout(() => {
        flushRemoteSave(nextConfig)
      }, REMOTE_SAVE_DEBOUNCE_MS)
    },
    [flushRemoteSave],
  )

  useEffect(() => {
    const next = normalizeNeonTrailConfig(config)
    applyNeonTrailConfig(next)
    saveNeonTrailConfig(next)
    if (!skipRemoteWriteRef.current) {
      scheduleRemoteSave(next)
    }
    skipRemoteWriteRef.current = false
  }, [config, scheduleRemoteSave])

  useEffect(() => {
    if (!isSupabaseConfigured) return undefined

    let cancelled = false

    const hydrate = async () => {
      setSyncStatus('loading')
      const { data, error } = await getNeonTrailSettings()
      if (cancelled) return

      if (error) {
        // Keep local cache; still allow admin writes to attempt later.
        remoteReadyRef.current = true
        setSyncStatus('error')
        setSyncError(error.message || 'Could not load campus theme')
        return
      }

      remoteReadyRef.current = true
      skipRemoteWriteRef.current = true
      setConfigState(normalizeNeonTrailConfig(data))
      setSyncStatus('synced')
      setSyncError(null)
    }

    hydrate()

    const channel = supabase
      .channel('platform-neon-trail')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'platform_settings',
          filter: `key=eq.${NEON_TRAIL_SETTINGS_KEY}`,
        },
        (payload) => {
          const raw = payload.new?.value
          if (!raw) return
          const next = normalizeNeonTrailConfig(raw)
          const current = normalizeNeonTrailConfig(latestConfigRef.current)
          if (JSON.stringify(next) === JSON.stringify(current)) {
            setSyncStatus('synced')
            return
          }
          skipRemoteWriteRef.current = true
          setConfigState(next)
          setSyncStatus('synced')
          setSyncError(null)
        },
      )
      .subscribe()

    return () => {
      cancelled = true
      if (saveTimerRef.current) window.clearTimeout(saveTimerRef.current)
      supabase.removeChannel(channel)
    }
  }, [])

  const setConfig = useCallback((updater) => {
    setConfigState((prev) => {
      const next = typeof updater === 'function' ? updater(prev) : updater
      return normalizeNeonTrailConfig(next)
    })
  }, [])

  const setEnabled = useCallback((enabled) => {
    setConfigState((prev) => ({ ...prev, enabled: Boolean(enabled) }))
  }, [])

  const updatePanel = useCallback((panelKey, patch) => {
    setConfigState((prev) =>
      normalizeNeonTrailConfig({
        ...prev,
        panels: {
          ...prev.panels,
          [panelKey]: { ...prev.panels[panelKey], ...patch },
        },
      }),
    )
  }, [])

  const updatePanelColor = useCallback((panelKey, index, hex) => {
    setConfigState((prev) => {
      const colors = [...prev.panels[panelKey].colors]
      colors[index] = hex
      return normalizeNeonTrailConfig({
        ...prev,
        panels: {
          ...prev.panels,
          [panelKey]: { ...prev.panels[panelKey], colors },
        },
      })
    })
  }, [])

  const resetDefaults = useCallback(() => {
    setConfigState(structuredClone(DEFAULT_NEON_TRAIL_CONFIG))
  }, [])

  const persistNow = useCallback(async () => {
    if (saveTimerRef.current) {
      window.clearTimeout(saveTimerRef.current)
      saveTimerRef.current = null
    }
    return flushRemoteSave(normalizeNeonTrailConfig(latestConfigRef.current))
  }, [flushRemoteSave])

  const value = useMemo(
    () => ({
      config,
      setConfig,
      setEnabled,
      updatePanel,
      updatePanelColor,
      resetDefaults,
      syncStatus,
      syncError,
      persistNow,
    }),
    [
      config,
      setConfig,
      setEnabled,
      updatePanel,
      updatePanelColor,
      resetDefaults,
      syncStatus,
      syncError,
      persistNow,
    ],
  )

  return <NeonTrailContext.Provider value={value}>{children}</NeonTrailContext.Provider>
}

export function useNeonTrail() {
  const ctx = useContext(NeonTrailContext)
  if (!ctx) throw new Error('useNeonTrail must be used within NeonTrailProvider')
  return ctx
}

