import { useEffect, useRef, useState } from 'react'
import {
  BOOT_MIN_MS,
  BOOT_MIN_REDUCE_MS,
  getBootLoaderContext,
  isDocumentReload,
  resolveBootPhase,
} from '@/lib/campusBootGate'

export function useCampusBootGate({ path, authLoading, role, dataLoading }) {
  const bootContext = getBootLoaderContext(path)
  const mountAt = useRef(typeof performance !== 'undefined' ? performance.now() : 0)
  const reloadBoot = useRef(isDocumentReload())

  const sessionPending = Boolean(authLoading)
  const campusDataPending = Boolean(role && dataLoading) && bootContext !== 'auth'

  const [minHold, setMinHold] = useState(() => Boolean(bootContext && reloadBoot.current))

  useEffect(() => {
    if (!bootContext || !reloadBoot.current) {
      setMinHold(false)
      return undefined
    }

    if (sessionPending || campusDataPending) return undefined

    const reduced =
      typeof window !== 'undefined' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches
    const minMs = reduced ? BOOT_MIN_REDUCE_MS : BOOT_MIN_MS
    const elapsed = performance.now() - mountAt.current
    const remaining = Math.max(0, minMs - elapsed)

    if (remaining === 0) {
      setMinHold(false)
      return undefined
    }

    const timer = window.setTimeout(() => setMinHold(false), remaining)
    return () => window.clearTimeout(timer)
  }, [bootContext, sessionPending, campusDataPending, path])

  const booting = Boolean(bootContext) && (sessionPending || campusDataPending || minHold)
  const phase = resolveBootPhase(bootContext, sessionPending, campusDataPending)

  return { booting, phase, bootContext }
}

import { useCallback, useEffect, useState } from 'react'
import { useAuth } from '../context/AuthContext'
import { isSupabaseConfigured } from '../lib/supabase'
import { EVENT_STATUS, REGISTRATION_STATUS, TABLES } from '../constants/domain'
import { useRealtimeTables } from './useRealtimeTables'
import {
  createEvent as apiCreateEvent,
  deleteEvent as apiDeleteEvent,
  listEvents,
  postponeEvent as apiPostponeEvent,
  extendRegistrationDeadline as apiExtendRegistrationDeadline,
  cancelEventWithNotice as apiCancelEventWithNotice,
  setEventStatus as apiSetEventStatus,
  updateEvent as apiUpdateEvent,
} from '../services/events'
import {
  cancelRegistration as apiCancelRegistration,
  listMyRegistrations,
  registerForEvent as apiRegisterForEvent,
} from '../services/registrations'
import {
  listSavedEvents,
  listVenues,
  saveEvent as apiSaveEvent,
  unsaveEvent as apiUnsaveEvent,
} from '../services/venues'

const ACTIVE_REG = new Set([
  REGISTRATION_STATUS.CONFIRMED,
  REGISTRATION_STATUS.WAITLIST,
  REGISTRATION_STATUS.PENDING,
  REGISTRATION_STATUS.PENDING_PAYMENT,
])

/** Core campus tables that drive Shell lists / approvals / seats. */
const LIVE_TABLES = [
  TABLES.EVENTS,
  TABLES.REGISTRATIONS,
  TABLES.VENUES,
  TABLES.SAVED_EVENTS,
  TABLES.EVENT_PAYMENTS,
]

function activeRegistrationIds(rows) {
  return (rows || [])
    .filter((r) => r && ACTIVE_REG.has(r.status))
    .map((r) => r.eventId)
}

export function useEventSphereData() {
  const { user } = useAuth()
  const [events, setEvents] = useState([])
  const [saved, setSaved] = useState([])
  const [registrations, setRegistrations] = useState([])
  const [registrationRows, setRegistrationRows] = useState([])
  const [venues, setVenues] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  const refresh = useCallback(async () => {
    if (!isSupabaseConfigured) {
      setLoading(false)
      setError('Supabase is not configured')
      return { ok: false }
    }

    setError(null)
    const [eventsRes, venuesRes] = await Promise.all([
      listEvents(),
      listVenues(),
    ])

    if (eventsRes.error) {
      setError(eventsRes.error.message)
      setEvents([])
    } else {
      setEvents(eventsRes.data || [])
    }

    if (!venuesRes.error) {
      setVenues(venuesRes.data || [])
    }

    if (user?.id) {
      const [regsRes, savedRes] = await Promise.all([
        listMyRegistrations(user.id),
        listSavedEvents(user.id),
      ])
      if (!regsRes.error) {
        setRegistrationRows(regsRes.data || [])
        setRegistrations(activeRegistrationIds(regsRes.data))
      }
      if (!savedRes.error) {
        setSaved((savedRes.data || []).map((row) => row.event_id))
      }
    } else {
      setRegistrations([])
      setRegistrationRows([])
      setSaved([])
    }

    setLoading(false)
    return { ok: !eventsRes.error }
  }, [user?.id])

  useEffect(() => {
    setLoading(true)
    refresh()
  }, [refresh])

  // Admin approvals, seats, venues, payments — live across tabs (no manual reload)
  useRealtimeTables(LIVE_TABLES, refresh, {
    channelName: 'es-campus-core',
    debounceMs: 400,
    refreshOnFocus: true,
  })

  const createEventAction = useCallback(
    async (form, uiStatus) => {
      if (!user?.id) return { error: { message: 'Sign in required' } }
      const { data, error: err } = await apiCreateEvent(
        {
          ...form,
          status: uiStatus,
          symbol: String(form.title || 'EV')
            .slice(0, 2)
            .toUpperCase(),
        },
        user.id,
      )
      if (!err && data) {
        await refresh()
      }
      return { data, error: err }
    },
    [user?.id, refresh],
  )

  const setStatusAction = useCallback(
    async (id, uiStatus) => {
      const { data, error: err } = await apiSetEventStatus(id, uiStatus)
      if (!err) await refresh()
      return { data, error: err }
    },
    [refresh],
  )

  const deleteEventAction = useCallback(
    async (id) => {
      const { error: err } = await apiDeleteEvent(id)
      if (!err) await refresh()
      return { error: err }
    },
    [refresh],
  )

  const updateEventAction = useCallback(
    async (id, updates) => {
      const { data, error: err } = await apiUpdateEvent(id, updates)
      if (!err) await refresh()
      return { data, error: err }
    },
    [refresh],
  )

  const postponeEventAction = useCallback(
    async (id, payload) => {
      const { data, error: err, announcement } = await apiPostponeEvent(id, payload)
      if (!err || data) await refresh()
      return { data, error: err, announcement }
    },
    [refresh],
  )

  const extendRegistrationAction = useCallback(
    async (id, payload) => {
      const { data, error: err, notified, extended, announcement } =
        await apiExtendRegistrationDeadline(id, payload)
      if (!err || data) await refresh()
      return { data, error: err, notified, extended, announcement }
    },
    [refresh],
  )

  const cancelEventAction = useCallback(
    async (id, payload) => {
      const { data, error: err, announcement } = await apiCancelEventWithNotice(id, payload)
      if (!err || data) await refresh()
      return { data, error: err, announcement }
    },
    [refresh],
  )

  const duplicateEventAction = useCallback(
    async (event) => {
      if (!user?.id) return { error: { message: 'Sign in required' } }
      return createEventAction(
        {
          title: `${event.title} Copy`,
          description: event.description,
          category: event.category,
          date: event.date,
          time: event.time,
          venue: event.venue,
          capacity: event.capacity,
          art: event.art,
        },
        EVENT_STATUS.DRAFT,
      )
    },
    [user?.id, createEventAction],
  )

  const registerAction = useCallback(
    async (eventId) => {
      if (!eventId) return { error: { message: 'Missing event id' } }
      const { data, error: err } = await apiRegisterForEvent(eventId)
      if (!err) {
        // Optimistic UI so pass/list update even if a later refresh is slow
        setRegistrations((prev) =>
          prev.includes(eventId) ? prev : [...prev, eventId],
        )
        if (data) {
          setRegistrationRows((prev) => {
            const others = (prev || []).filter((r) => r.eventId !== eventId)
            return [data, ...others]
          })
        }
        await refresh()
      }
      return { data, error: err }
    },
    [refresh],
  )

  const cancelRegisterAction = useCallback(
    async (eventId) => {
      const { data, error: err } = await apiCancelRegistration(eventId)
      if (!err) await refresh()
      return { data, error: err }
    },
    [refresh],
  )

  const toggleSaveAction = useCallback(
    async (eventId) => {
      if (!user?.id) return { error: { message: 'Sign in required' } }
      const isSaved = saved.includes(eventId)
      const { error: err } = isSaved
        ? await apiUnsaveEvent(user.id, eventId)
        : await apiSaveEvent(user.id, eventId)
      if (!err) await refresh()
      return { saved: !isSaved, error: err }
    },
    [user?.id, saved, refresh],
  )

  return {
    events,
    setEvents,
    saved,
    setSaved,
    registrations,
    registrationRows,
    setRegistrations,
    venues,
    loading,
    error,
    refresh,
    actions: {
      createEvent: createEventAction,
      setStatus: setStatusAction,
      deleteEvent: deleteEventAction,
      updateEvent: updateEventAction,
      postponeEvent: postponeEventAction,
      extendRegistrationDeadline: extendRegistrationAction,
      cancelEvent: cancelEventAction,
      duplicateEvent: duplicateEventAction,
      register: registerAction,
      cancelRegister: cancelRegisterAction,
      toggleSave: toggleSaveAction,
    },
  }
}

import { useEffect, useRef } from 'react'
import { isSupabaseConfigured, supabase } from '../lib/supabase'

/**
 * Debounced Supabase Realtime (postgres_changes) + optional tab-focus refresh.
 * Safe for multi-tab demos: one channel, many tables, no auth/logic changes.
 *
 * @param {string[]} tables - public table names (Realtime must be enabled in dashboard)
 * @param {() => void} onChange - usually a load/refresh function
 */
export function useRealtimeTables(
  tables,
  onChange,
  {
    channelName = 'es-live',
    debounceMs = 450,
    refreshOnFocus = true,
    enabled = true,
  } = {},
) {
  const cbRef = useRef(onChange)
  cbRef.current = onChange

  const list = (Array.isArray(tables) ? tables : [])
    .map((t) => String(t || '').trim())
    .filter(Boolean)
  const tablesKey = list.slice().sort().join('|')

  useEffect(() => {
    if (!enabled || !isSupabaseConfigured || !tablesKey) return undefined

    let timer = null
    const kick = () => {
      if (timer) window.clearTimeout(timer)
      timer = window.setTimeout(() => {
        try {
          cbRef.current?.()
        } catch (err) {
          console.warn('[useRealtimeTables] refresh failed', err)
        }
      }, debounceMs)
    }

    const name = `${channelName}:${tablesKey}`.slice(0, 120)
    let channel = supabase.channel(name)
    for (const table of list) {
      channel = channel.on(
        'postgres_changes',
        { event: '*', schema: 'public', table },
        kick,
      )
    }

    channel.subscribe((status) => {
      if (status === 'CHANNEL_ERROR') {
        console.warn(
          `[useRealtimeTables] channel error for ${tablesKey} — check Realtime is ON for these tables`,
        )
      }
    })

    const onVis = () => {
      if (!refreshOnFocus) return
      if (document.visibilityState === 'visible') kick()
    }
    if (refreshOnFocus) {
      document.addEventListener('visibilitychange', onVis)
      window.addEventListener('focus', onVis)
    }

    return () => {
      if (timer) window.clearTimeout(timer)
      if (refreshOnFocus) {
        document.removeEventListener('visibilitychange', onVis)
        window.removeEventListener('focus', onVis)
      }
      supabase.removeChannel(channel)
    }
    // list is derived from tablesKey; intentional
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tablesKey, channelName, debounceMs, refreshOnFocus, enabled])
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/
const NAME_RE = /^[\p{L}][\p{L}\s'.-]{1,58}$/u
const MOBILE_PK_RE = /^(\+92|0)?3[0-9]{9}$/

export function normalizeEmail(value) {
  return String(value || '').trim().toLowerCase()
}

export function validatePasswordStrength(password) {
  const p = String(password || '')
  if (!p) return { ok: false, message: 'Password is required.' }
  if (p.length < 8) return { ok: false, message: 'Use at least 8 characters.' }
  if (!/[a-zA-Z]/.test(p)) return { ok: false, message: 'Include at least one letter.' }
  if (!/[0-9]/.test(p)) return { ok: false, message: 'Include at least one number.' }
  if (/\s/.test(p)) return { ok: false, message: 'Password cannot contain spaces.' }
  return { ok: true, message: '' }
}

export function passwordStrengthHints(password) {
  const p = String(password || '')
  return [
    { key: 'len', label: '8+ characters', ok: p.length >= 8 },
    { key: 'letter', label: 'One letter', ok: /[a-zA-Z]/.test(p) },
    { key: 'digit', label: 'One number', ok: /[0-9]/.test(p) },
  ]
}

export function validateLogin({ email, password }) {
  const errors = {}
  const e = normalizeEmail(email)

  if (!e) errors.email = 'Email is required.'
  else if (!EMAIL_RE.test(e)) errors.email = 'Enter a valid email address.'

  if (!password) errors.password = 'Password is required.'
  else if (password.length < 6) errors.password = 'Password must be at least 6 characters.'

  const firstError = errors.email || errors.password || ''
  return { ok: !firstError, errors, firstError }
}

export function validateSignupStep1({ fullName, email, password, intentGuest }) {
  const errors = {}
  const name = String(fullName || '').trim()

  if (!name) errors.fullName = 'Full name is required.'
  else if (name.length < 2) errors.fullName = 'Name must be at least 2 characters.'
  else if (!NAME_RE.test(name)) errors.fullName = 'Use letters only in your name.'

  const e = normalizeEmail(email)
  if (!e) errors.email = 'Email is required.'
  else if (!EMAIL_RE.test(e)) errors.email = 'Enter a valid email address.'

  const pw = validatePasswordStrength(password)
  if (!pw.ok) errors.password = pw.message

  const firstError =
    errors.fullName || errors.email || errors.password || ''
  return { ok: !firstError, errors, firstError }
}

export function validateSignupStep2({ mobile, intentGuest, interests }) {
  const errors = {}
  const phone = String(mobile || '').replace(/[\s-]/g, '')

  if (phone && !MOBILE_PK_RE.test(phone)) {
    errors.mobile = 'Use a valid PK mobile (03XXXXXXXXX).'
  }

  if (!intentGuest && Array.isArray(interests) && interests.length > 8) {
    errors.interests = 'Pick up to 8 interests.'
  }

  const firstError = errors.mobile || errors.interests || ''
  return { ok: !firstError, errors, firstError }
}

export function validateMobile(value, { required = false } = {}) {
  const phone = String(value || '').replace(/[\s-]/g, '')
  if (!phone) {
    return required
      ? { ok: false, message: 'Mobile number is required.' }
      : { ok: true, message: '' }
  }
  if (!MOBILE_PK_RE.test(phone)) {
    return { ok: false, message: 'Use a valid PK mobile (03XXXXXXXXX).' }
  }
  return { ok: true, message: '' }
}

function cssVar(name, fallback) {
  try {
    const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim()
    return v || fallback
  } catch {
    return fallback
  }
}

function hexToRgba(color, alpha = 1) {
  const raw = String(color || '').trim()
  const hex = raw.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i)
  if (hex) {
    let h = hex[1]
    if (h.length === 3) h = h.split('').map((c) => c + c).join('')
    const n = parseInt(h, 16)
    const r = (n >> 16) & 255
    const g = (n >> 8) & 255
    const b = n & 255
    return `rgba(${r},${g},${b},${alpha})`
  }
  if (raw.startsWith('rgb')) {
    const nums = raw.replace(/[^\d.,]/g, '').split(',').map(Number)
    if (nums.length >= 3) return `rgba(${nums[0]},${nums[1]},${nums[2]},${alpha})`
  }
  return `rgba(196,181,253,${alpha})`
}

function readThemePalette() {
  return {
    stageFrom: cssVar('--te-stageFrom', '#0b0d18'),
    stageMid: cssVar('--te-stageMid', '#151936'),
    stageTo: cssVar('--te-stageTo', '#1a1430'),
    ink: cssVar('--te-ink', '#0a0614'),
    text: cssVar('--te-text', '#f4f5ff'),
    muted: cssVar('--te-muted', '#a8aec4'),
    cyan: cssVar('--te-cyan', '#54d8e8'),
    violet: cssVar('--te-violet', '#9a7bff'),
    pink: cssVar('--te-pink', '#cb8beb'),
    neon: cssVar('--te-neon', '#c4ff3e'),
    orbA: cssVar('--te-orbA', '#54d8e8'),
    orbB: cssVar('--te-orbB', '#9a7bff'),
    orbC: cssVar('--te-orbC', '#cb8beb'),
  }
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight) {
  const words = String(text || '').split(/\s+/).filter(Boolean)
  let line = ''
  let cy = y
  for (let i = 0; i < words.length; i += 1) {
    const test = line ? `${line} ${words[i]}` : words[i]
    if (ctx.measureText(test).width > maxWidth && line) {
      ctx.fillText(line, x, cy)
      line = words[i]
      cy += lineHeight
    } else {
      line = test
    }
  }
  if (line) ctx.fillText(line, x, cy)
  return cy
}

function drawDottedField(ctx, width, height, color) {
  const step = 22
  ctx.fillStyle = color
  for (let x = 88; x < width - 88; x += step) {
    for (let y = 88; y < height - 88; y += step) {
      ctx.beginPath()
      ctx.arc(x, y, 1.15, 0, Math.PI * 2)
      ctx.fill()
    }
  }
}

/**
 * @returns {Promise<{ blob: Blob, filename: string }>}
 */
export async function buildCertificateImage({
  studentName,
  eventTitle,
  eventDate,
  issuedOn,
  organizerLabel = 'EventSphere Campus',
}) {
  const width = 1400
  const height = 990
  const canvas = document.createElement('canvas')
  canvas.width = width
  canvas.height = height
  const ctx = canvas.getContext('2d')
  const t = readThemePalette()

  const bg = ctx.createLinearGradient(0, 0, width, height)
  bg.addColorStop(0, t.stageFrom || t.ink)
  bg.addColorStop(0.48, t.stageMid || t.ink)
  bg.addColorStop(1, t.stageTo || t.ink)
  ctx.fillStyle = bg
  ctx.fillRect(0, 0, width, height)

  drawDottedField(ctx, width, height, hexToRgba(t.muted, 0.14))

  ctx.fillStyle = hexToRgba(t.orbA || t.cyan, 0.16)
  ctx.beginPath()
  ctx.arc(220, 180, 170, 0, Math.PI * 2)
  ctx.fill()
  ctx.fillStyle = hexToRgba(t.orbB || t.violet, 0.16)
  ctx.beginPath()
  ctx.arc(1180, 780, 210, 0, Math.PI * 2)
  ctx.fill()
  ctx.fillStyle = hexToRgba(t.orbC || t.pink, 0.1)
  ctx.beginPath()
  ctx.arc(980, 220, 120, 0, Math.PI * 2)
  ctx.fill()

  ctx.strokeStyle = hexToRgba(t.violet, 0.55)
  ctx.lineWidth = 4
  ctx.strokeRect(48, 48, width - 96, height - 96)
  ctx.strokeStyle = hexToRgba(t.cyan, 0.4)
  ctx.lineWidth = 1.5
  ctx.strokeRect(68, 68, width - 136, height - 136)
  ctx.strokeStyle = hexToRgba(t.neon, 0.22)
  ctx.lineWidth = 1
  ctx.strokeRect(84, 84, width - 168, height - 168)

  ctx.fillStyle = t.cyan
  ctx.font = '700 18px system-ui,Segoe UI,sans-serif'
  ctx.textAlign = 'center'
  ctx.fillText('EVENTSPHERE', width / 2, 130)
  ctx.fillStyle = hexToRgba(t.muted, 0.95)
  ctx.font = '500 13px system-ui,Segoe UI,sans-serif'
  ctx.fillText('SMART CAMPUS EVENT & ENGAGEMENT', width / 2, 156)

  ctx.fillStyle = t.text
  ctx.font = '600 42px Georgia, "Times New Roman", serif'
  ctx.fillText('Certificate of Participation', width / 2, 240)

  ctx.fillStyle = hexToRgba(t.muted, 0.95)
  ctx.font = '400 18px system-ui,Segoe UI,sans-serif'
  ctx.fillText('This certifies that', width / 2, 310)

  ctx.fillStyle = t.text
  ctx.font = '700 48px Georgia, "Times New Roman", serif'
  ctx.fillText(String(studentName || 'Participant').slice(0, 48), width / 2, 380)

  ctx.fillStyle = hexToRgba(t.muted, 0.95)
  ctx.font = '400 18px system-ui,Segoe UI,sans-serif'
  ctx.fillText('successfully participated in', width / 2, 440)

  ctx.fillStyle = t.pink || t.violet
  ctx.font = '600 34px Georgia, "Times New Roman", serif'
  wrapText(ctx, String(eventTitle || 'Campus Event').slice(0, 80), width / 2, 500, 980, 42)

  const dateLine = eventDate ? `Event date: ${String(eventDate).slice(0, 10)}` : ''
  const issuedLine = issuedOn
    ? `Issued: ${new Date(issuedOn).toLocaleDateString()}`
    : `Issued: ${new Date().toLocaleDateString()}`
  ctx.fillStyle = hexToRgba(t.muted, 0.9)
  ctx.font = '400 16px system-ui,Segoe UI,sans-serif'
  ctx.fillText([dateLine, issuedLine].filter(Boolean).join('  ·  '), width / 2, 620)

  ctx.strokeStyle = hexToRgba(t.text, 0.22)
  ctx.beginPath()
  ctx.moveTo(280, 780)
  ctx.lineTo(520, 780)
  ctx.moveTo(880, 780)
  ctx.lineTo(1120, 780)
  ctx.stroke()
  ctx.fillStyle = hexToRgba(t.muted, 0.9)
  ctx.font = '500 14px system-ui,Segoe UI,sans-serif'
  ctx.fillText('Organizer', 400, 810)
  ctx.fillText(String(organizerLabel).slice(0, 28), 1000, 810)

  ctx.fillStyle = hexToRgba(t.violet, 0.95)
  ctx.font = '600 12px system-ui,Segoe UI,sans-serif'
  ctx.fillText('Generated by EventSphere · campus student credential', width / 2, 900)

  const blob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/png'))
  const safeTitle = String(eventTitle || 'event')
    .replace(/[^\w\-]+/g, '_')
    .slice(0, 40)
  return {
    blob,
    filename: `EventSphere_Certificate_${safeTitle}.png`,
  }
}

export async function downloadCertificate(opts) {
  const { blob, filename } = await buildCertificateImage(opts)
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  a.click()
  URL.revokeObjectURL(url)
  return { filename }
}

/** Opens a print-friendly dialog (browser → Save as PDF) via hidden iframe. */
export function printCertificate(opts) {
  const name = String(opts.studentName || 'Participant')
  const title = String(opts.eventTitle || 'Campus Event')
  const date = opts.eventDate ? String(opts.eventDate).slice(0, 10) : ''
  const issued = opts.issuedOn
    ? new Date(opts.issuedOn).toLocaleDateString()
    : new Date().toLocaleDateString()
  const t = readThemePalette()

  const html = `<!doctype html><html><head><meta charset="utf-8"/><title>Certificate — ${title}</title>
    <style>
      @page { size: landscape; margin: 14mm; }
      body {
        margin: 0; padding: 28px;
        font-family: Georgia, "Times New Roman", serif;
        text-align: center;
        color: ${t.text};
        background:
          radial-gradient(circle at 1px 1px, ${hexToRgba(t.muted, 0.28)} 1px, transparent 0) 0 0 / 18px 18px,
          linear-gradient(145deg, ${t.stageFrom}, ${t.stageMid}, ${t.stageTo});
        min-height: 100vh;
        box-sizing: border-box;
      }
      .frame {
        border: 3px solid ${hexToRgba(t.violet, 0.7)};
        outline: 1px solid ${hexToRgba(t.cyan, 0.45)};
        outline-offset: 10px;
        padding: 40px 36px;
        max-width: 980px;
        margin: 0 auto;
        background: ${hexToRgba(t.ink, 0.35)};
      }
      .brand { letter-spacing: .22em; font-size: 12px; color: ${t.cyan}; font-family: system-ui,sans-serif; font-weight: 700; }
      .sub { font-family: system-ui,sans-serif; font-size: 11px; color: ${t.muted}; margin-top: 6px; letter-spacing: .08em; }
      h1 { font-size: 34px; margin: 28px 0 10px; color: ${t.text}; }
      .name { font-size: 40px; margin: 24px 0; color: ${t.text}; }
      .event { font-size: 26px; color: ${t.pink || t.violet}; margin: 18px 0; }
      .meta { font-family: system-ui,sans-serif; font-size: 13px; color: ${t.muted}; margin-top: 28px; }
      p { color: ${t.muted}; }
    </style></head><body>
    <div class="frame">
      <div class="brand">EVENTSPHERE</div>
      <div class="sub">SMART CAMPUS EVENT &amp; ENGAGEMENT</div>
      <h1>Certificate of Participation</h1>
      <p>This certifies that</p>
      <div class="name">${name}</div>
      <p>successfully participated in</p>
      <div class="event">${title}</div>
      <div class="meta">${date ? `Event date: ${date} · ` : ''}Issued: ${issued}</div>
    </div>
    </body></html>`

  const iframe = document.createElement('iframe')
  iframe.setAttribute('aria-hidden', 'true')
  iframe.style.cssText =
    'position:fixed;right:0;bottom:0;width:0;height:0;border:0;opacity:0;pointer-events:none'
  document.body.appendChild(iframe)
  const doc = iframe.contentDocument || iframe.contentWindow?.document
  if (!doc) {
    iframe.remove()
    return { error: { message: 'Could not open print dialog' } }
  }
  doc.open()
  doc.write(html)
  doc.close()

  const runPrint = () => {
    try {
      iframe.contentWindow?.focus()
      iframe.contentWindow?.print()
    } finally {
      window.setTimeout(() => iframe.remove(), 1500)
    }
  }
  window.setTimeout(runPrint, 80)
  return { error: null }
}

import { useEffect, useState } from 'react'
import { ASSIGNABLE_ROLES, ROLES } from '../../constants/roles'
import { useAuth } from '../../context/AuthContext'
import { getProfiles, updateProfileRole } from '../../services/profiles'

export default function AdminUsersPage() {
  const { user } = useAuth()
  const [profiles, setProfiles] = useState([])
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)
  const [savingId, setSavingId] = useState(null)

  async function load() {
    setLoading(true)
    setError('')
    const { data, error: err } = await getProfiles()
    if (err) setError(err.message)
    else setProfiles(data || [])
    setLoading(false)
  }

  useEffect(() => {
    load()
  }, [])

  async function changeRole(profile, nextRole) {
    if (profile.role === nextRole) return
    if (profile.id === user.id && nextRole !== ROLES.ADMIN) {
      setError('You cannot demote yourself while signed in as admin.')
      return
    }
    setError('')
    setSavingId(profile.id)
    const { error: err } = await updateProfileRole(profile.id, nextRole)
    setSavingId(null)
    if (err) setError(err.message)
    else await load()
  }

  return (
    <div className="page">
      <header className="page-header">
        <h1>Users</h1>
        <p className="muted">
          Assign roles. Only admins can promote organizers — signup always creates{' '}
          <code>user</code>.
        </p>
      </header>

      {error && <p className="form-error">{error}</p>}

      {loading ? (
        <p className="muted">Loading…</p>
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>Role</th>
                <th>Joined</th>
                <th>Assign</th>
              </tr>
            </thead>
            <tbody>
              {profiles.map((p) => (
                <tr key={p.id}>
                  <td>{p.full_name || '—'}</td>
                  <td>{p.email}</td>
                  <td>
                    <span className={`pill role-${p.role}`}>{p.role}</span>
                  </td>
                  <td>{new Date(p.created_at).toLocaleDateString()}</td>
                  <td>
                    <select
                      className="role-select"
                      value={p.role}
                      disabled={p.id === user.id || savingId === p.id}
                      onChange={(e) => changeRole(p, e.target.value)}
                      aria-label={`Role for ${p.email}`}
                    >
                      {ASSIGNABLE_ROLES.map((r) => (
                        <option key={r} value={r}>
                          {r}
                        </option>
                      ))}
                    </select>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { Link, Navigate, useLocation, useNavigate } from 'react-router-dom'
import { homePathForRole } from '../../constants/roles'
import { useAuth } from '../../context/AuthContext'
import { sendEmailOtp, verifyEmailOtp } from '../../services/emailOtp'
import { isEmailJsConfigured } from '../../lib/emailjs'

export default function VerifyEmailPage() {
  const { profile, user, loading, signOut, refreshProfile } = useAuth()
  const navigate = useNavigate()
  const location = useLocation()
  const [otp, setOtp] = useState('')
  const [busy, setBusy] = useState(false)
  const [sending, setSending] = useState(false)
  const [message, setMessage] = useState('')
  const [error, setError] = useState('')
  const autoSent = useRef(false)

  useEffect(() => {
    if (user) refreshProfile()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user])

  // Auto-send OTP after signup (or when landing here unverified)
  useEffect(() => {
    if (!user || !profile || profile.email_verified || autoSent.current) return
    if (!isEmailJsConfigured) {
      setError('EmailJS is not configured in .env')
      return
    }

    autoSent.current = true
    setSending(true)
    setError('')
    sendEmailOtp({
      email: profile.email || user.email,
      fullName: profile.full_name,
    })
      .then(({ error: err }) => {
        if (err) {
          setError(err.message)
          autoSent.current = false
        } else {
          setMessage('OTP sent to your email. Valid for 10 minutes.')
        }
      })
      .finally(() => setSending(false))
  }, [user, profile, location.key])

  if (loading || (user && !profile)) {
    return (
      <div className="page-center">
        <p className="muted">Loading…</p>
      </div>
    )
  }

  if (!user) {
    return <Navigate to="/login" replace />
  }

  if (profile?.email_verified) {
    return <Navigate to={homePathForRole(profile.role)} replace />
  }

  async function resend() {
    setSending(true)
    setError('')
    setMessage('')
    const { error: err, toEmail } = await sendEmailOtp({
      email: profile?.email || user?.email,
      fullName: profile?.full_name || user?.user_metadata?.full_name,
    })
    setSending(false)
    if (err) {
      setError(err.message)
      return
    }
    setMessage(`New OTP sent to ${toEmail}. Check inbox/spam.`)
    await refreshProfile()
  }

  async function handleVerify(e) {
    e.preventDefault()
    setBusy(true)
    setError('')
    setMessage('')
    const { ok, error: err } = await verifyEmailOtp(otp)
    if (err) {
      setBusy(false)
      setError(err.message)
      return
    }
    if (!ok) {
      setBusy(false)
      setError('Invalid or expired OTP. Try again or resend.')
      return
    }
    await refreshProfile()
    setBusy(false)
    setMessage('Email verified.')
  }

  return (
    <div className="auth-page">
      <form className="auth-card" onSubmit={handleVerify}>
        <p className="brand">SYNVEX FORGE</p>
        <h1>Enter OTP</h1>
        <p className="muted">
          6-digit code for <strong>{profile?.email || user?.email}</strong>
        </p>

        {sending && <p className="muted">Sending OTP…</p>}

        {!isEmailJsConfigured && (
          <p className="banner warn">
            EmailJS keys missing in <code>.env</code>.
          </p>
        )}

        <label>
          OTP code
          <input
            type="text"
            inputMode="numeric"
            autoComplete="one-time-code"
            pattern="[0-9]{6}"
            maxLength={6}
            placeholder="123456"
            value={otp}
            onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
            required
          />
        </label>

        {error && <p className="form-error">{error}</p>}
        {message && <p className="form-ok">{message}</p>}

        <button type="submit" className="btn btn-primary" disabled={busy || otp.length !== 6}>
          {busy ? 'Checking…' : 'Verify OTP'}
        </button>

        <button type="button" className="btn btn-ghost" disabled={sending} onClick={resend}>
          {sending ? 'Sending…' : 'Resend OTP'}
        </button>

        <p className="auth-foot">
          <button
            type="button"
            className="btn btn-ghost btn-sm"
            onClick={async () => {
              await signOut()
              navigate('/', { replace: true })
            }}
          >
            Sign out
          </button>
          {' · '}
          <Link to="/">Home</Link>
        </p>
      </form>
    </div>
  )
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { createPortal } from 'react-dom'
import { Link, useLocation } from 'wouter'
import {
  CalendarDays,
  Ticket,
  ShieldCheck,
  ArrowRight,
  Loader2,
  Download,
  Copy,
  X,
} from 'lucide-react'
import { useAuth } from '@/context/AuthContext'
import QrPass from '@/components/phase-c/QrPass'
import GuestRegisterFlow from '@/components/guest/GuestRegisterFlow'
import AttendeeBadgeCard from '@/components/shared/AttendeeBadgeCard'
import PublicShell from '@/pages/public/PublicShell'
import { listMyRegistrations } from '@/services/registrations'
import { getEvent } from '@/services/events'
import { applyReferralCode, ensureMyReferralCode } from '@/services/growth'
import { buildAttendancePayload } from '@/lib/qrPayload'
import { formatEventSchedule, isEventEnded } from '@/lib/eventDate'
import { PAYMENT_STATUS, PAYMENT_STATUS_LABEL, REGISTRATION_STATUS } from '@/constants/domain'
import { useMascotLibrary } from '@/context/MascotLibraryContext'
import { PublicMascotBadge, resolvePublicMascot } from '@/components/public/PublicMascotScene'

const ACTIVE = new Set([
  REGISTRATION_STATUS.CONFIRMED,
  REGISTRATION_STATUS.WAITLIST,
  REGISTRATION_STATUS.PENDING,
  REGISTRATION_STATUS.PENDING_PAYMENT,
])

function hasPassQr(row) {
  if (!row) return false
  if (row.status === REGISTRATION_STATUS.PENDING_PAYMENT) return false
  if (row.paymentStatus === PAYMENT_STATUS.PENDING || row.paymentStatus === PAYMENT_STATUS.EXPIRED) return false
  return (
    row.status === REGISTRATION_STATUS.CONFIRMED ||
    row.status === REGISTRATION_STATUS.PENDING ||
    row.paymentStatus === PAYMENT_STATUS.NOT_REQUIRED ||
    row.paymentStatus === PAYMENT_STATUS.PAID ||
    row.paymentStatus === PAYMENT_STATUS.PARTIALLY_REFUNDED
  )
}

export default function GuestHub({ onLogout, setToast }) {
  const { user, profile, refreshProfile } = useAuth()
  const { enabledLibrary } = useMascotLibrary()
  const hubMascot = resolvePublicMascot('plane', enabledLibrary)
  const [path, setLocation] = useLocation()
  const [regs, setRegs] = useState([])
  const [eventsById, setEventsById] = useState({})
  const [loading, setLoading] = useState(true)
  const [friendCode, setFriendCode] = useState('')
  const [myReferral, setMyReferral] = useState('')
  const [walletId, setWalletId] = useState(null)

  const eventFromQuery = useMemo(() => {
    try {
      const q = new URLSearchParams(path.includes('?') ? path.split('?')[1] : window.location.search)
      return q.get('event') || ''
    } catch {
      return ''
    }
  }, [path])

  const identity = useMemo(() => {
    const name = profile?.full_name || 'Guest'
    const initials = String(name)
      .split(/\s+/)
      .map((p) => p[0])
      .join('')
      .slice(0, 2)
      .toUpperCase()
    return {
      name,
      email: profile?.email || user?.email,
      avatarUrl: profile?.avatar_url,
      initials,
    }
  }, [profile, user])

  const attendee = identity.name

  const load = useCallback(async () => {
    if (!user?.id) return
    setLoading(true)
    const { data, error } = await listMyRegistrations(user.id)
    if (error) setToast?.(error.message)
    const rows = data || []
    setRegs(rows)

    const ids = [...new Set(rows.map((r) => r.eventId || r.event_id).filter(Boolean))]
    const map = {}
    await Promise.all(
      ids.map(async (id) => {
        const { data: ev } = await getEvent(id)
        if (ev) map[id] = ev
      }),
    )
    setEventsById(map)

    const ref = await ensureMyReferralCode(user.id)
    if (ref.data?.referral_code) setMyReferral(ref.data.referral_code)

    setLoading(false)
  }, [user?.id, setToast])

  useEffect(() => {
    load()
  }, [load])

  useEffect(() => {
    if (!walletId) return undefined
    const onKey = (e) => {
      if (e.key === 'Escape') setWalletId(null)
    }
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    window.addEventListener('keydown', onKey)
    return () => {
      document.body.style.overflow = prev
      window.removeEventListener('keydown', onKey)
    }
  }, [walletId])

  const applyRef = async () => {
    if (!user?.id) return
    const { error } = await applyReferralCode(user.id, friendCode)
    if (error) setToast?.(error.message)
    else {
      setToast?.('Referral applied')
      setFriendCode('')
      await refreshProfile?.()
    }
  }

  const clearEventQuery = () => {
    setLocation('/guest')
  }

  const onRegisterComplete = async () => {
    clearEventQuery()
    await load()
  }

  const activeRegs = regs.filter((r) => ACTIVE.has(r.status))
  const passRegs = activeRegs.filter((r) => hasPassQr(r))
  const walletReg = passRegs.find((r) => String(r.eventId || r.event_id) === String(walletId))
  const walletEvent = walletReg ? eventsById[walletReg.eventId || walletReg.event_id] : null

  return (
    <PublicShell
      variant="hub"
      hideTitle
      identity={identity}
      onLogout={onLogout}
    >
      <div className="es-guest-hub-content" data-testid="guest-hub">
        <section className="surface es-guest-hub__identity">
          <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16 }}>
            <div style={{ minWidth: 0 }}>
              <div className="es-guest-hub__badge">
                <ShieldCheck size={12} /> Public guest
              </div>
              <h1 className="display" style={{ margin: '10px 0 6px', fontSize: 26 }}>
                {profile?.full_name || 'Guest'}
              </h1>
              <p className="muted" style={{ margin: 0, fontSize: 13 }}>
                {profile?.email || user?.email}
                {profile?.username ? ` · @${profile.username}` : ''}
              </p>
              <p className="subtle" style={{ margin: '8px 0 0', fontSize: 12 }}>
                Your secure hub — registrations and QR passes only. No campus dashboard access.
              </p>
            </div>
            <PublicMascotBadge mascot={hubMascot} size="md" />
          </div>
        </section>

        {eventFromQuery ? (
          <GuestRegisterFlow
            eventId={eventFromQuery}
            user={user}
            setToast={setToast}
            onComplete={onRegisterComplete}
            onCancel={clearEventQuery}
          />
        ) : null}

        <section className="surface" style={{ padding: 22 }}>
          <div className="eyebrow">Referral</div>
          <h2 className="display" style={{ margin: '8px 0 12px', fontSize: 20 }}>Student reference</h2>
          <p className="muted" style={{ fontSize: 12, marginBottom: 12 }}>
            If a campus student invited you, enter their referral code (optional).
          </p>
          {myReferral ? (
            <p className="subtle" style={{ fontSize: 11, marginBottom: 10 }}>
              Your guest code: <code>{myReferral}</code>
            </p>
          ) : null}
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <input
              className="input"
              value={friendCode}
              onChange={(e) => setFriendCode(e.target.value.toUpperCase())}
              placeholder="STUDENT CODE"
              data-testid="input-guest-referral"
              style={{ flex: 1, minWidth: 160 }}
            />
            <button type="button" className="btn" onClick={applyRef} data-testid="button-guest-apply-referral">
              Apply
            </button>
          </div>
        </section>

        <section className="es-guest-passes" data-testid="guest-passes">
          <div className="eyebrow">Your credentials</div>
          <h2 className="display" style={{ margin: '8px 0 6px', fontSize: 22 }}>
            <Ticket size={18} style={{ verticalAlign: -3, marginRight: 8 }} />
            My passes
          </h2>
          <p className="muted" style={{ fontSize: 12, marginBottom: 14 }}>
            Same door wallet as campus students — open <strong>Wallet view</strong> for a large QR the organizer can scan.
          </p>

          {loading ? (
            <p className="muted">
              <Loader2 size={14} style={{ animation: 'spin 0.9s linear infinite', verticalAlign: -2, marginRight: 6 }} />
              Loading passes…
            </p>
          ) : null}

          {!loading && !activeRegs.length ? (
            <div className="surface es-guest-hub__empty" style={{ padding: 22 }}>
              <p className="muted" style={{ margin: 0 }}>No active public registrations yet.</p>
              <Link href="/events" className="btn btn-primary" style={{ marginTop: 12 }}>
                Find public events <ArrowRight size={14} />
              </Link>
            </div>
          ) : null}

          {!loading && activeRegs.length ? (
            <div className="grid-2 stagger es-guest-passes__grid">
              {activeRegs.map((r) => {
                const eid = r.eventId || r.event_id
                const ev = eventsById[eid]
                const ended = ev ? isEventEnded(ev) : false
                const showQr = hasPassQr(r)
                const payload = buildAttendancePayload({
                  eventId: eid,
                  studentId: user?.id,
                  token: r.id || 'pass',
                })
                const payLabel =
                  r.paymentStatus && r.paymentStatus !== PAYMENT_STATUS.NOT_REQUIRED
                    ? PAYMENT_STATUS_LABEL[r.paymentStatus] || r.paymentStatus
                    : 'Free'
                const statusLabel = String(r.status || '').replace(/_/g, ' ')

                return (
                  <div className="surface pass" key={r.id || `${eid}-${r.status}`} data-testid={`card-guest-pass-${eid}`}>
                    <div className="pass-top">
                      <div className="eyebrow">EventSphere · Guest · {payLabel}</div>
                      <h2 className="display" style={{ fontSize: 25, margin: '16px 0 6px' }}>
                        {ev?.title || 'Event'}
                      </h2>
                      <div className="muted" style={{ fontSize: 11 }}>
                        {ev ? `${ev.date || ''} · ${ev.venue || ''}` : '—'}
                        {' · '}
                        <span style={{ textTransform: 'capitalize' }}>{statusLabel}</span>
                        {ended ? ' · ended' : ''}
                      </div>
                      {ev ? (
                        <p className="subtle" style={{ margin: '8px 0 0', fontSize: 11 }}>
                          <CalendarDays size={11} style={{ verticalAlign: -1, marginRight: 4 }} />
                          {formatEventSchedule(ev)}
                        </p>
                      ) : null}
                    </div>
                    <div className="pass-bottom">
                      <div>
                        <div className="subtle" style={{ fontSize: 9, letterSpacing: '.12em' }}>ATTENDEE</div>
                        <strong style={{ display: 'block', marginTop: 5 }}>{attendee}</strong>
                        <div className="subtle mono" style={{ marginTop: 16, fontSize: 10 }}>
                          REG · ES-{String(eid).slice(0, 4).toUpperCase()}
                        </div>
                      </div>
                      {showQr ? (
                        <QrPass
                          eventId={eid}
                          studentId={user?.id}
                          token={r.id || 'pass'}
                          size={96}
                          label={`Guest QR pass for ${ev?.title || 'event'}`}
                        />
                      ) : (
                        <span className="muted" style={{ fontSize: 11, maxWidth: 120, textAlign: 'right' }}>
                          Pass when confirmed / paid
                        </span>
                      )}
                    </div>
                    {showQr ? (
                      <div style={{ padding: '0 24px 20px', display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                        <button
                          className="btn btn-primary"
                          type="button"
                          onClick={() => setWalletId(eid)}
                          data-testid={`button-guest-wallet-${eid}`}
                        >
                          Wallet view
                        </button>
                        <button
                          className="btn"
                          type="button"
                          onClick={() => {
                            navigator.clipboard?.writeText(payload)
                            setToast?.('QR payload copied')
                          }}
                          data-testid={`button-guest-copy-pass-${eid}`}
                        >
                          <Download size={14} /> Copy QR payload
                        </button>
                        <Link href={`/events/${eid}`} className="btn btn-quiet">
                          View event
                        </Link>
                      </div>
                    ) : (
                      <div style={{ padding: '0 24px 20px' }}>
                        <Link href={`/events/${eid}`} className="btn btn-quiet">
                          View event
                        </Link>
                      </div>
                    )}
                    {showQr ? (
                      <div style={{ padding: '0 24px 18px' }}>
                        <AttendeeBadgeCard
                          name={attendee}
                          eventTitle={ev?.title || 'Event'}
                          roleLabel="Public guest"
                          eventDate={`${ev?.date || ''} · ${ev?.time || ''}`}
                          venue={ev?.venue}
                          setToast={setToast}
                        />
                      </div>
                    ) : null}
                  </div>
                )
              })}
            </div>
          ) : null}
        </section>
      </div>

      {walletEvent && walletReg
        ? createPortal(
            <div
              className="pass-wallet-overlay"
              role="dialog"
              aria-modal="true"
              aria-labelledby="guest-pass-wallet-title"
              onMouseDown={(e) => e.target === e.currentTarget && setWalletId(null)}
            >
              <div className="pass-wallet-sheet">
                <div className="pass-wallet-bar">
                  <span className="eyebrow" style={{ color: 'inherit' }}>EventSphere wallet · Guest</span>
                  <button className="icon-btn" type="button" onClick={() => setWalletId(null)} aria-label="Close wallet view">
                    <X size={18} />
                  </button>
                </div>
                <h2 id="guest-pass-wallet-title" className="display" style={{ fontSize: 28, margin: '8px 0 6px', color: '#f4f5ff' }}>
                  {walletEvent.title}
                </h2>
                <p className="muted" style={{ color: '#c9cbe0', margin: 0 }}>
                  {walletEvent.date} · {walletEvent.venue}
                </p>
                <div className="pass-wallet-qr">
                  <QrPass
                    eventId={walletEvent.id}
                    studentId={user?.id}
                    token={walletReg.id || 'pass'}
                    size={220}
                    label={`Fullscreen guest QR for ${walletEvent.title}`}
                  />
                </div>
                <p style={{ color: '#f4f5ff', fontWeight: 600, margin: '18px 0 4px' }}>{attendee}</p>
                <p className="subtle" style={{ color: '#aeb1c8', fontSize: 12, margin: 0 }}>
                  Hold phone steady for organizer scan · Esc to close
                </p>
                <button
                  className="btn"
                  type="button"
                  style={{ marginTop: 18, width: '100%' }}
                  onClick={() => {
                    const payload = buildAttendancePayload({
                      eventId: walletEvent.id,
                      studentId: user?.id,
                      token: walletReg.id || 'pass',
                    })
                    navigator.clipboard?.writeText(payload)
                    setToast?.('QR payload copied')
                  }}
                >
                  <Copy size={14} /> Copy payload
                </button>
              </div>
            </div>,
            document.body,
          )
        : null}
    </PublicShell>
  )
}

import { useCallback, useEffect, useState } from 'react'
